    var avoidO=0;
    for(var i=0;i<9;i++){
      var d=rays[i],a=RA[i];
      if(d>=10)continue;
      var w=(10-d)/10;w*=w*(1-Math.abs(a)/110);
      if(a>0)avoidO-=w*0.25;else if(a<0)avoidO+=w*0.25;
    }
    if(fwdClear<8){if(sideL>sideR)avoidO+=0.5*(1-fwdClear/8);else avoidO-=0.5*(1-fwdClear/8)}
    if(edgeAng!==null&&edgeF>0)avoidO+=0.3*edgeF*clamp(angD(edgeAng,heading)/45,-1,1);
    avoidO=clamp(avoidO,-2,2);

    /* ===== HELPERS ===== */
    function wc(side,vd){
      var va=side===0?vL:vR,g=mem.g[side];
      if(!isFinite(g)||g<0.3)g=3;
      var c=vd/g+(vd-va)*0.2/g;
      if(Math.abs(vd)<0.05)c=-va*0.15/g;
      return clamp(c,-1,1);
    }

    function drTo(tx,ty,maxV,arrR){
      tx=clamp(tx,3,mem.sz-3);ty=clamp(ty,3,mem.sz-3);
      var d=dist(mem.xE,mem.yE,tx,ty);
      if(d<arrR)return{a:1,vl:0,vr:0,d:d};
      var br=Math.atan2(ty-mem.yE,tx-mem.xE)*180/Math.PI;
      var hErr=angD(br,heading);
      var v=Math.min(maxV,d*0.5,safeV);
      if(Math.abs(hErr)>90)v=0;
      else if(Math.abs(hErr)>60)v=Math.min(v,0.3);
      else if(Math.abs(hErr)>30)v=Math.min(v,0.8);
      else if(Math.abs(hErr)>15)v=Math.min(v,1.5);
      if(d<arrR+3)v=Math.min(v,d*0.3);
      var o=clamp(hErr*0.02,-1,1)+avoidO;
      o=clamp(o,-1.5,1.5);
      var vl=v-o*0.3,vr=v+o*0.3;
      var m=Math.max(Math.abs(vl),Math.abs(vr),0.001);
      if(m>2.8){vl*=2.8/m;vr*=2.8/m}
      return{a:0,vl:vl,vr:vr,d:d};
    }

    function hold(hx,hy,maxV){
      var ex=hx-mem.xE,ey=hy-mem.yE,d=Math.sqrt(ex*ex+ey*ey);
      var v=clamp(d*0.15,0,maxV);
      v=clamp(v-(vL+vR)*0.3,-maxV,maxV);
      var br=Math.atan2(ey,ex)*180/Math.PI;
      var o=0;if(d>0.3)o=clamp(angD(br,heading)*0.01,-0.12,0.12);
      return{vl:clamp(v-o*0.3,-maxV,maxV),vr:clamp(v+o*0.3,-maxV,maxV)};
    }

    function siteXY(){
      if(!obs.site)return null;
      var sd=nz(obs.site.distance,0),sb=nz(obs.site.bearing,0);
      return{x:mem.xE+sd*Math.cos((heading+sb)*Math.PI/180),y:mem.yE+sd*Math.sin((heading+sb)*Math.PI/180)};
    }

    /* ===== URGENCY ===== */
    var dBase=dist(mem.xE,mem.yE,mem.bx,mem.by);
    var tHome=dBase/Math.max(0.5,spd);
    var eHome=dBase*mem.eM*1.5+0.01;
    var needRet=(timeLeft<tHome*1.5+30)||(batt<eHome*1.5+0.02)||(carried>=mem.cap);

    /* ===== OPPORTUNISTIC SAMPLING ===== */
    if(obs.site&&nz(obs.site.distance,99)<8&&carried<mem.cap&&mem.st!=='drill'&&mem.st!=='dock'&&mem.st!=='approach'&&!needRet){
      var sp=siteXY();
      if(sp){
        var bm=null,bd=1e9;
        for(var i=0;i<mem.tg.length;i++){
          var g2=mem.tg[i];if(g2.done)continue;
          var dd=dist(sp.x,sp.y,g2.hx,g2.hy);
          if(dd<bd){bd=dd;bm=g2}
        }
        if(bm&&bd<30){
          bm.ax=sp.x;bm.ay=sp.y;bm.found=true;
          if(obs.site.value!=null)bm.val=nz(obs.site.value,bm.est);
          mem.cur=bm;
        }else{
          var nc={id:mem.tg.length,hx:sp.x,hy:sp.y,
            est:Math.max(0.1,nz(obs.site.value,1)),
            val:nz(obs.site.value,null),done:false,found:true,ax:sp.x,ay:sp.y};
          mem.tg.push(nc);mem.cur=nc;
        }
      }
      mem.st='approach';mem.lpT=t;mem.lpD=1e9;
    }

    /* ===== STATE MACHINE ===== */
    var vl=0,vr=0;

    if(mem.st==='plan'){
      if(needRet){mem.st='ret';mem.cur=null;mem.lpT=t;mem.lpD=1e9}
      else{
        var best=null,bs=-1;
        for(var i=0;i<mem.tg.length;i++){
          var g=mem.tg[i];if(g.done)continue;
          var tx=g.ax!=null?g.ax:g.hx,ty=g.ay!=null?g.ay:g.hy;
          var d1=dist(mem.xE,mem.yE,tx,ty),d2=dist(tx,ty,mem.bx,mem.by);
          if((d1+d2)/1.5+15>timeLeft*0.7)continue;
          if((d1+d2)*mem.eM*1.3+0.015>batt*0.7)continue;
          var val=g.val!=null?g.val:g.est;
          var sc=val/(d1+15);
          if(sc>bs){bs=sc;best=g}
        }
        if(best){
          mem.cur=best;
          mem.wp={x:best.ax!=null?best.ax:best.hx,y:best.ay!=null?best.ay:best.hy};
          mem.st='goto';mem.lpT=t;mem.lpD=1e9;
        }else{mem.st='ret';mem.lpT=t;mem.lpD=1e9}
      }
    }

    if(mem.st==='goto'){
      if(!mem.cur||mem.cur.done||!mem.wp){mem.st='plan'}
      else{
        var d=drTo(mem.wp.x,mem.wp.y,2.2,5);
        vl=d.vl;vr=d.vr;
        if(d.a||d.d<5){
          mem.st='search';mem.sc={x:mem.xE,y:mem.yE};
          mem.sA=0;mem.sR=10;mem.swp=null;mem.st0=t;mem.lpT=t;mem.lpD=1e9;
        }else{
          if(d.d<mem.lpD-1){mem.lpD=d.d;mem.lpT=t}
          if(t-mem.lpT>30){mem.st='rec';mem.rT=t;mem.rD=(sideL>sideR)?1:-1}
        }
      }
    }

    if(mem.st==='search'){
      if(!mem.sc){mem.st='plan'}
      else if(obs.site!=null&&nz(obs.site.distance,99)<8&&carried<mem.cap){
        mem.st='approach';mem.lpT=t;mem.lpD=1e9;
      }else{
        var sci=nz(obs.science,0);
        var timeout=sci>0.1?35:(sci>0.001?25:10);
        if(t-mem.st0>timeout){
          if(mem.cur)mem.cur.done=true;mem.st='plan';
        }else{
          if(!mem.swp){
            mem.sA+=60;
            if(mem.sA>=360){mem.sA=0;mem.sR=Math.min(mem.sR+10,28)}
            mem.swp={x:clamp(mem.sc.x+mem.sR*Math.cos(mem.sA*Math.PI/180),3,mem.sz-3),
                     y:clamp(mem.sc.y+mem.sR*Math.sin(mem.sA*Math.PI/180),3,mem.sz-3)};
          }
          var d=drTo(mem.swp.x,mem.swp.y,1.5,2);vl=d.vl;vr=d.vr;
          if(d.a)mem.swp=null;
        }
      }
    }

    if(mem.st==='approach'){
      if(!obs.site||nz(obs.site.distance,99)>=8){
        mem.st='search';mem.sc={x:mem.xE,y:mem.yE};
        mem.sA=0;mem.sR=5;mem.swp=null;mem.st0=t-20;
      }else{
        var sd=nz(obs.site.distance,99),sb=nz(obs.site.bearing,0);
        var sx=mem.xE+sd*Math.cos((heading+sb)*Math.PI/180),
            sy=mem.yE+sd*Math.sin((heading+sb)*Math.PI/180);
        if(mem.cur){
          mem.cur.ax=sx;mem.cur.ay=sy;mem.cur.found=true;
          if(obs.site.value!=null)mem.cur.val=nz(obs.site.value,mem.cur.est);
        }
        if(sd<1.5&&spd<0.12){
          mem.st='drill';mem.dP={x:mem.xE,y:mem.yE};mem.dS=t;
        }else if(sd<1.5){
          vl=-0.3*vL;vr=-0.3*vR;
        }else{
          var d=drTo(sx,sy,1.0,1.3);vl=d.vl;vr=d.vr;
          if(t-mem.lpT>25){mem.st='rec';mem.rT=t;mem.rD=1}
        }
      }
    }

    if(mem.st==='drill'){
      if(!mem.dP){mem.dP={x:mem.xE,y:mem.yE};mem.dS=t}
      var hp=hold(mem.dP.x,mem.dP.y,0.18);vl=hp.vl;vr=hp.vr;
      if(Math.abs((vL+vR)/2)<0.13)out.drill=true;
      var drl=nz(obs.drilling,0);
      if(drl>=5.95||carried>mem.dC){
        if(mem.cur){mem.cur.done=true}
        mem.dC=carried;mem.st='plan';out.drill=false;
      }else if(t-mem.dS>35){
        if(mem.cur)mem.cur.done=true;mem.st='plan';out.drill=false;
      }
    }

    if(mem.st==='ret'){
      if(dBase<3){mem.st='dock';mem.dT2=0}
      else{
        var tx=mem.bx,ty=mem.by;
        if(obs.beacon!=null){
          var bd=nz(obs.beacon.distance,99),bb=nz(obs.beacon.bearing,0);
          if(bd<30){tx=mem.xE+bd*Math.cos((heading+bb)*Math.PI/180);ty=mem.yE+bd*Math.sin((heading+bb)*Math.PI/180)}
        }
        var d=drTo(tx,ty,2.2,2.5);vl=d.vl;vr=d.vr;
        if(dBase<mem.lpD-1){mem.lpD=dBase;mem.lpT=t}
        if(t-mem.lpT>30){mem.st='rec';mem.rT=t;mem.rD=1}
      }
    }

    if(mem.st==='dock'){
      if(obs.docked||dBase<3){
        vl=-0.1*vL;vr=-0.1*vR;mem.dT2+=dt;
        if(batt>0.9||timeLeft<80||mem.dT2>30){
          mem.st='plan';mem.dT2=0;mem.lpT=t;mem.lpD=1e9;
        }
      }else{
        mem.dT2=0;
        var d=drTo(mem.bx,mem.by,1.0,2);vl=d.vl;vr=d.vr;
      }
    }

    if(mem.st==='rec'){
      var rt=t-mem.rT;
      if(rt<1.2){vl=-0.8;vr=-0.8}
      else if(rt<3.2){vl=-0.8*mem.rD;vr=0.8*mem.rD}
      else{mem.st='plan';mem.lpT=t;mem.lpD=1e9}
    }

    if(obs.bumped&&mem.st!=='drill'&&mem.st!=='dock'&&t-mem.rT>5){
      mem.st='rec';mem.rT=t;mem.rD=(sideL>sideR)?1:-1;
    }

    out.left=wc(0,vl);out.right=wc(1,vr);
    mem.uP[0]=out.left;mem.uP[1]=out.right;
    return out;
  }catch(e){return{left:0,right:0,drill:false}}
}

function act(obs, mem) {
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const rad = Math.PI / 180;
  if (!mem || typeof mem !== "object") mem = {};

  if (!mem._ready) {
    const mission = obs.mission || {};
    let w = 400;
    let h = 400;
    if (typeof mission.size === "number") {
      w = mission.size;
      h = mission.size;
    } else if (mission.size && typeof mission.size === "object") {
      w = num(mission.size.width, num(mission.size.x, 400));
      h = num(mission.size.height, num(mission.size.y, 400));
    } else {
      w = num(mission.width, 400);
      h = num(mission.height, 400);
    }
    const b = mission.base || { x: 200, y: 200 };
    mem.mapW = w;
    mem.mapH = h;
    mem.baseX = num(b.x, w * 0.5);
    mem.baseY = num(b.y, h * 0.5);
    mem.capacity = Math.max(1, num(mission.capacity, 5));
    mem.totalSeconds = num(mission.seconds, 1200);
    mem.hints = [];
    const hs = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const q = hs[i] || {};
      const x = num(q.x, NaN);
      const y = num(q.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      let v = num(q.estimate, num(q.value, 1));
      if (!(v > 0)) v = 0.2;
      mem.hints.push({
        x: clamp(x, 2, w - 2),
        y: clamp(y, 2, h - 2),
        value: v,
        status: 0,
        blockedUntil: 0
      });
    }
    mem._ready = true;
    mem.clock = 0;
    mem.bias = 0;
    mem.burnBase = 0.0007;
    mem.energyBucket = 0;
    mem.distBucket = 0;
    mem.posX = num(obs.x, mem.baseX);
    mem.posY = num(obs.y, mem.baseY);
    mem.rawPrevX = mem.posX;
    mem.rawPrevY = mem.posY;
    mem.gpsFreezeCount = 0;
    mem.gpsFrozen = false;
    mem.deadAccX = 0;
    mem.deadAccY = 0;
    mem.calX = mem.posX;
    mem.calY = mem.posY;
    mem.calT = 0;
    mem.calN = 0;
    mem.calStraight = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.lastHeadRaw = undefined;
    mem.prevBattery = num(obs.battery, 1);
    mem.prevCarried = num(obs.carried, 0);
    mem.prevCarriedValue = num(obs.carriedValue, 0);
    mem.activeHint = null;
    mem.activeFree = null;
    mem.search = null;
    mem.lastLocalSearch = -1000;
    mem.gridVisited = {};
    mem.siteGoals = [];
    mem.nextSiteId = 1;
    mem.liveSiteId = null;
    mem.sampling = false;
    mem.sampleSiteId = null;
    mem.sampleStart = 0;
    mem.sampleX = mem.posX;
    mem.sampleY = mem.posY;
    mem.stillTicks = 0;
    mem.holdI = 0;
    mem.returning = false;
    mem.motorI = [0, 0];
    mem.lastSet = [0, 0];
    mem.lastBumped = false;
    mem.bumpCount = 0;
    mem.recoverUntil = 0;
    mem.recoverSign = 1;
    mem.navKey = "";
    mem.navBestDist = 1e9;
    mem.navProgressT = 0;
    mem.lastSteer = 0;
    mem.sandUntil = 0;
    mem.slipTicks = 0;
    mem.rayLast = null;
    mem.rayStale = [];
    mem.rayDisabled = [];
    mem.rayTravel = 0;
    mem.maxRayTravel = 0;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.siteGoals)) mem.siteGoals = [];
  if (!mem.gridVisited) mem.gridVisited = {};
  if (!Array.isArray(mem.motorI)) mem.motorI = [0, 0];
  if (!Array.isArray(mem.lastSet)) mem.lastSet = [0, 0];

  const reportedT = num(obs.t, mem.clock || 0);
  let dt = 0.1;
  if (mem._lastT !== undefined) {
    const td = reportedT - mem._lastT;
    if (td > 0.015 && td < 0.7) dt = td;
  }
