  const clock = mem.clock;

  const xRaw = num(obs.x, mem.posX);
  const yRaw = num(obs.y, mem.posY);
  const headingRaw = num(obs.heading, 0);
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const wheelAbs = (Math.abs(wl) + Math.abs(wr)) * 0.5;
  const wheelAvg = (wl + wr) * 0.5;
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;

  if (mem.lastHeadRaw !== undefined) {
    const dh = wrap(headingRaw - mem.lastHeadRaw);
    const expected = (wr - wl) / 0.6 * dt / rad;
    const mismatch = wrap(dh - expected);
    if (Math.abs(mismatch) > 60 && Math.abs(expected) < 40) {
      mem.bias = wrap(mem.bias + mismatch);
    }
  }
  mem.lastHeadRaw = headingRaw;
  let headingTrue = wrap(headingRaw - num(mem.bias, 0));

  const oldPX = num(mem.posX, xRaw);
  const oldPY = num(mem.posY, yRaw);
  const rawStep = dist(xRaw, yRaw, num(mem.rawPrevX, xRaw), num(mem.rawPrevY, yRaw));
  let stepX = 0;
  let stepY = 0;
  if (!Number.isFinite(mem.posX) || !Number.isFinite(mem.posY)) {
    mem.posX = xRaw;
    mem.posY = yRaw;
    mem.rawPrevX = xRaw;
    mem.rawPrevY = yRaw;
  } else if (mem.gpsFrozen) {
    if (rawStep > 0.8) {
      mem.gpsFrozen = false;
      mem.gpsFreezeCount = 0;
      mem.deadAccX = 0;
      mem.deadAccY = 0;
      mem.posX = xRaw;
      mem.posY = yRaw;
    } else {
      if (wheelAbs > 0.12) {
        const dx = wheelAvg * Math.cos(headingTrue * rad) * dt;
        const dy = wheelAvg * Math.sin(headingTrue * rad) * dt;
        mem.posX += dx;
        mem.posY += dy;
        stepX = dx;
        stepY = dy;
      }
    }
  } else if (rawStep < 0.025 && wheelAbs > 0.32 && !docked) {
    mem.gpsFreezeCount++;
    const dx = wheelAvg * Math.cos(headingTrue * rad) * dt;
    const dy = wheelAvg * Math.sin(headingTrue * rad) * dt;
    mem.deadAccX += dx;
    mem.deadAccY += dy;
    if (mem.gpsFreezeCount >= 10) {
      mem.gpsFrozen = true;
      mem.posX = xRaw + mem.deadAccX;
      mem.posY = yRaw + mem.deadAccY;
      stepX = dx;
      stepY = dy;
    } else {
      mem.posX = xRaw;
      mem.posY = yRaw;
    }
  } else {
    mem.gpsFreezeCount = 0;
    mem.deadAccX = 0;
    mem.deadAccY = 0;
    mem.posX = xRaw;
    mem.posY = yRaw;
  }
  mem.rawPrevX = xRaw;
  mem.rawPrevY = yRaw;
  const px = num(mem.posX, xRaw);
  const py = num(mem.posY, yRaw);
  let stepDist = dist(oldPX, oldPY, px, py);
  if (stepDist < 1e-5 && (Math.abs(stepX) + Math.abs(stepY)) > 0) {
    stepDist = Math.hypot(stepX, stepY);
  }

  if (mem.calT === undefined) {
    mem.calT = clock;
    mem.calX = xRaw;
    mem.calY = yRaw;
    mem.calN = 0;
    mem.calStraight = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }
  mem.calN = (mem.calN || 0) + 1;
  mem.calSin += Math.sin(headingRaw * rad);
  mem.calCos += Math.cos(headingRaw * rad);
  if (Math.abs(wr - wl) < 0.22) mem.calStraight = (mem.calStraight || 0) + 1;
  if (clock - mem.calT >= 1.8) {
    const cx = xRaw - num(mem.calX, xRaw);
    const cy = yRaw - num(mem.calY, yRaw);
    if (Math.hypot(cx, cy) > 1.3 &&
        mem.calN > 0 &&
        mem.calStraight / mem.calN > 0.68) {
      const track = Math.atan2(cy, cx) / rad;
      const avgHeading = Math.atan2(mem.calSin, mem.calCos) / rad;
      const measuredBias = wrap(avgHeading - track);
      const err = wrap(measuredBias - num(mem.bias, 0));
      if (Math.abs(err) < 100) {
        mem.bias = wrap(mem.bias + clamp(err, -35, 35) * 0.10);
      }
    }
    mem.calT = clock;
    mem.calX = xRaw;
    mem.calY = yRaw;
    mem.calN = 0;
    mem.calStraight = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }
  headingTrue = wrap(headingRaw - num(mem.bias, 0));

  const carried = Math.max(0, num(obs.carried, 0));
  const battery = Math.max(0, num(obs.battery, 1));
  const solar = Math.max(0, num(obs.solar, 0));
  const db = num(mem.prevBattery, battery) - battery;
  if (wheelAbs > 0.12 && !docked) {
    mem.energyBucket = (mem.energyBucket || 0) +
      Math.max(0, db + solar * dt * 0.35);
    if (stepDist > 0.025) mem.distBucket = (mem.distBucket || 0) + stepDist;
    if (mem.distBucket >= 5) {
      const load = 1 + 0.20 * carried;
      const measured = mem.energyBucket / Math.max(1, mem.distBucket) / load;
      if (measured > 0.00004 && measured < 0.02) {
        const alpha = measured > mem.burnBase ? 0.30 : 0.09;
        mem.burnBase = clamp(mem.burnBase + alpha * (measured - mem.burnBase),
                             0.0002, 0.015);
      }
      mem.energyBucket = 0;
      mem.distBucket = 0;
    }
  }
  mem.prevBattery = battery;

  const hasRays = !!(obs.rays && typeof obs.rays.length === "number");
  const rayValues = [];
  const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  if (!Array.isArray(mem.rayLast)) {
    mem.rayLast = [];
    mem.rayStale = [];
    mem.rayDisabled = [];
    for (let i = 0; i < 9; i++) {
      mem.rayLast[i] = 15;
      mem.rayStale[i] = 0;
      mem.rayDisabled[i] = false;
    }
  }
  let allMax = hasRays;
  let disabledCount = 0;
  for (let i = 0; i < 9; i++) {
    const rv = hasRays ? num(obs.rays[i], 15) : 15;
    const r = clamp(rv, 0, 15);
    rayValues[i] = r;
    if (r < 14.7) allMax = false;
    if (Math.abs(r - mem.rayLast[i]) < 0.025) {
      mem.rayStale[i] = (mem.rayStale[i] || 0) + 1;
    } else {
      mem.rayStale[i] = 0;
      if (mem.rayDisabled[i] && Math.abs(r - mem.rayLast[i]) > 0.5) {
        mem.rayDisabled[i] = false;
      }
    }
    mem.rayLast[i] = r;
    if (mem.rayDisabled[i]) disabledCount++;
  }
  mem.rayTravel = (mem.rayTravel || 0) + stepDist;
  if (mem.rayTravel > 4) {
    for (let i = 0; i < 9; i++) {
      if (mem.rayStale[i] > 55 && rayValues[i] < 14.7) {
        mem.rayDisabled[i] = true;
      }
    }
    mem.rayTravel = 0;
  }
  disabledCount = 0;
  for (let i = 0; i < 9; i++) if (mem.rayDisabled[i]) disabledCount++;
  if (allMax && wheelAbs > 0.15) {
    mem.maxRayTravel = (mem.maxRayTravel || 0) + stepDist;
  } else {
    mem.maxRayTravel = 0;
  }
  const raysBlind = !hasRays || disabledCount >= 5 || mem.maxRayTravel > 30;

  const groundSpeed = stepDist / Math.max(0.04, dt);
  if (wheelAbs > 0.8 && groundSpeed < 0.30 && !bumped && !docked) {
    mem.slipTicks = (mem.slipTicks || 0) + 1;
    if (mem.slipTicks > 12) mem.sandUntil = clock + 12;
  } else {
    mem.slipTicks = Math.max(0, (mem.slipTicks || 0) - 1);
  }

  if (bumped && !mem.lastBumped) {
    mem.bumpCount = (mem.bumpCount || 0) + 1;
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const r = Math.max(0.25, rayValues[i]);
      if (rayAngles[i] < 0) rightDanger += 1 / r;
      else if (rayAngles[i] > 0) leftDanger += 1 / r;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.03) {
      mem.recoverSign = Math.sign(num(obs.site && obs.site.bearing, 30)) || 1;
    } else {
      mem.recoverSign = rightDanger > leftDanger ? 1 : -1;
    }
    mem.recoverUntil = clock + 1.15;
  }
  mem.lastBumped = bumped;

  const science = Math.max(0, num(obs.science, 0));
  const timeLeft = Math.max(0, num(obs.timeLeft, mem.totalSeconds - clock));
  const cap = Math.max(1, num(mem.capacity, 5));

  function markHintDone(i) {
    if (i === null || i === undefined || i < 0 || i >= mem.hints.length) return;
    mem.hints[i].status = 1;
    if (mem.activeHint === i) mem.activeHint = null;
    if (mem.search && mem.search.hintId === i) mem.search = null;
  }

  let justSampled = carried > num(mem.prevCarried, carried) + 0.01;
  let sampledPX = num(mem.sampleX, px);
  let sampledPY = num(mem.sampleY, py);
  if (justSampled) {
    let completedGoal = null;
    if (mem.sampleSiteId !== null && mem.sampleSiteId !== undefined) {
      for (let i = 0; i < mem.siteGoals.length; i++) {
        if (mem.siteGoals[i].id === mem.sampleSiteId) {
          completedGoal = mem.siteGoals[i];
          mem.siteGoals[i].done = true;
          break;
        }
      }
    }
    let relatedHint = completedGoal && completedGoal.hintId !== undefined
      ? completedGoal.hintId : null;
    if (relatedHint === null && mem.activeHint !== null &&
        mem.activeHint !== undefined) {
      const hh = mem.hints[mem.activeHint];
      if (hh && (dist(sampledPX, sampledPY, hh.x, hh.y) < 32 ||
          (mem.search && mem.search.hintId === mem.activeHint))) {
        relatedHint = mem.activeHint;
      }
    }
    if (relatedHint === null && mem.search && mem.search.hintId !== null &&
        mem.search.hintId !== undefined &&
        dist(sampledPX, sampledPY, mem.search.cx, mem.search.cy) < 35) {
      relatedHint = mem.search.hintId;
    }
    if (relatedHint !== null) markHintDone(relatedHint);

    if (mem.search && mem.search.hintId === null &&
        dist(sampledPX, sampledPY, mem.search.cx, mem.search.cy) < 36) {
      if (mem.search.key && mem.search.key.indexOf("g:") === 0) {
        mem.gridVisited[mem.search.key] = true;
      }
      if (mem.search.local) mem.lastLocalSearch = clock;
      if (mem.activeFree && mem.search.key === mem.activeFree.key) {
        mem.gridVisited[mem.activeFree.key] = true;
        mem.activeFree = null;
      }
      mem.search = null;
    }
    if (mem.liveSiteId === mem.sampleSiteId) mem.liveSiteId = null;
    mem.sampling = false;
    mem.sampleSiteId = null;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }
  mem.prevCarried = carried;
  mem.prevCarriedValue = num(obs.carriedValue, mem.prevCarriedValue || 0);

  let siteVisible = false;
  let siteDistance = 0;
  let siteBearing = 0;
  let visibleSiteId = null;
  const siteObs = obs.site;
  if (siteObs && Number.isFinite(Number(siteObs.distance))) {
    siteDistance = clamp(num(siteObs.distance, 8), 0, 20);
    siteBearing = num(siteObs.bearing, 0);
    const globalSiteBearing = (headingTrue + siteBearing) * rad;
    const sx = px + siteDistance * Math.cos(globalSiteBearing);
    const sy = py + siteDistance * Math.sin(globalSiteBearing);
    const suppressOldSample = justSampled &&
      dist(sx, sy, sampledPX, sampledPY) < 3;
    if (!suppressOldSample) {
      let match = null;
      let bestD = 6.5;
      for (let i = 0; i < mem.siteGoals.length; i++) {
        const g = mem.siteGoals[i];
        if (g.done) continue;
        const dd = dist(sx, sy, g.x, g.y);
        if (dd < bestD) {
          bestD = dd;
          match = g;
        }
      }
      if (!match) {
        match = {
          id: mem.nextSiteId++,
          x: clamp(sx, 1, mem.mapW - 1),
          y: clamp(sy, 1, mem.mapH - 1),
          value: Math.max(0.1, num(siteObs.value, 1)),
          seen: clock,
          done: false,
          hintId: null
        };
        mem.siteGoals.push(match);
      } else {
        match.x = 0.68 * match.x + 0.32 * clamp(sx, 1, mem.mapW - 1);
        match.y = 0.68 * match.y + 0.32 * clamp(sy, 1, mem.mapH - 1);
        match.value = Math.max(match.value, num(siteObs.value, match.value));
        match.seen = clock;
      }
      if (mem.activeHint !== null && mem.activeHint !== undefined) {
        const hh = mem.hints[mem.activeHint];
        if (hh && dist(sx, sy, hh.x, hh.y) < 34) match.hintId = mem.activeHint;
      }
      if (mem.search && mem.search.hintId !== null &&
          mem.search.hintId !== undefined &&
          dist(sx, sy, mem.search.cx, mem.search.cy) < 35) {
        match.hintId = mem.search.hintId;
      }
      visibleSiteId = match.id;
      mem.liveSiteId = match.id;
      siteVisible = true;
    }
  }

  function getSiteGoal() {
    if (mem.liveSiteId !== null && mem.liveSiteId !== undefined) {
      for (let i = 0; i < mem.siteGoals.length; i++) {
        const g = mem.siteGoals[i];
        if (g.id === mem.liveSiteId && !g.done) return g;
      }
      mem.liveSiteId = null;
    }
    let best = null;
    let bd = 1e9;
    for (let i = 0; i < mem.siteGoals.length; i++) {
      const g = mem.siteGoals[i];
      if (g.done) continue;
      const dd = dist(px, py, g.x, g.y);
      if (dd < bd) {
        bd = dd;
        best = g;
      }
    }
    if (best) mem.liveSiteId = best.id;
    return best;
  }

  let pendingSite = getSiteGoal();
  if (!siteVisible && pendingSite && !mem.sampling &&
      dist(px, py, pendingSite.x, pendingSite.y) < 2.5 &&
      clock - num(pendingSite.seen, clock) > 14) {
    pendingSite.done = true;
    if (mem.liveSiteId === pendingSite.id) mem.liveSiteId = null;
    pendingSite = getSiteGoal();
  }

  function hasPendingSite() {
    for (let i = 0; i < mem.siteGoals.length; i++) {
      if (!mem.siteGoals[i].done) return true;
    }
    return false;
  }

  function hasPendingHint() {
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status === 0) return true;
    }
    return false;
  }

  function hasUnvisitedGrid() {
    const nx = Math.max(1, Math.floor((mem.mapW - 40) / 50) + 1);
    const ny = Math.max(1, Math.floor((mem.mapH - 40) / 50) + 1);
    for (let ix = 0; ix < nx; ix++) {
      for (let iy = 0; iy < ny; iy++) {
        if (!mem.gridVisited["g:" + ix + ":" + iy]) return true;
      }
    }
    return false;
  }

  function energyFor(d1, d2, n, extra, samples) {
    const meters = (Math.max(0, d1) + 1.10 * Math.max(0, d2) +
                    Math.max(0, extra)) * 1.30;
    const load = 1 + 0.24 * (Math.max(0, n) + 0.45);
    return meters * mem.burnBase * load * 1.38 +
           0.075 + 0.020 * Math.max(0, samples);
  }

  function planTime(d1, d2, extra) {
    return (Math.max(0, d1) + Math.max(0, d2) +
            Math.max(0, extra)) * 1.02 + 45;
  }

  const baseDistanceGPS = dist(px, py, mem.baseX, mem.baseY);
  const beacon = obs.beacon;
  const beaconDistance = beacon && Number.isFinite(Number(beacon.distance))
    ? Math.max(0, num(beacon.distance, baseDistanceGPS)) : null;
  const baseDistance = beaconDistance !== null
    ? beaconDistance : baseDistanceGPS;

  function findBestHint() {
    let best = null;
    let bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const hnt = mem.hints[i];
      if (hnt.status !== 0 || num(hnt.blockedUntil, 0) > clock) continue;
      const d1 = dist(px, py, hnt.x, hnt.y);
      const d2 = dist(hnt.x, hnt.y, mem.baseX, mem.baseY);
      const extra = 32;
      const need = energyFor(d1, d2, carried, extra, 1);
      const tneed = planTime(d1, d2, extra);
      if (need > battery - 0.015 || tneed > timeLeft - 5) continue;
      let cost;
      if (carried > 0) {
        cost = 28 + d1 + Math.max(0, d2 - baseDistance) * 0.9;
      } else {
        cost = 32 + d1 + d2;
      }
      const score = Math.max(0.05, hnt.value) / Math.pow(Math.max(1, cost), 0.86);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function findGrid() {
    let best = null;
    let bestCost = 1e30;
    const nx = Math.max(1, Math.floor((mem.mapW - 40) / 50) + 1);
    const ny = Math.max(1, Math.floor((mem.mapH - 40) / 50) + 1);
    for (let ix = 0; ix < nx; ix++) {
      for (let iy = 0; iy < ny; iy++) {
        const key = "g:" + ix + ":" + iy;
        if (mem.gridVisited[key]) continue;
        const gx = clamp(20 + ix * 50, 8, mem.mapW - 8);
        const gy = clamp(20 + iy * 50, 8, mem.mapH - 8);
        const d1 = dist(px, py, gx, gy);
        const d2 = dist(gx, gy, mem.baseX, mem.baseY);
        const extra = 24;
        const need = energyFor(d1, d2, carried, extra, 1);
        const tneed = planTime(d1, d2, extra);
        if (need > battery - 0.02 || tneed > timeLeft - 5) continue;
        const cost = d1 + 0.36 * d2;
        if (cost < bestCost) {
          bestCost = cost;
          best = { key: key, x: gx, y: gy };
        }
      }
    }
    return best;
  }

  function makeRing(s, radius, count) {
    const points = [];
    for (let i = 0; i < count; i++) {
      const a = 2 * Math.PI * i / count;
      const x = clamp(s.cx + radius * Math.cos(a), 2, mem.mapW - 2);
      const y = clamp(s.cy + radius * Math.sin(a), 2, mem.mapH - 2);
      let duplicate = false;
      for (let j = 0; j < points.length; j++) {
        if (dist(x, y, points[j].x, points[j].y) < 3) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) points.push({ x: x, y: y });
    }
    return points;
  }

  function startSearch(cx, cy, hintId, key, local) {
    const s = {
      cx: clamp(cx, 2, mem.mapW - 2),
      cy: clamp(cy, 2, mem.mapH - 2),
      hintId: hintId === undefined ? null : hintId,
      key: key || null,
      local: !!local,
      centerS: science,
      bestS: science,
      bestX: px,
      bestY: py,
      bestRad: dist(px, py, cx, cy),
      phase: "inner",
      points: [],
      idx: 0,
      pointT: clock,
      outerUsed: false,
      hillUsed: false,
      hillDirX: 1,
      hillDirY: 0,
      hillR: 16,
      hillStep: 0,
      lastHillS: science
    };
    s.points = makeRing(s, 9, 8);
    mem.search = s;
    if (hintId !== null && hintId !== undefined) mem.activeHint = hintId;
  }

  function finishSearch() {
    const s = mem.search;
    if (!s) return;
    if (s.hintId !== null && s.hintId !== undefined) {
      const i = s.hintId;
      if (i >= 0 && i < mem.hints.length) mem.hints[i].status = 1;
      if (mem.activeHint === i) mem.activeHint = null;
    }
    if (s.key && s.key.indexOf("g:") === 0) {
      mem.gridVisited[s.key] = true;
    }
    if (s.local) mem.lastLocalSearch = clock;
    if (mem.activeFree && s.key === mem.activeFree.key) mem.activeFree = null;
    mem.search = null;
  }

  function beginOuter(s) {
    if (s.outerUsed) {
      finishSearch();
      return;
    }
    s.outerUsed = true;
    s.phase = "outer";
    s.points = makeRing(s, 22, 16);
    s.idx = 0;
    s.pointT = clock;
    if (s.points.length === 0) finishSearch();
  }

  function beginHill(s) {
    const dx = s.bestX - s.cx;
    const dy = s.bestY - s.cy;
    const n = Math.hypot(dx, dy);
    if (n < 2) return false;
    s.phase = "hill";
    s.hillUsed = true;
    s.hillDirX = dx / n;
    s.hillDirY = dy / n;
    s.hillR = Math.max(16, s.bestRad + 7);
    s.hillStep = 0;
    s.lastHillS = s.bestS;
    s.pointT = clock;
    return true;
  }

  function recordSearchSignal(s) {
    if (science > s.bestS) {
      s.bestS = science;
      s.bestX = px;
      s.bestY = py;
      s.bestRad = dist(px, py, s.cx, s.cy);
    }
  }

  function processSearch() {
    const s = mem.search;
    if (!s) return;
    let tx = s.cx;
    let ty = s.cy;
    if (s.phase === "inner" || s.phase === "outer") {
      if (!s.points || s.idx >= s.points.length) {
        if (s.phase === "inner") {
          const threshold = Math.max(0.000001, Math.abs(s.centerS) * 0.10);
          if (s.bestS <= 0.000001) {
            finishSearch();
            return;
          }
          if (s.bestS > s.centerS + threshold && beginHill(s)) return;
          beginOuter(s);
          return;
        }
        if (s.bestS > 0.000001 && !s.hillUsed && beginHill(s)) return;
        finishSearch();
        return;
      }
      tx = s.points[s.idx].x;
      ty = s.points[s.idx].y;
      const reached = dist(px, py, tx, ty) < 3.5;
      const expired = clock - s.pointT > 42;
      if (!reached && !expired) return;
      if (reached) recordSearchSignal(s);
      s.idx++;
      s.pointT = clock;
      if (s.idx < s.points.length) return;

      if (s.phase === "inner") {
        const threshold = Math.max(0.000001, Math.abs(s.centerS) * 0.10);
        if (s.bestS <= 0.000001) {
          finishSearch();
          return;
        }
        if (s.bestS > s.centerS + threshold && beginHill(s)) return;
        beginOuter(s);
        return;
      }
      if (s.bestS > 0.000001 && !s.hillUsed && beginHill(s)) return;
      finishSearch();
      return;
    }

    if (s.phase === "hill") {
      tx = s.cx + s.hillDirX * s.hillR;
      ty = s.cy + s.hillDirY * s.hillR;
      tx = clamp(tx, 2, mem.mapW - 2);
      ty = clamp(ty, 2, mem.mapH - 2);
      const reached = dist(px, py, tx, ty) < 3.5;
      const expired = clock - s.pointT > 42;
      if (!reached && !expired) return;
      if (reached) {
        recordSearchSignal(s);
        if (s.hillStep > 0 && s.lastHillS > 0.000001 &&
            science < s.lastHillS * 0.72) {
          if (!s.outerUsed) beginOuter(s);
          else finishSearch();
          return;
        }
        if (science > s.lastHillS) s.lastHillS = science;
      }
      s.hillStep++;
      s.hillR += 7;
      s.pointT = clock;
      if (s.hillR > 43) {
        if (!s.outerUsed) beginOuter(s);
        else finishSearch();
      }
    }
  }

  function ensureTasks() {
    if (mem.activeHint !== null && mem.activeHint !== undefined) {
      const a = mem.activeHint;
      if (!mem.hints[a] || mem.hints[a].status !== 0) mem.activeHint = null;
    }
    if (mem.search && mem.search.hintId !== null &&
        mem.search.hintId !== undefined) {
      mem.activeHint = mem.search.hintId;
    }
    if (!mem.activeHint && !mem.search) {
      const best = findBestHint();
      if (best !== null) mem.activeHint = best;
    }
    if (!mem.activeHint && !mem.search && !hasPendingHint() &&
        !hasPendingSite() && carried < cap) {
      if (science > 0.000001 && clock - num(mem.lastLocalSearch, -1000) > 40) {
        startSearch(px, py, null, "local:" + Math.floor(clock), true);
      } else if (carried === 0 && !mem.activeFree) {
        mem.activeFree = findGrid();
      }
    }
  }

  function maybeStartSearch() {
    if (siteVisible || mem.search || hasPendingSite()) return;
    if (mem.activeHint !== null && mem.activeHint !== undefined) {
      const hnt = mem.hints[mem.activeHint];
      if (hnt && dist(px, py, hnt.x, hnt.y) < 4.5) {
        startSearch(hnt.x, hnt.y, mem.activeHint, null, false);
      }
      return;
    }
    if (mem.activeFree) {
      if (dist(px, py, mem.activeFree.x, mem.activeFree.y) < 5) {
        if (science > 0.000001) {
          startSearch(mem.activeFree.x, mem.activeFree.y, null,
                      mem.activeFree.key, false);
        } else {
          mem.gridVisited[mem.activeFree.key] = true;
          mem.activeFree = null;
        }
      }
    }
  }

  function remainingSearchMeters(s) {
    if (!s) return 0;
    if (s.phase === "inner") {
      return Math.min(110, Math.max(0, s.points.length - s.idx) * 7 + 35);
    }
    if (s.phase === "outer") {
      return Math.min(110, Math.max(0, s.points.length - s.idx) * 7 + 8);
    }
    return Math.min(80, Math.max(0, 43 - s.hillR) + (s.outerUsed ? 5 : 24));
  }

  function getPlan() {
    if (siteVisible) {
      const sg = getSiteGoal();
      const gx = sg ? sg.x : px + siteDistance *
        Math.cos((headingTrue + siteBearing) * rad);
      const gy = sg ? sg.y : py + siteDistance *
        Math.sin((headingTrue + siteBearing) * rad);
      const d2 = dist(gx, gy, mem.baseX, mem.baseY);
      return {
        kind: "site",
        x: gx,
        y: gy,
        d1: siteDistance,
        d2: d2,
        extra: 3,
        need: energyFor(siteDistance, d2, carried, 3, 1),
        time: planTime(siteDistance, d2, 3),
        id: sg ? sg.id : visibleSiteId
      };
    }
    const sg = getSiteGoal();
    if (sg) {
      const d1 = dist(px, py, sg.x, sg.y);
      const d2 = dist(sg.x, sg.y, mem.baseX, mem.baseY);
      return {
        kind: "site",
        x: sg.x,
        y: sg.y,
        d1: d1,
        d2: d2,
        extra: 4,
        need: energyFor(d1, d2, carried, 4, 1),
        time: planTime(d1, d2, 4),
        id: sg.id
      };
    }
    if (mem.activeHint !== null && mem.activeHint !== undefined) {
      const hnt = mem.hints[mem.activeHint];
      if (hnt && hnt.status === 0) {
        const d1 = dist(px, py, hnt.x, hnt.y);
        const d2 = dist(hnt.x, hnt.y, mem.baseX, mem.baseY);
        const extra = mem.search ? remainingSearchMeters(mem.search) : 32;
        return {
          kind: "hint",
          x: hnt.x,
          y: hnt.y,
          d1: d1,
          d2: d2,
          extra: extra,
          need: energyFor(d1, d2, carried, extra, 1),
          time: planTime(d1, d2, extra),
          id: mem.activeHint
        };
      }
    }
    if (mem.search) {
      const s = mem.search;
      const d1 = dist(px, py, s.cx, s.cy);
      const d2 = dist(s.cx, s.cy, mem.baseX, mem.baseY);
      const extra = remainingSearchMeters(s);
      return {
        kind: "free",
        x: s.cx,
        y: s.cy,
        d1: d1,
        d2: d2,
        extra: extra,
        need: energyFor(d1, d2, carried, extra, 1),
        time: planTime(d1, d2, extra),
        id: s.key
      };
    }
    if (mem.activeFree) {
      const d1 = dist(px, py, mem.activeFree.x, mem.activeFree.y);
      const d2 = dist(mem.activeFree.x, mem.activeFree.y, mem.baseX, mem.baseY);
      return {
        kind: "free",
        x: mem.activeFree.x,
        y: mem.activeFree.y,
        d1: d1,
        d2: d2,
        extra: 24,
        need: energyFor(d1, d2, carried, 24, 1),
        time: planTime(d1, d2, 24),
        id: mem.activeFree.key
      };
    }
    return null;
  }

  function retEnergy(d, n) {
    return d * 1.34 * mem.burnBase * (1 + 0.24 * Math.max(0, n)) *
           1.45 + 0.06 + 0.008 * Math.max(0, n);
  }

  function stopOutput(drill) {
    mem.motorI[0] = 0;
    mem.motorI[1] = 0;
    mem.lastSet[0] = 0;
    mem.lastSet[1] = 0;
    return { left: 0, right: 0, drill: !!drill };
  }

  function motorCommand(index, target, actual, bias) {
    target = clamp(target, -2.85, 2.85);
    let integ = num(mem.motorI[index], 0);
    const last = num(mem.lastSet[index], 0);
    if (target * last < -0.08 ||
        (Math.abs(target) < 0.05 && Math.abs(last) > 0.15)) {
      integ = 0;
    }
    const err = target - actual;
    let raw = target / 3.0 + 0.34 * err + integ + bias;
    if (Math.abs(target) < 0.05) {
      integ *= 0.75;
    } else {
      const proposed = clamp(integ + 0.24 * err * dt, -0.36, 0.36);
      if (Math.abs(raw) < 0.96 || err * raw < 0) integ = proposed;
      raw = target / 3.0 + 0.34 * err + integ + bias;
    }
    if (Math.abs(target) > 0.18 && Math.abs(actual) < 0.05 &&
        Math.abs(raw) < 0.115) {
      raw = Math.sign(target) * 0.115;
    }
    mem.motorI[index] = clamp(integ, -0.36, 0.36);
    mem.lastSet[index] = target;
    return clamp(raw, -1, 1);
  }

  function drive(v, omega, holdBias) {
    const leftTarget = clamp(v - omega * 0.30, -2.85, 2.85);
    const rightTarget = clamp(v + omega * 0.30, -2.85, 2.85);
    const hb = num(holdBias, 0);
    return {
      left: motorCommand(0, leftTarget, wl, hb),
      right: motorCommand(1, rightTarget, wr, hb),
      drill: false
    };
  }

  function dangerSign(goalErr) {
    let rd = 0;
    let ld = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.3, rayValues[i]);
      if (rayAngles[i] < 0) rd += q;
      else if (rayAngles[i] > 0) ld += q;
    }
    if (Math.abs(rd - ld) < 0.02) return Math.sign(goalErr || 1);
    return rd > ld ? 1 : -1;
  }

  function navigation(goalErr, goalDist, mode, key) {
    goalErr = wrap(goalErr);
    goalDist = Math.max(0, num(goalDist, 0));

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestDist = goalDist;
      mem.navProgressT = clock;
    } else if (goalDist < num(mem.navBestDist, 1e9) - 0.35) {
      mem.navBestDist = goalDist;
      mem.navProgressT = clock;
    }
    if (clock - num(mem.navProgressT, clock) > 24 &&
        wheelAbs > 0.25 && clock >= num(mem.recoverUntil, 0)) {
      mem.recoverSign = dangerSign(goalErr);
      mem.recoverUntil = clock + 1.0;
      mem.navProgressT = clock;
      mem.navBestDist = goalDist;
    }

    if (clock < num(mem.recoverUntil, 0)) {
      const sign = num(mem.recoverSign, 1) || 1;
      return drive(-0.42, sign * 1.05, 0);
    }

    const candidates = [-85, -70, -55, -40, -25, -10, 0,
                        10, 25, 40, 55, 70, 85];
    const desired = clamp(goalErr, -85, 85);
    candidates.push(desired);
    let bestAngle = 0;
    let bestCost = 1e30;
    let bestAhead = 1e9;
    const look = 8;
    for (let c = 0; c < candidates.length; c++) {
      const a = candidates[c];
      const ar = a * rad;
      const ca = Math.cos(ar);
      const sa = Math.sin(ar);
      let cost = 0.72 * Math.pow(wrap(a - goalErr) / 36, 2) +
                 0.0015 * Math.abs(wrap(a - num(mem.lastSteer, 0)));
      let ahead = 1e9;

      for (let i = 0; i < 9; i++) {
        if (mem.rayDisabled[i]) continue;
        const r0 = rayValues[i];
        if (!(r0 > 0.05) || r0 >= 14.75) continue;
        const r = Math.max(0.15, r0 - 0.28);
        const rr = rayAngles[i] * rad;
        const ox = r * Math.cos(rr);
        const oy = r * Math.sin(rr);
        const proj = ox * ca + oy * sa;
        if (proj < -0.4 || proj > look + 2.5) continue;
        const along = clamp(proj, 0, look);
        const lateral = Math.abs(-ox * sa + oy * ca);
        const separation = Math.hypot(proj - along, lateral);
        if (separation < 2.65) {
          cost += 2.5 * Math.pow(2.65 - separation, 2);
        } else if (separation < 4) {
          cost += 0.10 * Math.pow(4 - separation, 2);
        }
        if (proj > 0 && lateral < 2.6) {
          ahead = Math.min(ahead, Math.max(0, proj - 1.15));
        }
      }

      const globalAngle = (headingTrue + a) * rad;
      const nx = px + 7 * Math.cos(globalAngle);
      const ny = py + 7 * Math.sin(globalAngle);
      if (nx < 3) cost += 2.5 * Math.pow(3 - nx, 2);
      if (ny < 3) cost += 2.5 * Math.pow(3 - ny, 2);
      if (nx > mem.mapW - 3) cost += 2.5 * Math.pow(nx - (mem.mapW - 3), 2);
      if (ny > mem.mapH - 3) cost += 2.5 * Math.pow(ny - (mem.mapH - 3), 2);

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
        bestAhead = ahead;
      }
    }
    mem.lastSteer = bestAngle;

    let cruise = mode === "site" ? 1.9 : 2.15;
    if (mode === "return") cruise = 2.05;
    if (raysBlind) cruise = Math.min(cruise, disabledCount >= 5 ? 0.95 : 1.35);
    if (mem.bumpCount >= 4) cruise = Math.min(cruise, 1.35);
    if (clock < num(mem.sandUntil, 0)) cruise = Math.min(cruise, 1.2);

    let speed = cruise;
    if (mode === "site") {
      if (goalDist < 8) {
        speed = Math.min(speed, Math.max(0.25, 0.34 + 0.43 * (goalDist - 1.2)));
      }
    } else if (mode === "return") {
      if (goalDist < 12) speed = Math.min(speed, 0.28 + 0.17 * goalDist);
    } else {
      if (goalDist < 12) {
        speed = Math.min(speed, Math.max(0.30, Math.sqrt(Math.max(0, goalDist - 2) * 0.78)));
      }
    }

    const turnMagnitude = Math.abs(bestAngle);
    if (turnMagnitude > 52) {
      speed *= clamp(1 - (turnMagnitude - 52) / 95, 0.34, 1);
    }
    if (Math.abs(goalErr) > 118) speed = 0;

    let front = 1e9;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i] || Math.abs(rayAngles[i]) > 25) continue;
      if (rayValues[i] < 14.75) front = Math.min(front, Math.max(0.1, rayValues[i] - 0.55));
    }
    if (front < 1.8) speed = Math.min(speed, 0.38);
    else if (front < 3) speed = Math.min(speed, 0.62);
    else if (front < 5) speed = Math.min(speed, 0.95);
    else if (front < 8) speed = Math.min(speed, 1.40);

    if (bestAhead < 1.0) speed = Math.min(speed, 0.36);
    else if (bestAhead < 2.0) speed = Math.min(speed, 0.55);
    else if (bestAhead < 3.5) speed = Math.min(speed, 0.82);
    else if (bestAhead < 5.5) speed = Math.min(speed, 1.15);

    const ga = (headingTrue + bestAngle) * rad;
    const dx = Math.cos(ga);
    const dy = Math.sin(ga);
    if ((px < 5 && dx < 0) || (py < 5 && dy < 0) ||
        (px > mem.mapW - 5 && dx > 0) ||
        (py > mem.mapH - 5 && dy > 0)) {
      speed = Math.min(speed, 0.45);
    } else if ((px < 9 && dx < 0) || (py < 9 && dy < 0) ||
               (px > mem.mapW - 9 && dx > 0) ||
               (py > mem.mapH - 9 && dy > 0)) {
      speed = Math.min(speed, 0.85);
    }

    let omega;
    if (Math.abs(goalErr) > 118) {
      omega = (Math.sign(bestAngle) || Math.sign(goalErr) || 1) * 1.25;
    } else {
      omega = clamp(2.35 * bestAngle * rad, -1.8, 1.8);
    }
    if (speed < 0.05) speed = 0;
    const maxWheel = Math.max(Math.abs(speed - omega * 0.30),
                              Math.abs(speed + omega * 0.30));
    if (maxWheel > 2.8) {
      const scale = 2.8 / maxWheel;
      speed *= scale;
      omega *= scale;
    }
    return drive(speed, omega, 0);
  }

  function getCurrentPlan() {
    return getPlan();
  }

  function shouldReturnNow() {
    if (mem.returning) return true;
    if (docked) return false;
    if (carried >= cap) return true;
    const reserve = retEnergy(baseDistance, carried);
    if (battery < reserve + 0.015) return true;
    const returnTime = baseDistance * 1.15 + 35;
    if (carried > 0 && timeLeft < returnTime + 12) return true;
    const p = getCurrentPlan();
    if (!p) return true;
    if (battery < p.need + 0.015) return true;
    if (timeLeft < p.time + (carried > 0 ? 12 : 5)) return true;
    return false;
  }

  if (docked && carried <= 0 && mem.returning) mem.returning = false;
  if (docked && carried > 0) mem.returning = true;

  ensureTasks();
  maybeStartSearch();

  if (!docked && !mem.returning && !siteVisible) {
    if (mem.search) processSearch();
    if (!mem.search && mem.activeFree &&
        dist(px, py, mem.activeFree.x, mem.activeFree.y) < 5 &&
        !hasPendingSite()) {
      if (science > 0.000001) {
        startSearch(mem.activeFree.x, mem.activeFree.y, null,
                    mem.activeFree.key, false);
      } else {
        mem.gridVisited[mem.activeFree.key] = true;
        mem.activeFree = null;
      }
    }
    ensureTasks();
    maybeStartSearch();
  }

  if (!docked && !mem.returning && shouldReturnNow()) {
    mem.returning = true;
  }

  if (mem.returning) {
    if (docked) return stopOutput(false);
    const bd = beaconDistance !== null ? beaconDistance : baseDistanceGPS;
    if (bd <= 2.35) return stopOutput(false);
    let err;
    if (beacon && Number.isFinite(Number(beacon.bearing)) &&
        beaconDistance !== null) {
      err = num(beacon.bearing, 0);
    } else {
      const bearing = Math.atan2(mem.baseY - py, mem.baseX - px) / rad;
      err = wrap(bearing - headingTrue);
    }
    return navigation(err, bd, "return", "base");
  }

  function sampleOutput() {
    const progress = Math.max(0, num(obs.drilling, 0));
    if (!mem.sampling && siteVisible && siteDistance <= 1.25) {
      mem.sampling = true;
      mem.sampleSiteId = mem.liveSiteId;
      mem.sampleX = px;
      mem.sampleY = py;
      mem.sampleStart = clock;
      mem.stillTicks = 0;
      mem.holdI = 0;
    }
    if (!mem.sampling) return null;

    if (siteVisible && siteDistance > 1.58) {
      mem.sampling = false;
      mem.stillTicks = 0;
      mem.holdI = 0;
      return null;
    }
    if (!siteVisible && progress < 0.15 &&
        clock - num(mem.sampleStart, clock) > 9) {
      mem.sampling = false;
      mem.stillTicks = 0;
      return null;
    }

    const still = Math.abs(wl) < 0.14 && Math.abs(wr) < 0.14;
    if (still) mem.stillTicks = (mem.stillTicks || 0) + 1;
    else mem.stillTicks = 0;

    const errX = num(mem.sampleX, px) - px;
    const errY = num(mem.sampleY, py) - py;
    const along = errX * Math.cos(headingTrue * rad) +
                  errY * Math.sin(headingTrue * rad);
    const velAlong = ((px - oldPX) * Math.cos(headingTrue * rad) +
                      (py - oldPY) * Math.sin(headingTrue * rad)) /
                     Math.max(0.04, dt);
    if (Math.abs(along) > 0.08) {
      mem.holdI = clamp(num(mem.holdI, 0) + 0.010 * along * dt, -0.15, 0.15);
    }
    const pitch = clamp(num(obs.pitch, 0), -25, 25);
    const hold = clamp(0.012 * pitch + 0.035 * along +
                       num(mem.holdI, 0) - 0.05 * velAlong, -0.25, 0.25);

    let inRange = true;
    if (siteVisible) inRange = siteDistance <= 1.52;
    else if (progress <= 0) inRange = clock - num(mem.sampleStart, clock) < 1.5;

    let drill = inRange && mem.stillTicks >= 2;
    if (progress > 0.05 && inRange) drill = true;
    const left = motorCommand(0, 0, wl, hold);
    const right = motorCommand(1, 0, wr, hold);
    return { left: left, right: right, drill: !!drill };
  }

  let sampleCmd = sampleOutput();
  if (sampleCmd) return sampleCmd;

  if (docked && carried > 0) return stopOutput(false);

  if (docked) {
    let p = getCurrentPlan();
    if (p && battery >= 0.985 && p.need > 1.0) {
      if (p.kind === "hint" && p.id !== null && p.id !== undefined) {
        mem.hints[p.id].blockedUntil = clock + 240;
        if (mem.activeHint === p.id) mem.activeHint = null;
        if (mem.search && mem.search.hintId === p.id) mem.search = null;
      } else if (p.kind === "site") {
        for (let i = 0; i < mem.siteGoals.length; i++) {
          if (mem.siteGoals[i].id === p.id) mem.siteGoals[i].done = true;
        }
        if (mem.liveSiteId === p.id) mem.liveSiteId = null;
      } else if (p.kind === "free" && p.id &&
                 String(p.id).indexOf("g:") === 0) {
        mem.gridVisited[p.id] = true;
        mem.activeFree = null;
        mem.search = null;
      }
      ensureTasks();
      p = getCurrentPlan();
    }
    if (!p) return stopOutput(false);
    if (timeLeft < p.time + 10) return stopOutput(false);
    if (battery < p.need + 0.025) return stopOutput(false);
    const chargeTarget = Math.min(0.97, Math.max(0.62, p.need + 0.10));
    if (battery < chargeTarget && timeLeft > p.time + 70) {
      return stopOutput(false);
    }
  }

  if (!docked && !mem.returning) {
    if (shouldReturnNow()) {
      mem.returning = true;
      const bd = beaconDistance !== null ? beaconDistance : baseDistanceGPS;
      if (bd <= 2.35) return stopOutput(false);
      let err;
      if (beacon && Number.isFinite(Number(beacon.bearing)) &&
          beaconDistance !== null) {
        err = num(beacon.bearing, 0);
      } else {
        err = wrap(Math.atan2(mem.baseY - py, mem.baseX - px) / rad - headingTrue);
      }
      return navigation(err, bd, "return", "base");
    }
  }

  if (!docked && !mem.returning && !siteVisible) {
    if (mem.search) processSearch();
    ensureTasks();
    maybeStartSearch();
  }

  sampleCmd = sampleOutput();
  if (sampleCmd) return sampleCmd;

  if (mem.returning) {
    if (docked) return stopOutput(false);
    const bd = beaconDistance !== null ? beaconDistance : baseDistanceGPS;
    if (bd <= 2.35) return stopOutput(false);
    const err = beacon && Number.isFinite(Number(beacon.bearing)) &&
                beaconDistance !== null
      ? num(beacon.bearing, 0)
      : wrap(Math.atan2(mem.baseY - py, mem.baseX - px) / rad - headingTrue);
    return navigation(err, bd, "return", "base");
  }

  if (siteVisible) {
    if (siteDistance <= 1.25) {
      sampleCmd = sampleOutput();
      if (sampleCmd) return sampleCmd;
    }
    return navigation(wrap(siteBearing), siteDistance, "site",
                      "site:" + String(visibleSiteId));
  }

  pendingSite = getSiteGoal();
  if (pendingSite) {
    const sd = dist(px, py, pendingSite.x, pendingSite.y);
    const bearing = Math.atan2(pendingSite.y - py, pendingSite.x - px) / rad;
    return navigation(wrap(bearing - headingTrue), sd, "site",
                      "site:" + String(pendingSite.id));
  }

  if (mem.search) {
    const s = mem.search;
    let tx = s.cx;
    let ty = s.cy;
    if (s.phase === "inner" || s.phase === "outer") {
      if (s.points && s.idx < s.points.length) {
        tx = s.points[s.idx].x;
        ty = s.points[s.idx].y;
      }
    } else if (s.phase === "hill") {
      tx = clamp(s.cx + s.hillDirX * s.hillR, 2, mem.mapW - 2);
      ty = clamp(s.cy + s.hillDirY * s.hillR, 2, mem.mapH - 2);
    }
    const d = dist(px, py, tx, ty);
    const bearing = Math.atan2(ty - py, tx - px) / rad;
    const key = "search:" + String(s.hintId) + ":" +
                String(s.key) + ":" + s.phase + ":" +
                String(s.idx) + ":" + String(s.hillStep);
    return navigation(wrap(bearing - headingTrue), d, "waypoint", key);
  }

  if (mem.activeHint !== null && mem.activeHint !== undefined) {
    const hnt = mem.hints[mem.activeHint];
    if (hnt) {
      const d = dist(px, py, hnt.x, hnt.y);
      const bearing = Math.atan2(hnt.y - py, hnt.x - px) / rad;
      return navigation(wrap(bearing - headingTrue), d, "waypoint",
                        "hint:" + String(mem.activeHint));
    }
  }

  if (mem.activeFree) {
    const d = dist(px, py, mem.activeFree.x, mem.activeFree.y);
    const bearing = Math.atan2(mem.activeFree.y - py,
                               mem.activeFree.x - px) / rad;
    return navigation(wrap(bearing - headingTrue), d, "waypoint",
                      "grid:" + String(mem.activeFree.key));
  }

  return stopOutput(false);
}

function act(obs, mem) {
  const PI = Math.PI;
  const RAD = PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  if (!mem || typeof mem !== "object") mem = {};

  const rawX = num(obs.x, 200);
  const rawY = num(obs.y, 200);
  const headingRaw = wrap(num(obs.heading, 0));
  const wheelLeft = num(obs.wheelLeft, 0);
  const wheelRight = num(obs.wheelRight, 0);
  const wheelAvg = (wheelLeft + wheelRight) * 0.5;
  const wheelAbs = (Math.abs(wheelLeft) + Math.abs(wheelRight)) * 0.5;
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const battery = Math.max(0, num(obs.battery, 1));
  const solar = Math.max(0, num(obs.solar, 0));
  const carried = Math.max(0, num(obs.carried, 0));
  const delivered = Math.max(0, num(obs.delivered, 0));
  const science = Math.max(0, num(obs.science, 0));
  const pitch = num(obs.pitch, 0);
  const reportedT = num(obs.t, mem.clock || 0);

  if (!mem._ready) {
    const mission = obs.mission || {};
    let mapW = 400;
    let mapH = 400;
    const size = mission.size;
    if (typeof size === "number") {
      mapW = size;
      mapH = size;
    } else if (Array.isArray(size)) {
      mapW = num(size[0], 400);
      mapH = num(size[1], mapW);
    } else if (size && typeof size === "object") {
      mapW = num(size.width, num(size.x, 400));
      mapH = num(size.height, num(size.y, mapW));
    } else {
      mapW = num(mission.width, 400);
      mapH = num(mission.height, 400);
    }

    const base = mission.base || {};
    mem.mapW = mapW;
    mem.mapH = mapH;
    mem.baseX = num(base.x, mapW * 0.5);
    mem.baseY = num(base.y, mapH * 0.5);
    mem.capacity = Math.max(1, num(mission.capacity, 5));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));

    mem.hints = [];
    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const x = num(h.x, NaN);
      const y = num(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      let value = num(h.estimate, num(h.value, 1));
      if (!(value > 0)) value = 0.2;
      mem.hints.push({
        x: clamp(x, 2, mapW - 2),
        y: clamp(y, 2, mapH - 2),
        value: value,
        status: 0,
        blockedUntil: 0
      });
    }

    mem.grid = [];
    let ix = 0;
    for (let x = 25; x <= mapW - 10; x += 50, ix++) {
      let iy = 0;
      for (let y = 25; y <= mapH - 10; y += 50, iy++) {
        mem.grid.push({
          x: clamp(x, 4, mapW - 4),
          y: clamp(y, 4, mapH - 4),
          key: "g:" + ix + ":" + iy
        });
      }
    }
    if (mem.grid.length === 0) {
      mem.grid.push({
        x: mapW * 0.5,
        y: mapH * 0.5,
        key: "g:0:0"
      });
    }

    mem.gridVisited = {};
    mem.task = null;
    mem.search = null;
    mem.returning = false;
    mem.bootstrapDone = false;
    mem.nextTaskId = 1;

    mem.clock = reportedT;
    mem._lastT = undefined;
    mem.headingOffset = 0;
    mem.lastHeadRaw = undefined;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.rawPrevX = rawX;
    mem.rawPrevY = rawY;
    mem.gpsFrozen = false;
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;
    mem.posDX = 0;
    mem.posDY = 0;

    mem.calPrevX = rawX;
    mem.calPrevY = rawY;
    mem.calActive = false;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;

    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.maxBattery = battery;
    mem.burn = 0.00075;
    mem.energyBucket = 0;
    mem.distanceBucket = 0;

    mem.prevCarried = carried;
    mem.prevDelivered = delivered;
    mem.sampling = false;
    mem.sampleX = rawX;
    mem.sampleY = rawY;
    mem.sampleSiteX = null;
    mem.sampleSiteY = null;
    mem.sampleStartDistance = 0;
    mem.stillTicks = 0;
    mem.holdI = 0;

    mem.siteX = null;
    mem.siteY = null;
    mem.siteLastSeen = -1000;
    mem.siteLastDistance = 99;

    mem.motorI = [0, 0];
    mem.lastWheelTarget = [0, 0];
    mem.lastV = 0;
    mem.lastSteer = 0;

    mem.navKey = "";
    mem.navBestDist = 1e9;
    mem.navProgressT = reportedT;
    mem.recoverUntil = 0;
    mem.recoverSign = 1;
    mem.lastBumped = false;
    mem.bumpCount = 0;

    mem.slipTicks = 0;
    mem.sandUntil = 0;

    mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayDisabled = [false, false, false, false, false, false, false, false, false];
    mem.rayTravel = 0;
    mem.maxRayTravel = 0;

    mem.dockWaitKey = "";
    mem.dockWaitStart = 0;
    mem.dockWaitBattery = battery;
    mem._ready = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.grid)) mem.grid = [];
  if (!mem.gridVisited) mem.gridVisited = {};
  if (!Array.isArray(mem.motorI)) mem.motorI = [0, 0];
  if (!Array.isArray(mem.lastWheelTarget)) mem.lastWheelTarget = [0, 0];
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  if (!Array.isArray(mem.rayDisabled)) mem.rayDisabled = [false, false, false, false, false, false, false, false, false];

  let dt = 0.1;
  if (mem._lastT !== undefined) {
    const td = reportedT - mem._lastT;
    if (td > 0.015 && td < 0.7) dt = td;
  }
  mem._lastT = reportedT;
  const clock = reportedT;
  mem.clock = clock;

  const oldCarried = num(mem.prevCarried, carried);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const justSampled = carried > oldCarried + 0.1;
  const justDelivered = delivered > oldDelivered + 0.1;

  let headingTrue = headingRaw;
  if (mem.lastHeadRaw !== undefined) {
    const rawDelta = wrap(headingRaw - mem.lastHeadRaw);
    const expectedDelta = (wheelRight - wheelLeft) / 0.6 * dt / RAD;
    const mismatch = wrap(rawDelta - expectedDelta);
    if (Math.abs(mismatch) > 55 && Math.abs(expectedDelta) < 30) {
      mem.headingOffset = wrap(num(mem.headingOffset, 0) + mismatch);
    }
  }
  mem.lastHeadRaw = headingRaw;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  const oldPX = num(mem.posX, rawX);
  const oldPY = num(mem.posY, rawY);
  const rawStep = dist(rawX, rawY, num(mem.rawPrevX, rawX), num(mem.rawPrevY, rawY));

  if (mem.gpsFrozen) {
    if (rawStep > 0.8) {
      mem.gpsFrozen = false;
      mem.gpsFreezeCount = 0;
      mem.freezeAccX = 0;
      mem.freezeAccY = 0;
      mem.posX = rawX;
      mem.posY = rawY;
    } else if (wheelAbs > 0.12 && !bumped) {
      const dx = wheelAvg * Math.cos(headingTrue * RAD) * dt;
      const dy = wheelAvg * Math.sin(headingTrue * RAD) * dt;
      mem.posX += dx;
      mem.posY += dy;
    }
  } else if (rawStep < 0.025 && wheelAbs > 0.32 && !docked && !bumped) {
    mem.gpsFreezeCount = (mem.gpsFreezeCount || 0) + 1;
    mem.freezeAccX = num(mem.freezeAccX, 0) + wheelAvg * Math.cos(headingTrue * RAD) * dt;
    mem.freezeAccY = num(mem.freezeAccY, 0) + wheelAvg * Math.sin(headingTrue * RAD) * dt;
    if (mem.gpsFreezeCount >= 8) {
      mem.gpsFrozen = true;
      mem.posX = rawX + mem.freezeAccX;
      mem.posY = rawY + mem.freezeAccY;
    } else {
      mem.posX = 0.55 * oldPX + 0.45 * rawX;
      mem.posY = 0.55 * oldPY + 0.45 * rawY;
    }
  } else {
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;
    if (rawStep > 7 && !docked) {
      mem.posX = oldPX;
      mem.posY = oldPY;
    } else {
      mem.posX = 0.55 * oldPX + 0.45 * rawX;
      mem.posY = 0.55 * oldPY + 0.45 * rawY;
    }
  }

  mem.rawPrevX = rawX;
  mem.rawPrevY = rawY;

  let px = num(mem.posX, rawX);
  let py = num(mem.posY, rawY);
  let stepX = px - oldPX;
  let stepY = py - oldPY;
  let stepDist = Math.hypot(stepX, stepY);

  const calDX = rawX - num(mem.calPrevX, rawX);
  const calDY = rawY - num(mem.calPrevY, rawY);
  if (!docked && !mem.gpsFrozen && wheelAvg > 0.3 &&
      Math.abs(wheelRight - wheelLeft) < 0.17 && rawStep < 1.5) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calDX = 0;
      mem.calDY = 0;
      mem.calSin = 0;
      mem.calCos = 0;
      mem.calN = 0;
    }
    mem.calDX += calDX;
    mem.calDY += calDY;
    mem.calSin += Math.sin(headingTrue * RAD);
    mem.calCos += Math.cos(headingTrue * RAD);
    mem.calN++;
    if (Math.hypot(mem.calDX, mem.calDY) > 5 && mem.calN > 12) {
      const track = Math.atan2(mem.calDY, mem.calDX) / RAD;
      const avgHeading = Math.atan2(mem.calSin, mem.calCos) / RAD;
      const error = wrap(avgHeading - track);
      if (Math.abs(error) < 55) {
        mem.headingOffset = wrap(
          num(mem.headingOffset, 0) + clamp(error * 0.18, -12, 12)
        );
      }
      mem.calActive = false;
      mem.calDX = 0;
      mem.calDY = 0;
      mem.calSin = 0;
      mem.calCos = 0;
      mem.calN = 0;
    }
  } else {
    mem.calActive = false;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;
  }
  mem.calPrevX = rawX;
  mem.calPrevY = rawY;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  const timeLeft = Math.max(0, num(obs.timeLeft, mem.totalSeconds - clock));
  const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const hasRays = !!(obs.rays && typeof obs.rays.length === "number");
  const rays = [];
  let allMax = hasRays;
  let disabledCount = 0;
  for (let i = 0; i < 9; i++) {
    const r = clamp(num(hasRays ? obs.rays[i] : 15, 15), 0, 15);
    rays.push(r);
    if (r < 14.7) allMax = false;
    if (Math.abs(r - num(mem.rayLast[i], 15)) < 0.025) {
      mem.rayStale[i] = (mem.rayStale[i] || 0) + 1;
    } else {
      mem.rayStale[i] = 0;
      if (mem.rayDisabled[i] && Math.abs(r - mem.rayLast[i]) > 0.5) {
        mem.rayDisabled[i] = false;
      }
    }
    mem.rayLast[i] = r;
  }

  mem.rayTravel = num(mem.rayTravel, 0) + stepDist;
  if (mem.rayTravel > 8) {
    for (let i = 0; i < 9; i++) {
      if (mem.rayStale[i] > 120 && rays[i] < 14.7) {
        mem.rayDisabled[i] = true;
      }
    }
    mem.rayTravel = 0;
  }
  disabledCount = 0;
  for (let i = 0; i < 9; i++) {
    if (mem.rayDisabled[i]) disabledCount++;
  }
  if (allMax && wheelAbs > 0.15) {
    mem.maxRayTravel = num(mem.maxRayTravel, 0) + stepDist;
  } else {
    mem.maxRayTravel = 0;
  }
  const raysBlind = !hasRays || disabledCount >= 5 || mem.maxRayTravel > 35;

  const groundSpeed = stepDist / Math.max(0.04, dt);
  if (wheelAbs > 0.8 && groundSpeed < 0.27 && !bumped && !docked) {
    mem.slipTicks = (mem.slipTicks || 0) + 1;
    if (mem.slipTicks > 20) mem.sandUntil = clock + 12;
  } else {
    mem.slipTicks = Math.max(0, (mem.slipTicks || 0) - 1);
  }

  const oldBattery = num(mem.prevBattery, battery);
  const db = oldBattery - battery;
  if (!docked && wheelAbs > 0.12 && Math.abs(db) < 0.08) {
    mem.energyBucket = num(mem.energyBucket, 0) +
      Math.max(0, db + solar * dt * 0.06);
    if (stepDist > 0.025) {
      mem.distanceBucket = num(mem.distanceBucket, 0) + stepDist;
    }
    if (mem.distanceBucket >= 8) {
      const load = 1 + 0.20 * carried;
      const measured = mem.energyBucket / Math.max(1, mem.distanceBucket) / load;
      if (measured > 0.00008 && measured < 0.02) {
        const alpha = measured > mem.burn ? 0.34 : 0.12;
        mem.burn = clamp(
          mem.burn * (1 - alpha) + measured * alpha,
          0.00025,
          0.008
        );
      }
      mem.energyBucket = 0;
      mem.distanceBucket = 0;
    }
  }
  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);

  let siteVisible = false;
  let siteDistance = 99;
  let siteBearing = 0;
  const siteObs = obs.site;
  if (siteObs && Number.isFinite(Number(siteObs.distance))) {
    siteDistance = clamp(num(siteObs.distance, 99), 0, 20);
    siteBearing = wrap(num(siteObs.bearing, 0));
    const a = (headingTrue + siteBearing) * RAD;
    const sx = px + siteDistance * Math.cos(a);
    const sy = py + siteDistance * Math.sin(a);
    if (Number.isFinite(sx) && Number.isFinite(sy)) {
      if (!Number.isFinite(mem.siteX) || !Number.isFinite(mem.siteY)) {
        mem.siteX = sx;
        mem.siteY = sy;
      } else {
        mem.siteX = 0.55 * mem.siteX + 0.45 * sx;
        mem.siteY = 0.55 * mem.siteY + 0.45 * sy;
      }
      mem.siteLastSeen = clock;
      mem.siteLastDistance = siteDistance;
      siteVisible = true;
    }
  } else if (!mem.sampling && clock - num(mem.siteLastSeen, -1000) > 5) {
    mem.siteX = null;
    mem.siteY = null;
  }

  const suppressOldSite = justSampled && siteVisible && siteDistance < 3;
  if (justSampled) {
    const sx = Number.isFinite(mem.sampleX) ? mem.sampleX : px;
    const sy = Number.isFinite(mem.sampleY) ? mem.sampleY : py;
    const task = mem.task;
    const search = mem.search;
    let matched = false;

    if (task) {
      const linkedSearch = !!(search && search.key === task.key);
      let closeToTask = dist(sx, sy, task.x, task.y) < 27;
      if (task.kind === "local") closeToTask = true;
      if (linkedSearch || closeToTask) {
        matched = true;
        if (task.kind === "hint" &&
            task.index >= 0 && task.index < mem.hints.length) {
          mem.hints[task.index].status = 1;
        } else if (task.kind === "grid") {
          mem.gridVisited[task.key] = true;
        } else if (task.kind === "local") {
          mem.bootstrapDone = true;
        }
        mem.task = null;
        mem.search = null;
      }
    }

    let nearestHint = -1;
    let nearestDistance = 25;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status !== 0) continue;
      const d = dist(sx, sy, mem.hints[i].x, mem.hints[i].y);
      if (d < nearestDistance) {
        nearestDistance = d;
        nearestHint = i;
      }
    }
    if (nearestHint >= 0) {
      mem.hints[nearestHint].status = 1;
      if (mem.task && mem.task.kind === "hint" &&
          mem.task.index === nearestHint) {
        mem.task = null;
        mem.search = null;
      }
    }

    mem.sampling = false;
    mem.stillTicks = 0;
    mem.holdI = 0;
    mem.siteX = null;
    mem.siteY = null;
    mem.siteLastSeen = -1000;
    mem.bootstrapDone = true;
    mem.dockWaitKey = "";
  }

  if (justDelivered || (docked && carried < oldCarried)) {
    mem.returning = false;
    mem.sampling = false;
    mem.siteX = null;
    mem.siteY = null;
    mem.siteLastSeen = -1000;
    mem.dockWaitKey = "";
  }
  mem.prevCarried = carried;
  mem.prevDelivered = delivered;

  if (bumped && !mem.lastBumped) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.25, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.03) {
      mem.recoverSign = Math.sign(siteBearing || 1);
    } else {
      mem.recoverSign = rightDanger > leftDanger ? 1 : -1;
    }
    mem.recoverUntil = clock + 1.35;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
  }
  mem.lastBumped = bumped;

  function motorCommand(index, target, actual, bias) {
    target = clamp(target, -2.65, 2.65);
    let integ = num(mem.motorI[index], 0);
    const last = num(mem.lastWheelTarget[index], 0);

    if (target * last < -0.05) integ = 0;
    const error = target - actual;
    let raw;

    if (Math.abs(target) < 0.06) {
      integ *= 0.24;
      raw = 0.30 * error + integ + bias;
    } else {
      raw = target / 2.7 + 0.30 * error + integ + bias;
      const proposed = clamp(integ + 0.42 * error * dt, -0.44, 0.44);
      if (Math.abs(raw) < 0.97 || error * raw < 0) integ = proposed;
      raw = target / 2.7 + 0.30 * error + integ + bias;
      if (Math.abs(target) > 0.16 && Math.abs(actual) < 0.05 &&
          Math.abs(raw) < 0.105) {
        raw = Math.sign(target) * 0.105 + bias;
      }
    }

    mem.motorI[index] = clamp(integ, -0.44, 0.44);
    mem.lastWheelTarget[index] = target;
    return clamp(raw, -1, 1);
  }

  function drive(v, omega, holdBias) {
    let leftTarget = v - omega * 0.30;
    let rightTarget = v + omega * 0.30;
    const maxWheel = Math.max(Math.abs(leftTarget), Math.abs(rightTarget));
    if (maxWheel > 2.65) {
      const scale = 2.65 / maxWheel;
      leftTarget *= scale;
      rightTarget *= scale;
      v *= scale;
    }
    const bias = clamp(num(holdBias, 0), -0.28, 0.28);
    mem.lastV = v;
    return {
      left: motorCommand(0, leftTarget, wheelLeft, bias),
      right: motorCommand(1, rightTarget, wheelRight, bias),
      drill: false
    };
  }

  function stopOutput() {
    return drive(0, 0, 0);
  }

  function dangerTurn(goalErr) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.3, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.02) {
      return Math.sign(goalErr || 1);
    }
    return rightDanger > leftDanger ? 1 : -1;
  }

  function navigation(goalErr, goalDist, mode, key) {
    goalErr = wrap(goalErr);
    goalDist = Math.max(0, num(goalDist, 0));

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestDist = goalDist;
      mem.navProgressT = clock;
    } else if (goalDist < num(mem.navBestDist, 1e9) - 0.35) {
      mem.navBestDist = goalDist;
      mem.navProgressT = clock;
    }

    if (clock - num(mem.navProgressT, clock) > 25 &&
        clock >= num(mem.recoverUntil, 0)) {
      mem.recoverSign = dangerTurn(goalErr);
      mem.recoverUntil = clock + 1.1;
      mem.navProgressT = clock;
      mem.navBestDist = goalDist;
    }

    if (clock < num(mem.recoverUntil, 0)) {
      const sign = num(mem.recoverSign, 1) || 1;
      return drive(-0.38, sign * 1.08, 0);
    }

    if (Math.abs(goalErr) > 118) {
      return drive(0, (Math.sign(goalErr) || 1) * 1.35, 0);
    }

    const desired = clamp(goalErr, -90, 90);
    const candidates = [-100, -85, -70, -55, -40, -25, -10, 0,
                         10, 25, 40, 55, 70, 85, 100, desired];
    let bestAngle = desired;
    let bestCost = 1e30;
    let bestAhead = 1e9;
    const look = 9;

    for (let c = 0; c < candidates.length; c++) {
      const a = candidates[c];
      const ar = a * RAD;
      const ca = Math.cos(ar);
      const sa = Math.sin(ar);
      let cost = Math.pow(wrap(a - desired) / 36, 2) +
                 0.001 * Math.abs(wrap(a - num(mem.lastSteer, 0)));
      let ahead = 1e9;

      for (let i = 0; i < 9; i++) {
        if (mem.rayDisabled[i]) continue;
        const r0 = rays[i];
        if (!(r0 > 0.05) || r0 >= 14.75) continue;

        const r = Math.max(0.15, r0 - 0.38);
        const rr = rayAngles[i] * RAD;
        const ox = r * Math.cos(rr);
        const oy = r * Math.sin(rr);
        const along = ox * ca + oy * sa;
        if (along < -0.25 || along > look) continue;
        const lateral = Math.abs(-ox * sa + oy * ca);

        if (lateral < 2.45) {
          const penetration = Math.max(0, 2.0 - lateral);
          if (penetration > 0) {
            cost += penetration * penetration *
              (0.75 + 2.3 / (Math.max(0.35, along) + 0.55));
          } else if (lateral < 2.45) {
            cost += 0.07 * Math.pow(2.45 - lateral, 2);
          }
        }
        if (along > 0 && lateral < 1.75) {
          ahead = Math.min(ahead, along);
        }
      }

      const globalAngle = (headingTrue + a) * RAD;
      const nx = px + 7 * Math.cos(globalAngle);
      const ny = py + 7 * Math.sin(globalAngle);
      if (nx < 3) cost += 2.2 * Math.pow(3 - nx, 2);
      if (ny < 3) cost += 2.2 * Math.pow(3 - ny, 2);
      if (nx > mem.mapW - 3) cost += 2.2 * Math.pow(nx - (mem.mapW - 3), 2);
      if (ny > mem.mapH - 3) cost += 2.2 * Math.pow(ny - (mem.mapH - 3), 2);

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
        bestAhead = ahead;
      }
    }
    mem.lastSteer = bestAngle;

    let cruise = mode === "return" ? 1.18 : (mode === "site" ? 1.12 : 1.30);
    if (raysBlind) cruise = Math.min(cruise, 0.88);
    if (mem.bumpCount >= 4) cruise = Math.min(cruise, 1.0);
    if (clock < num(mem.sandUntil, 0)) cruise = Math.min(cruise, 0.65);

    let speed = cruise;
    speed *= clamp(1 - Math.max(0, Math.abs(bestAngle) - 28) / 82, 0.22, 1);

    if (mode === "site") {
      if (goalDist < 8) {
        speed = Math.min(speed, Math.max(0.10, (goalDist - 0.65) * 0.42));
      }
      if (goalDist <= 1.22) speed = 0;
    } else if (mode === "return") {
      if (goalDist < 12) {
        speed = Math.min(speed, Math.max(0.14, 0.18 + 0.10 * goalDist));
      }
      if (goalDist <= 2.4) speed = 0;
    } else {
      if (goalDist < 10) {
        speed = Math.min(speed,
          Math.max(0.14, Math.sqrt(Math.max(0, goalDist - 1.8) * 0.35)));
      }
      if (goalDist <= 2.5) speed = 0;
    }

    if (bestAhead < 1.35) speed = Math.min(speed, 0.16);
    else if (bestAhead < 2.4) speed = Math.min(speed, 0.32);
    else if (bestAhead < 3.6) speed = Math.min(speed, 0.52);
    else if (bestAhead < 5.2) speed = Math.min(speed, 0.78);
    else if (bestAhead < 7.5) speed = Math.min(speed, 1.0);

    const ga = (headingTrue + bestAngle) * RAD;
    const dx = Math.cos(ga);
    const dy = Math.sin(ga);
    if ((px < 5 && dx < 0) || (py < 5 && dy < 0) ||
        (px > mem.mapW - 5 && dx > 0) ||
        (py > mem.mapH - 5 && dy > 0)) {
      speed = Math.min(speed, 0.35);
    }

    const omega = clamp(2.05 * bestAngle * RAD, -1.72, 1.72);
    return drive(speed, omega, 0);
  }

  function baseDistanceNow() {
    const gpsD = dist(px, py, mem.baseX, mem.baseY);
    const beacon = obs.beacon;
    if (beacon && Number.isFinite(Number(beacon.distance))) {
      const d = clamp(num(beacon.distance, gpsD), 0, 100);
      if (d <= 25) return d;
    }
    return gpsD;
  }

  const beacon = obs.beacon;
  const beaconDistance =
    beacon && Number.isFinite(Number(beacon.distance))
      ? clamp(num(beacon.distance, 100), 0, 100)
      : null;
  const baseDistance = baseDistanceNow();

  function returnCost(d, n) {
    const count = Math.max(0, n);
    return Math.max(0, d) * mem.burn * (1 + 0.20 * count) * 2.0 +
      0.10 + 0.025 * count;
  }

  function returnTime(d) {
    return Math.max(0, d) / 0.72 + 18;
  }

  function taskExtra(task) {
    if (!task) return 0;
    if (mem.search && mem.search.key === task.key) {
      const s = mem.search;
      const steps = s.steps || [];
      const currentStep = steps[s.stepIndex] || 8;
      const remPoints = Math.max(0, s.points.length - s.idx);
      let future = 0;
      for (let j = s.stepIndex + 1; j < steps.length; j++) {
        future += steps[j] * 6.2;
      }
      return Math.min(
        task.kind === "grid" ? 180 : 155,
        Math.max(18, remPoints * currentStep * 0.78 + future)
      );
    }
    if (task.kind === "hint") return 155;
    if (task.kind === "grid") return 175;
    return 85;
  }

  function taskNeed(task, n) {
    if (!task) return 1e9;
    const d1 = dist(px, py, task.x, task.y);
    const d2 = dist(task.x, task.y, mem.baseX, mem.baseY);
    const load = 1 + 0.20 * (Math.max(0, n) + 0.5);
    const extra = taskExtra(task);
    return (d1 + d2 + extra) * mem.burn * load * 1.75 +
      0.13 + 0.025 * (Math.max(0, n) + 1);
  }

  function taskTime(task) {
    if (!task) return 1e9;
    const d1 = dist(px, py, task.x, task.y);
    const d2 = dist(task.x, task.y, mem.baseX, mem.baseY);
    return (d1 + d2 + taskExtra(task)) * 1.48 + 32;
  }

  function makeRing(cx, cy, radius, count) {
    const points = [];
    for (let i = 0; i < count; i++) {
      const a = 2 * PI * i / count;
      const x = clamp(cx + radius * Math.cos(a), 3, mem.mapW - 3);
      const y = clamp(cy + radius * Math.sin(a), 3, mem.mapH - 3);
      let duplicate = false;
      for (let j = 0; j < points.length; j++) {
        if (dist(x, y, points[j].x, points[j].y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) points.push({ x: x, y: y });
    }
    if (points.length > 1) {
      let nearest = 0;
      let nearestD = 1e30;
      for (let i = 0; i < points.length; i++) {
        const d = dist(px, py, points[i].x, points[i].y);
        if (d < nearestD) {
          nearestD = d;
          nearest = i;
        }
      }
      return points.slice(nearest).concat(points.slice(0, nearest));
    }
    return points;
  }

  function startSearch(task, initialScience) {
    if (!task) return;
    const s = {
      kind: task.kind,
      key: task.key,
      index: task.index,
      cx: task.x,
      cy: task.y,
      centerS: Math.max(0, initialScience),
      stepIndex: 0,
      steps: [],
      count: 8,
      points: [],
      idx: 0,
      pointStart: clock,
      arriveT: null,
      ringBestS: Math.max(0, initialScience),
      bestX: task.x,
      bestY: task.y,
      moves: 0
    };

    if (task.kind === "hint" && initialScience <= 0.000001) {
      s.steps = [10, 20];
    } else if (task.kind === "grid") {
      s.steps = [9, 19, 31];
      s.count = 12;
    } else if (task.kind === "local") {
      s.steps = [7, 14, 22];
    } else {
      s.steps = [6, 12, 20];
    }

    s.points = makeRing(s.cx, s.cy, s.steps[0], s.count);
    s.pointStart = clock;
    s.ringBestS = s.centerS;
    s.bestX = s.cx;
    s.bestY = s.cy;
    mem.task = task;
    mem.search = s;
  }

  function finishSearch() {
    const s = mem.search;
    if (!s) return;
    if (s.kind === "hint" && s.index >= 0 && s.index < mem.hints.length) {
      if (mem.hints[s.index].status === 0) mem.hints[s.index].status = 2;
    } else if (s.kind === "grid") {
      mem.gridVisited[s.key] = true;
    } else if (s.kind === "local") {
      mem.bootstrapDone = true;
    }
    if (mem.task && mem.task.key === s.key) mem.task = null;
    mem.search = null;
    mem.dockWaitKey = "";
  }

  function nextSearchRing() {
    const s = mem.search;
    if (!s) return;

    const gain = s.ringBestS - s.centerS;
    const threshold = Math.max(0.0000005, Math.abs(s.centerS) * 0.035);
    const moved = dist(s.cx, s.cy, s.bestX, s.bestY);

    if (gain > threshold && moved > 2.5 && s.moves < 5) {
      s.cx = s.bestX;
      s.cy = s.bestY;
      s.centerS = s.ringBestS;
      s.moves++;
      s.stepIndex = 0;
    } else {
      s.stepIndex++;
    }

    if (s.stepIndex >= s.steps.length) {
      finishSearch();
      return;
    }

    s.points = makeRing(s.cx, s.cy, s.steps[s.stepIndex], s.count);
    s.idx = 0;
    s.pointStart = clock;
    s.arriveT = null;
    s.ringBestS = s.centerS;
    s.bestX = s.cx;
    s.bestY = s.cy;
    if (s.points.length === 0) finishSearch();
  }

  function advanceSearchPoint() {
    const s = mem.search;
    if (!s) return;
    s.idx++;
    s.arriveT = null;
    s.pointStart = clock;
    if (s.idx >= s.points.length) nextSearchRing();
  }

  function updateSearch() {
    const s = mem.search;
    if (!s) return;
    if (!s.points || s.points.length === 0) {
      finishSearch();
      return;
    }
    if (s.idx >= s.points.length) {
      nextSearchRing();
      return;
    }

    const target = s.points[s.idx];
    const d = dist(px, py, target.x, target.y);
    if (d < 2.8) {
      if (s.arriveT === null) s.arriveT = clock;
      if (clock - s.arriveT >= 0.35) {
        if (science > s.ringBestS) {
          s.ringBestS = science;
          s.bestX = px;
          s.bestY = py;
        }
        advanceSearchPoint();
      }
    } else {
      s.arriveT = null;
      if (clock - s.pointStart > 38) advanceSearchPoint();
    }
  }

  function taskObject(kind, x, y, key, index, value) {
    return {
      kind: kind,
      x: clamp(x, 3, mem.mapW - 3),
      y: clamp(y, 3, mem.mapH - 3),
      key: key || ("t:" + (mem.nextTaskId++)),
      index: index === undefined ? -1 : index,
      value: value === undefined ? 1 : value
    };
  }

  function chooseTask() {
    const budget = docked
      ? Math.max(battery, num(mem.maxBattery, battery))
      : battery;
    let best = null;
    let bestScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0 || num(h.blockedUntil, 0) > clock) continue;
      const task = taskObject("hint", h.x, h.y, "h:" + i, i, h.value);
      const d1 = dist(px, py, task.x, task.y);
      const d2 = dist(task.x, task.y, mem.baseX, mem.baseY);
      const extra = 155;
      const load = 1 + 0.20 * (carried + 0.5);
      const need = (d1 + d2 + extra) * mem.burn * load * 1.75 +
        0.13 + 0.025 * (carried + 1);
      const tneed = (d1 + d2 + extra) * 1.48 + 32;
      if (need > budget - 0.025 || tneed > timeLeft - 8) continue;
      const cost = 25 + d1 + 0.72 * d2 + extra * 0.22;
      const score = Math.max(0.05, h.value) / Math.pow(Math.max(1, cost), 0.90);
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }

    if (best) return best;

    let gridBest = null;
    let gridCost = 1e30;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (!g || mem.gridVisited[g.key]) continue;
      const d1 = dist(px, py, g.x, g.y);
      const d2 = dist(g.x, g.y, mem.baseX, mem.baseY);
      const extra = 175;
      const load = 1 + 0.20 * (carried + 0.5);
      const need = (d1 + d2 + extra) * mem.burn * load * 1.75 +
        0.13 + 0.025 * (carried + 1);
      const tneed = (d1 + d2 + extra) * 1.48 + 32;
      if (need > budget - 0.025 || tneed > timeLeft - 8) continue;
      const cost = d1 + 0.52 * d2;
      if (cost < gridCost) {
        gridCost = cost;
        gridBest = taskObject("grid", g.x, g.y, g.key, -1, 1);
      }
    }
    return gridBest;
  }

  function ensureTask() {
    if (mem.task && mem.task.kind === "hint") {
      const i = mem.task.index;
      if (i < 0 || i >= mem.hints.length || mem.hints[i].status !== 0) {
        mem.task = null;
        mem.search = null;
      }
    }

    if (mem.task || mem.search || mem.returning) return;

    if (!mem.bootstrapDone) {
      mem.bootstrapDone = true;
      if (!siteVisible && science > 0.000001) {
        const local = taskObject(
          "local",
          px,
          py,
          "local:0",
          -1,
          1
        );
        startSearch(local, science);
        return;
      }
    }

    const task = chooseTask();
    if (task) {
      mem.task = task;
      if (task.kind === "local") startSearch(task, science);
    }
  }

  function taskBearing(task) {
    const bearing = Math.atan2(task.y - py, task.x - px) / RAD;
    return wrap(bearing - headingTrue);
  }

  function goHome() {
    if (docked || baseDistance <= 2.4) return stopOutput();
    let err;
    if (beacon && beaconDistance !== null && beaconDistance <= 25 &&
        Number.isFinite(Number(beacon.bearing))) {
      err = num(beacon.bearing, 0);
    } else {
      const bearing = Math.atan2(mem.baseY - py, mem.baseX - px) / RAD;
      err = wrap(bearing - headingTrue);
    }
    return navigation(err, baseDistance, "return", "base");
  }

  function sampleOutput() {
    if (!mem.sampling) return null;

    let d = 99;
    let inRange = false;
    if (siteVisible && !suppressOldSite) {
      d = siteDistance;
      inRange = d <= 1.52;
      mem.siteLastSeen = clock;
      mem.siteLastDistance = d;
    } else if (Number.isFinite(mem.sampleSiteX) &&
               Number.isFinite(mem.sampleSiteY)) {
      d = dist(px, py, mem.sampleSiteX, mem.sampleSiteY);
      inRange = d <= 1.48;
      if (!inRange && clock - num(mem.siteLastSeen, -1000) < 1.2 &&
          dist(px, py, mem.sampleX, mem.sampleY) < 0.45 &&
          mem.sampleStartDistance <= 1.35) {
        inRange = true;
      }
    }

    if (!inRange || d > 1.75) {
      mem.sampling = false;
      mem.stillTicks = 0;
      mem.holdI = 0;
      return null;
    }

    if (!docked) {
      const reserve = returnCost(baseDistance, carried + 1);
      if (battery < reserve + 0.015 ||
          timeLeft < returnTime(baseDistance) + 6) {
        mem.sampling = false;
        mem.returning = true;
        return null;
      }
    }

    const still = Math.abs(wheelLeft) < 0.13 &&
                  Math.abs(wheelRight) < 0.13;
    if (still) mem.stillTicks = (mem.stillTicks || 0) + 1;
    else mem.stillTicks = 0;

    const ex = num(mem.sampleX, px) - px;
    const ey = num(mem.sampleY, py) - py;
    const along = ex * Math.cos(headingTrue * RAD) +
                  ey * Math.sin(headingTrue * RAD);
    const velAlong = (stepX * Math.cos(headingTrue * RAD) +
                      stepY * Math.sin(headingTrue * RAD)) /
                     Math.max(0.04, dt);

    if (Math.abs(along) > 0.06) {
      mem.holdI = clamp(
        num(mem.holdI, 0) + 0.012 * along * dt,
        -0.14,
        0.14
      );
    }
    const hold = clamp(
      0.012 * clamp(pitch, -25, 25) +
      0.038 * along +
      num(mem.holdI, 0) -
      0.055 * velAlong,
      -0.25,
      0.25
    );

    const cmd = drive(0, 0, hold);
    return {
      left: cmd.left,
      right: cmd.right,
      drill: !!(still && d <= 1.52)
    };
  }

  if (justDelivered || docked) mem.returning = false;

  if (docked && carried > 0) return stopOutput();

  if (!mem.sampling && siteVisible && !suppressOldSite &&
      siteDistance <= 1.25 && carried < mem.capacity) {
    mem.sampling = true;
    mem.sampleX = px;
    mem.sampleY = py;
    mem.sampleSiteX = Number.isFinite(mem.siteX) ? mem.siteX : null;
    mem.sampleSiteY = Number.isFinite(mem.siteY) ? mem.siteY : null;
    mem.sampleStartDistance = siteDistance;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }

  if (mem.sampling) {
    const out = sampleOutput();
    if (out) return out;
  }

  if (!mem.returning) ensureTask();

  if (!docked && !mem.returning) {
    const reserve = returnCost(baseDistance, carried);
    if (carried >= mem.capacity ||
        battery < reserve + (carried > 0 ? 0.025 : 0.085) ||
        timeLeft < returnTime(baseDistance) + (carried > 0 ? 8 : 2)) {
      mem.returning = true;
    } else if (carried > 0 && mem.task &&
               taskNeed(mem.task, carried) > battery - 0.02) {
      mem.returning = true;
    }
  }

  if (mem.returning) return goHome();

  let siteGoal = false;
  let siteGoalDistance = 99;
  if (siteVisible && !suppressOldSite) {
    siteGoal = true;
    siteGoalDistance = siteDistance;
  } else if (!justSampled &&
             Number.isFinite(mem.siteX) &&
             Number.isFinite(mem.siteY) &&
             clock - num(mem.siteLastSeen, -1000) < 3.5) {
    siteGoal = true;
    siteGoalDistance = dist(px, py, mem.siteX, mem.siteY);
  }

  if (siteGoal) {
    if (carried >= mem.capacity) {
      mem.returning = true;
      return goHome();
    }

    const safeDistance = baseDistance + Math.max(0, siteGoalDistance);
    if (battery < returnCost(safeDistance, carried + 1) + 0.02 ||
        timeLeft < returnTime(safeDistance) + 7) {
      mem.returning = true;
      return goHome();
    }

    if (siteGoalDistance <= 1.25) {
      if (!mem.sampling) {
        mem.sampling = true;
        mem.sampleX = px;
        mem.sampleY = py;
        mem.sampleSiteX = Number.isFinite(mem.siteX) ? mem.siteX : null;
        mem.sampleSiteY = Number.isFinite(mem.siteY) ? mem.siteY : null;
        mem.sampleStartDistance = siteGoalDistance;
        mem.stillTicks = 0;
        mem.holdI = 0;
      }
      const out = sampleOutput();
      if (out) return out;
    }

    if (siteVisible && !suppressOldSite) {
      return navigation(wrap(siteBearing), siteDistance, "site", "site");
    }
    const bearing = Math.atan2(mem.siteY - py, mem.siteX - px) / RAD;
    return navigation(
      wrap(bearing - headingTrue),
      siteGoalDistance,
      "site",
      "site-memory"
    );
  }

  if (mem.task && mem.task.kind === "hint") {
    const i = mem.task.index;
    if (i < 0 || i >= mem.hints.length || mem.hints[i].status !== 0) {
      mem.task = null;
      mem.search = null;
    }
  }

  for (let guard = 0; guard < 4; guard++) {
    if (!mem.task && !mem.search && !mem.returning) ensureTask();

    if (mem.search) {
      updateSearch();
      if (mem.search) {
        const s = mem.search;
        if (s.idx >= s.points.length) {
          updateSearch();
          if (!mem.search) continue;
        }
        if (mem.search) {
          const q = mem.search.points[mem.search.idx];
          if (q) {
            const d = dist(px, py, q.x, q.y);
            const key = "search:" + mem.search.key + ":" +
              mem.search.stepIndex + ":" + mem.search.idx + ":" +
              mem.search.moves;
            return navigation(taskBearing({ x: q.x, y: q.y }), d, "waypoint", key);
          }
        }
      }
      continue;
    }

    if (!mem.task) continue;

    const task = mem.task;
    if (task.kind === "local") {
      startSearch(task, science);
      continue;
    }

    const d = dist(px, py, task.x, task.y);
    if (d < 4.2) {
      if (task.kind === "grid" && science <= 0.000001) {
        mem.gridVisited[task.key] = true;
        mem.task = null;
        continue;
      }
      startSearch(task, science);
      continue;
    }

    if (!docked) {
      const need = taskNeed(task, carried);
      if (carried > 0 && need > battery - 0.02) {
        mem.returning = true;
        return goHome();
      }
      if (timeLeft < taskTime(task) + 8) {
        mem.returning = true;
        return goHome();
      }
    }

    if (docked) {
      const need = taskNeed(task, carried);
      if (battery < need + 0.015) {
        if (mem.dockWaitKey !== task.key) {
          mem.dockWaitKey = task.key;
          mem.dockWaitStart = clock;
          mem.dockWaitBattery = battery;
        } else if (battery > num(mem.dockWaitBattery, battery) + 0.025) {
          mem.dockWaitStart = clock;
          mem.dockWaitBattery = battery;
        }

        if (clock - num(mem.dockWaitStart, clock) > 120) {
          if (task.kind === "hint" &&
              task.index >= 0 && task.index < mem.hints.length) {
            mem.hints[task.index].blockedUntil = clock + 180;
          } else if (task.kind === "grid") {
            mem.gridVisited[task.key] = true;
          }
          mem.task = null;
          mem.search = null;
          mem.dockWaitKey = "";
        }
        return stopOutput();
      }
      mem.dockWaitKey = "";
    }

    if (docked && timeLeft < taskTime(task) + 10) return stopOutput();

    return navigation(taskBearing(task), d, "waypoint", "task:" + task.key);
  }

  if (!mem.task && !mem.search) ensureTask();

  if (mem.task || mem.search) {
    if (!docked && timeLeft < returnTime(baseDistance) + 8) {
      mem.returning = true;
      return goHome();
    }
    if (docked) return stopOutput();
  }

  if (!docked) {
    mem.returning = true;
    return goHome();
  }
  return stopOutput();
}

function act(obs, mem) {
  const PI = Math.PI;
  const RAD = PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  if (!mem || typeof mem !== "object") mem = {};

  const now = num(obs.t, num(mem.clock, 0));
  const rawX = num(obs.x, 200);
  const rawY = num(obs.y, 200);
  const headingRaw = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const wheelAvg = (wl + wr) * 0.5;
  const wheelAbs = (Math.abs(wl) + Math.abs(wr)) * 0.5;
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const battery = Math.max(0, num(obs.battery, 1));
  const solar = Math.max(0, num(obs.solar, 0));
  const carried = Math.max(0, num(obs.carried, 0));
  const carriedValue = Math.max(0, num(obs.carriedValue, 0));
  const delivered = Math.max(0, num(obs.delivered, 0));
  const pitch = num(obs.pitch, 0);
  const science = Math.max(0, num(obs.science, 0));

  if (!mem._init) {
    const mission = obs.mission || {};
    let mapW = 400;
    let mapH = 400;
    const size = mission.size;
    if (typeof size === "number") {
      mapW = size;
      mapH = size;
    } else if (Array.isArray(size)) {
      mapW = num(size[0], 400);
      mapH = num(size[1], mapW);
    } else if (size && typeof size === "object") {
      mapW = num(size.width, num(size.x, 400));
      mapH = num(size.height, num(size.y, mapW));
    } else {
      mapW = num(mission.width, 400);
      mapH = num(mission.height, 400);
    }
    mapW = Math.max(20, mapW);
    mapH = Math.max(20, mapH);

    const base = mission.base || {};
    mem.mapW = mapW;
    mem.mapH = mapH;
    mem.baseX = num(base.x, mapW * 0.5);
    mem.baseY = num(base.y, mapH * 0.5);
    mem.capacity = Math.max(1, num(mission.capacity, 5));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));

    mem.hints = [];
    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const x = num(h.x, NaN);
      const y = num(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      let value = num(h.estimate, num(h.value, 1));
      if (!(value > 0)) value = 0.2;
      mem.hints.push({
        x: clamp(x, 2, mapW - 2),
        y: clamp(y, 2, mapH - 2),
        value: value,
        status: 0,
        blockedUntil: 0
      });
    }

    mem.grid = [];
    let gxIndex = 0;
    for (let x = 25; x <= mapW - 20; x += 55, gxIndex++) {
      let gyIndex = 0;
      for (let y = 25; y <= mapH - 20; y += 55, gyIndex++) {
        mem.grid.push({
          x: clamp(x, 5, mapW - 5),
          y: clamp(y, 5, mapH - 5),
          key: "g:" + gxIndex + ":" + gyIndex
        });
      }
    }

    mem.gridVisited = {};
    mem.task = null;
    mem.search = null;
    mem.returning = false;

    mem.clock = now;
    mem._lastT = now;
    mem.headingOffset = 0;
    mem.lastHeadRaw = headingRaw;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.rawPrevX = rawX;
    mem.rawPrevY = rawY;
    mem.gpsFrozen = false;
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;

    mem.calPrevX = rawX;
    mem.calPrevY = rawY;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;

    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.maxBattery = battery;
    mem.burn = 0.0009;
    mem.energyBucket = 0;
    mem.distanceBucket = 0;

    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;

    mem.sampling = false;
    mem.sampleX = rawX;
    mem.sampleY = rawY;
    mem.sampleSiteX = null;
    mem.sampleSiteY = null;
    mem.lastSampleSiteX = null;
    mem.lastSampleSiteY = null;
    mem.sampleStart = 0;
    mem.stillCount = 0;
    mem.holdI = 0;
    mem.drillStarted = false;
    mem.lastDrilling = 0;

    mem.motorI = [0, 0];
    mem.lastTargets = [0, 0];
    mem.stallN = [0, 0];
    mem.deadBoost = [0, 0];

    mem.navKey = "";
    mem.navBestDist = 1e9;
    mem.navProgressT = now;
    mem.lastSteer = 0;
    mem.recoverUntil = 0;
    mem.recoverSign = 1;
    mem.lastBumped = false;
    mem.bumpCount = 0;

    mem.slipTicks = 0;
    mem.sandUntil = 0;

    mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayDisabled = [false, false, false, false, false, false, false, false, false];
    mem.rayTravel = 0;
    mem.maxRayTravel = 0;

    mem.chargeWaitKey = "";
    mem.chargeWaitStart = now;
    mem.chargeWaitBattery = battery;
    mem._init = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.grid)) mem.grid = [];
  if (!mem.gridVisited) mem.gridVisited = {};
  if (!Array.isArray(mem.motorI)) mem.motorI = [0, 0];
  if (!Array.isArray(mem.lastTargets)) mem.lastTargets = [0, 0];
  if (!Array.isArray(mem.stallN)) mem.stallN = [0, 0];
  if (!Array.isArray(mem.deadBoost)) mem.deadBoost = [0, 0];
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  if (!Array.isArray(mem.rayDisabled)) mem.rayDisabled = [false, false, false, false, false, false, false, false, false];

  let dt = 0.1;
  if (mem._lastT !== undefined) {
    const td = now - num(mem._lastT, now);
    if (td > 0.015 && td < 0.7) dt = td;
  }
  mem._lastT = now;
  mem.clock = now;

  const headingDelta = mem.lastHeadRaw === undefined
    ? 0
    : wrap(headingRaw - num(mem.lastHeadRaw, headingRaw));
  if (mem.lastHeadRaw !== undefined) {
    const expectedDelta = (wr - wl) / 0.6 * dt / RAD;
    const mismatch = wrap(headingDelta - expectedDelta);
    if (Math.abs(mismatch) > 48 &&
        Math.abs(expectedDelta) < 28 &&
        Math.abs(headingDelta) > 30) {
      mem.headingOffset = wrap(
        num(mem.headingOffset, 0) + clamp(mismatch, -120, 120)
      );
    }
  }
  mem.lastHeadRaw = headingRaw;
  let headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  const oldPX = num(mem.posX, rawX);
  const oldPY = num(mem.posY, rawY);
  const rawStep = dist(rawX, rawY, num(mem.rawPrevX, rawX), num(mem.rawPrevY, rawY));

  if (mem.gpsFrozen) {
    if (rawStep > 0.75) {
      mem.gpsFrozen = false;
      mem.gpsFreezeCount = 0;
      mem.freezeAccX = 0;
      mem.freezeAccY = 0;
      mem.posX = rawX;
      mem.posY = rawY;
    } else if (wheelAbs > 0.10 && !docked) {
      const dx = wheelAvg * Math.cos(headingTrue * RAD) * dt;
      const dy = wheelAvg * Math.sin(headingTrue * RAD) * dt;
      mem.posX += dx;
      mem.posY += dy;
    }
  } else if (rawStep < 0.02 && wheelAbs > 0.32 && !docked && !bumped) {
    mem.gpsFreezeCount = (mem.gpsFreezeCount || 0) + 1;
    const dx = wheelAvg * Math.cos(headingTrue * RAD) * dt;
    const dy = wheelAvg * Math.sin(headingTrue * RAD) * dt;
    mem.freezeAccX = num(mem.freezeAccX, 0) + dx;
    mem.freezeAccY = num(mem.freezeAccY, 0) + dy;
    if (mem.gpsFreezeCount >= 9) {
      mem.gpsFrozen = true;
      mem.posX = rawX + mem.freezeAccX;
      mem.posY = rawY + mem.freezeAccY;
    } else {
      mem.posX = 0.55 * oldPX + 0.45 * rawX;
      mem.posY = 0.55 * oldPY + 0.45 * rawY;
    }
  } else {
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;
    if (rawStep > 8 && !docked) {
      mem.posX = oldPX;
      mem.posY = oldPY;
    } else {
      const alpha = wheelAbs > 0.2 ? 0.52 : 0.20;
      mem.posX = oldPX + alpha * (rawX - oldPX);
      mem.posY = oldPY + alpha * (rawY - oldPY);
    }
  }
  mem.rawPrevX = rawX;
  mem.rawPrevY = rawY;

  let px = num(mem.posX, rawX);
  let py = num(mem.posY, rawY);
  let stepDist = dist(oldPX, oldPY, px, py);

  const calDX = rawX - num(mem.calPrevX, rawX);
  const calDY = rawY - num(mem.calPrevY, rawY);
  if (!docked && !mem.gpsFrozen && wheelAvg > 0.42 &&
      Math.abs(wr - wl) < 0.19 && rawStep < 1.2) {
    mem.calDX = num(mem.calDX, 0) + calDX;
    mem.calDY = num(mem.calDY, 0) + calDY;
    mem.calSin = num(mem.calSin, 0) + Math.sin(headingRaw * RAD);
    mem.calCos = num(mem.calCos, 0) + Math.cos(headingRaw * RAD);
    mem.calN = (mem.calN || 0) + 1;

    if (Math.hypot(mem.calDX, mem.calDY) > 3.5 &&
        Math.hypot(mem.calDX, mem.calDY) > 2.5 &&
        mem.calN > 8) {
      const track = Math.atan2(mem.calDY, mem.calDX) / RAD;
      const avgRaw = Math.atan2(mem.calSin, mem.calCos) / RAD;
      const measuredOffset = wrap(avgRaw - track);
      const err = wrap(measuredOffset - num(mem.headingOffset, 0));
      if (Math.abs(err) < 60) {
        mem.headingOffset = wrap(
          num(mem.headingOffset, 0) + clamp(err * 0.16, -9, 9)
        );
      }
      mem.calDX = 0;
      mem.calDY = 0;
      mem.calSin = 0;
      mem.calCos = 0;
      mem.calN = 0;
    }
  } else {
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;
  }
  mem.calPrevX = rawX;
  mem.calPrevY = rawY;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  const timeLeft = Math.max(0, num(obs.timeLeft, mem.totalSeconds - now));
  const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const hasRays = !!(obs.rays && typeof obs.rays.length === "number");
  const rays = [];
  let allMax = hasRays;
  for (let i = 0; i < 9; i++) {
    const r = clamp(num(hasRays ? obs.rays[i] : 15, 15), 0, 15);
    rays.push(r);
    if (r < 14.7) allMax = false;

    if (Math.abs(r - num(mem.rayLast[i], 15)) < 0.025) {
      mem.rayStale[i] = (mem.rayStale[i] || 0) + 1;
    } else {
      mem.rayStale[i] = 0;
      if (mem.rayDisabled[i] && Math.abs(r - num(mem.rayLast[i], r)) > 0.5) {
        mem.rayDisabled[i] = false;
      }
    }
    mem.rayLast[i] = r;
  }

  mem.rayTravel = num(mem.rayTravel, 0) + stepDist;
  if (mem.rayTravel > 10) {
    for (let i = 0; i < 9; i++) {
      if (mem.rayStale[i] > 150 && rays[i] < 14.7) {
        mem.rayDisabled[i] = true;
      }
    }
    mem.rayTravel = 0;
  }
  let disabledCount = 0;
  for (let i = 0; i < 9; i++) {
    if (mem.rayDisabled[i]) disabledCount++;
  }
  if (allMax && wheelAbs > 0.15) {
    mem.maxRayTravel = num(mem.maxRayTravel, 0) + stepDist;
  } else {
    mem.maxRayTravel = 0;
  }
  const raysBlind = !hasRays || disabledCount >= 5 || mem.maxRayTravel > 40;

  const groundSpeed = stepDist / Math.max(0.04, dt);
  if (wheelAbs > 0.85 && Math.abs(wheelAvg) > 0.35 &&
      groundSpeed < 0.27 && !bumped && !docked) {
    mem.slipTicks = (mem.slipTicks || 0) + 1;
    if (mem.slipTicks > 16) mem.sandUntil = now + 12;
  } else {
    mem.slipTicks = Math.max(0, (mem.slipTicks || 0) - 1);
  }

  const oldBattery = num(mem.prevBattery, battery);
  const db = oldBattery - battery;
  if (!docked && wheelAbs > 0.12 &&
      Math.abs(db) < 0.08 && stepDist > 0.01) {
    mem.energyBucket = num(mem.energyBucket, 0) +
      Math.max(0, db + Math.max(0, solar) * dt * 0.035);
    mem.distanceBucket = num(mem.distanceBucket, 0) + stepDist;
    if (mem.distanceBucket >= 10) {
      const measured = mem.energyBucket / Math.max(1, mem.distanceBucket);
      if (measured > 0.00004 && measured < 0.02) {
        const oldBurn = num(mem.burn, 0.0009);
        const alpha = measured > oldBurn ? 0.24 : 0.10;
        mem.burn = clamp(oldBurn + alpha * (measured - oldBurn),
                         0.00025, 0.012);
      }
      mem.energyBucket = 0;
      mem.distanceBucket = 0;
    }
  }
  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);

  if (bumped && !mem.lastBumped) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.3, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    mem.recoverSign = rightDanger > leftDanger ? 1 : -1;
    mem.recoverUntil = now + 1.0;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
  }
  mem.lastBumped = bumped;

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const justSampled = carried > oldCarried + 0.01 ||
                      carriedValue > oldCarriedValue + 0.01;
  const justDelivered = delivered > oldDelivered + 0.01 ||
                        (docked && carried < oldCarried - 0.01);

  if (justSampled) {
    const sx = Number.isFinite(Number(mem.sampleSiteX))
      ? Number(mem.sampleSiteX)
      : num(mem.sampleX, px);
    const sy = Number.isFinite(Number(mem.sampleSiteY))
      ? Number(mem.sampleSiteY)
      : num(mem.sampleY, py);

    mem.lastSampleSiteX = sx;
    mem.lastSampleSiteY = sy;

    if (mem.task) {
      if (mem.task.type === "hint" &&
          mem.task.index >= 0 && mem.task.index < mem.hints.length) {
        mem.hints[mem.task.index].status = 1;
      } else if (mem.task.type === "grid") {
        mem.gridVisited[mem.task.key] = true;
      }
    }

    let nearestHint = -1;
    let nearestD = 24;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status !== 0) continue;
      const d = dist(sx, sy, mem.hints[i].x, mem.hints[i].y);
      if (d < nearestD) {
        nearestD = d;
        nearestHint = i;
      }
    }
    if (nearestHint >= 0) mem.hints[nearestHint].status = 1;

    mem.task = null;
    mem.search = null;
    mem.sampling = false;
    mem.stillCount = 0;
    mem.holdI = 0;
    mem.drillStarted = false;
  }

  if (justDelivered) {
    mem.returning = false;
    mem.sampling = false;
    mem.stillCount = 0;
    mem.holdI = 0;
    mem.drillStarted = false;
  }

  mem.prevCarried = carried;
  mem.prevCarriedValue = carriedValue;
  mem.prevDelivered = delivered;

  let siteVisible = false;
  let siteDistance = 99;
  let siteBearing = 0;
  let siteGX = NaN;
  let siteGY = NaN;
  const siteObs = obs.site;
  if (siteObs && Number.isFinite(Number(siteObs.distance))) {
    siteDistance = clamp(num(siteObs.distance, 99), 0, 12);
    siteBearing = wrap(num(siteObs.bearing, 0));
    const a = (headingTrue + siteBearing) * RAD;
    siteGX = px + siteDistance * Math.cos(a);
    siteGY = py + siteDistance * Math.sin(a);

    let suppress = false;
    if (justSampled &&
        Number.isFinite(Number(mem.lastSampleSiteX)) &&
        Number.isFinite(Number(mem.lastSampleSiteY)) &&
        dist(siteGX, siteGY, Number(mem.lastSampleSiteX),
             Number(mem.lastSampleSiteY)) < 2.4) {
      suppress = true;
    }
    if (!suppress) siteVisible = true;
  }

  const beacon = obs.beacon;
  const beaconDistance =
    beacon && Number.isFinite(Number(beacon.distance)) &&
    Number(beacon.distance) <= 21
      ? Math.max(0, num(beacon.distance, 0))
      : null;
  const gpsBaseDistance = dist(px, py, mem.baseX, mem.baseY);
  const baseDistance = docked
    ? 0
    : (beaconDistance !== null ? beaconDistance : gpsBaseDistance);

  function returnEnergy(d, n) {
    const count = Math.max(0, n);
    return Math.max(0, d) * num(mem.burn, 0.0009) *
      (1 + 0.22 * count) * 2.15 +
      0.065 + 0.018 * count;
  }

  function returnTime(d) {
    if (d <= 2.6) return 0;
    return (d - 2.4) / 0.86 + 15;
  }

  function motorCommand(i, target, actual, bias) {
    target = clamp(target, -2.4, 2.4);
    let integ = num(mem.motorI[i], 0);
    const lastTarget = num(mem.lastTargets[i], 0);

    if (target * lastTarget < -0.06) integ = 0;
    if (Math.abs(target) < 0.055 && Math.abs(lastTarget) > 0.16) {
      integ = 0;
    }
    if (Math.abs(lastTarget) < 0.055 && Math.abs(target) > 0.14) {
      integ *= 0.25;
    }

    const holdBias = clamp(num(bias, 0), -0.30, 0.30);
    let raw;
    if (Math.abs(target) < 0.055) {
      const error = -actual;
      integ = clamp(integ + 0.26 * error * dt, -0.30, 0.30);
      raw = 0.58 * error + integ + holdBias;
    } else {
      const error = target - actual;
      raw = target / 2.9 + 0.38 * error + integ + holdBias;
      const proposed = clamp(integ + 0.31 * error * dt, -0.42, 0.42);
      if (Math.abs(raw) < 0.96 || error * raw < 0) integ = proposed;
      raw = target / 2.9 + 0.38 * error + integ + holdBias;

      if (Math.abs(target) > 0.22 && Math.abs(actual) < 0.07) {
        mem.stallN[i] = (mem.stallN[i] || 0) + 1;
        if (mem.stallN[i] > 5) {
          mem.deadBoost[i] = clamp(
            num(mem.deadBoost[i], 0) + 0.012, 0, 0.12
          );
        }
      } else {
        mem.stallN[i] = Math.max(0, (mem.stallN[i] || 0) - 1);
        if (Math.abs(actual) > 0.15) {
          mem.deadBoost[i] = Math.max(
            0, num(mem.deadBoost[i], 0) - 0.001
          );
        }
      }

      const minimum = 0.14 + num(mem.deadBoost[i], 0);
      if (Math.abs(target) > 0.18 &&
          Math.abs(actual) < 0.12 &&
          Math.abs(raw) < minimum) {
        raw = Math.sign(target) * minimum;
      }
    }

    mem.motorI[i] = clamp(integ, -0.42, 0.42);
    mem.lastTargets[i] = target;
    return clamp(raw, -1, 1);
  }

  function drive(v, omega, holdBias) {
    let leftTarget = v - omega * 0.30;
    let rightTarget = v + omega * 0.30;
    const maxWheel = Math.max(Math.abs(leftTarget), Math.abs(rightTarget));
    if (maxWheel > 2.4) {
      const scale = 2.4 / maxWheel;
      leftTarget *= scale;
      rightTarget *= scale;
    }
    return {
      left: motorCommand(0, leftTarget, wl, holdBias),
      right: motorCommand(1, rightTarget, wr, holdBias),
      drill: false
    };
  }

  function stopOutput() {
    return drive(0, 0, 0);
  }

  function dangerTurn(goalErr) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.3, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.02) {
      return Math.sign(goalErr || 1);
    }
    return rightDanger > leftDanger ? 1 : -1;
  }

  function navigation(goalErr, goalDist, mode, key) {
    goalErr = wrap(goalErr);
    goalDist = Math.max(0, num(goalDist, 0));

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    } else if (goalDist < num(mem.navBestDist, 1e9) - 0.40) {
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    }

    if (now - num(mem.navProgressT, now) > 22 &&
        now >= num(mem.recoverUntil, 0)) {
      mem.recoverSign = dangerTurn(goalErr);
      mem.recoverUntil = now + 0.95;
      mem.navProgressT = now;
      mem.navBestDist = goalDist;
    }

    if (now < num(mem.recoverUntil, 0)) {
      const sign = num(mem.recoverSign, 1) || 1;
      return drive(-0.35, sign * 0.95, 0);
    }

    if (Math.abs(goalErr) > 112) {
      return drive(0, (Math.sign(goalErr) || 1) * 1.25, 0);
    }

    const options = [
      -90, -75, -60, -45, -30, -15, 0,
      15, 30, 45, 60, 75, 90,
      clamp(goalErr, -100, 100)
    ];
    let bestAngle = clamp(goalErr, -90, 90);
    let bestCost = 1e30;
    const look = 7;

    for (let c = 0; c < options.length; c++) {
      const a = options[c];
      const ar = a * RAD;
      const ca = Math.cos(ar);
      const sa = Math.sin(ar);
      let cost = Math.pow(wrap(a - goalErr) / 34, 2) +
        0.001 * Math.abs(wrap(a - num(mem.lastSteer, 0)));

      for (let i = 0; i < 9; i++) {
        if (mem.rayDisabled[i]) continue;
        const r0 = rays[i];
        if (!(r0 > 0.05) || r0 >= 14.75) continue;

        const r = Math.max(0.15, r0 - 0.35);
        const rr = rayAngles[i] * RAD;
        const ox = r * Math.cos(rr);
        const oy = r * Math.sin(rr);
        const along = ox * ca + oy * sa;
        if (along < -0.35 || along > look + 0.5) continue;

        const lateral = Math.abs(-ox * sa + oy * ca);
        if (lateral < 1.85) {
          const penetration = 1.85 - lateral;
          cost += penetration * penetration *
            (1.0 + 4.0 / (Math.max(0, along) + 0.55));
        } else if (lateral < 3.0) {
          cost += 0.08 * Math.pow(3.0 - lateral, 2);
        }
      }

      const globalAngle = (headingTrue + a) * RAD;
      const nx = px + 7 * Math.cos(globalAngle);
      const ny = py + 7 * Math.sin(globalAngle);
      if (nx < 3) cost += 2.8 * Math.pow(3 - nx, 2);
      if (ny < 3) cost += 2.8 * Math.pow(3 - ny, 2);
      if (nx > mem.mapW - 3) cost += 2.8 * Math.pow(nx - (mem.mapW - 3), 2);
      if (ny > mem.mapH - 3) cost += 2.8 * Math.pow(ny - (mem.mapH - 3), 2);

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
      }
    }
    mem.lastSteer = bestAngle;

    let cruise = mode === "return" ? 1.55 :
                 mode === "site" ? 1.15 : 1.45;
    if (raysBlind) cruise = Math.min(cruise, 1.02);
    if (disabledCount >= 5) cruise = Math.min(cruise, 0.78);
    if (mem.bumpCount >= 5) cruise = Math.min(cruise, 1.15);
    if (now < num(mem.sandUntil, 0)) cruise = Math.min(cruise, 0.82);

    let speed = cruise;
    if (Math.abs(bestAngle) > 50) {
      speed *= clamp(1 - (Math.abs(bestAngle) - 50) / 75, 0.18, 1);
    }
    if (Math.abs(goalErr) > 100) speed = 0;

    if (mode === "site") {
      if (goalDist < 8) {
        speed = Math.min(speed, clamp(0.55 * (goalDist - 0.68), 0, 1.0));
      }
      if (goalDist <= 0.9) speed = 0;
    } else if (mode === "return") {
      if (goalDist < 12) {
        speed = Math.min(speed, 0.25 + 0.18 * goalDist);
      }
      if (goalDist <= 2.55) speed = 0;
    } else {
      if (goalDist < 10) {
        speed = Math.min(
          speed,
          Math.sqrt(Math.max(0, goalDist - 2.1) * 0.62)
        );
      }
      if (goalDist <= 2.25) speed = 0;
    }

    let pathRange = 1e9;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      if (rays[i] >= 14.75) continue;
      if (Math.abs(wrap(rayAngles[i] - bestAngle)) <= 30) {
        pathRange = Math.min(pathRange, rays[i]);
      }
    }
    if (pathRange < 1.8) speed = Math.min(speed, 0.20);
    else if (pathRange < 2.8) speed = Math.min(speed, 0.36);
    else if (pathRange < 4.0) speed = Math.min(speed, 0.58);
    else if (pathRange < 5.3) speed = Math.min(speed, 0.82);

    const travelAngle = (headingTrue + bestAngle) * RAD;
    const dx = Math.cos(travelAngle);
    const dy = Math.sin(travelAngle);
    if ((px < 5 && dx < 0) || (py < 5 && dy < 0) ||
        (px > mem.mapW - 5 && dx > 0) ||
        (py > mem.mapH - 5 && dy > 0)) {
      speed = Math.min(speed, 0.40);
    } else if ((px < 9 && dx < 0) || (py < 9 && dy < 0) ||
               (px > mem.mapW - 9 && dx > 0) ||
               (py > mem.mapH - 9 && dy > 0)) {
      speed = Math.min(speed, 0.72);
    }

    const omega = clamp(2.0 * bestAngle * RAD, -1.6, 1.6);
    return drive(speed, omega, 0);
  }

  function goHome() {
    if (docked) return stopOutput();
    if (baseDistance <= 2.55) return stopOutput();

    let err;
    if (beaconDistance !== null &&
        beacon &&
        Number.isFinite(Number(beacon.bearing))) {
      err = num(beacon.bearing, 0);
    } else {
      const bearing = Math.atan2(mem.baseY - py, mem.baseX - px) / RAD;
      err = wrap(bearing - headingTrue);
    }
    return navigation(err, baseDistance, "return", "home");
  }

  function canBeginSample() {
    if (carried >= mem.capacity) return false;
    const required = returnEnergy(baseDistance, carried + 1) + 0.055;
    if (battery < required) return false;
    const neededTime = docked ? 7 : returnTime(baseDistance) + 9;
    return timeLeft > neededTime;
  }

  function beginSampling() {
    mem.sampling = true;
    mem.sampleX = px;
    mem.sampleY = py;
    mem.sampleSiteX = Number.isFinite(siteGX) ? siteGX : null;
    mem.sampleSiteY = Number.isFinite(siteGY) ? siteGY : null;
    mem.sampleStart = now;
    mem.stillCount = 0;
    mem.holdI = 0;
    mem.drillStarted = false;
    mem.lastDrilling = 0;
  }

  function sampleOutput() {
    if (!mem.sampling) return null;

    const progress = Math.max(0, num(obs.drilling, 0));
    if (progress > 0.03) mem.drillStarted = true;

    let range = 99;
    let matchingSite = false;
    if (siteVisible &&
        Number.isFinite(Number(mem.sampleSiteX)) &&
        Number.isFinite(Number(mem.sampleSiteY))) {
      const siteSeparation = dist(
        siteGX, siteGY,
        Number(mem.sampleSiteX), Number(mem.sampleSiteY)
      );
      matchingSite = siteSeparation < 5.0 || siteDistance < 2.0;
    }

    if (siteVisible && matchingSite) {
      range = siteDistance;
    } else if (Number.isFinite(Number(mem.sampleSiteX)) &&
               Number.isFinite(Number(mem.sampleSiteY))) {
      range = dist(px, py, Number(mem.sampleSiteX), Number(mem.sampleSiteY));
    } else {
      range = dist(px, py, num(mem.sampleX, px), num(mem.sampleY, py)) + 0.8;
    }

    const farLimit = siteVisible && matchingSite ? 1.82 : 2.25;
    if (range > farLimit) {
      mem.sampling = false;
      mem.stillCount = 0;
      mem.holdI = 0;
      mem.drillStarted = false;
      return null;
    }

    if (!docked && progress < 5.6 &&
        battery < returnEnergy(baseDistance, carried + 1) + 0.012) {
      mem.sampling = false;
      mem.stillCount = 0;
      mem.holdI = 0;
      mem.returning = true;
      return null;
    }
    if (!docked && progress < 5.6 &&
        timeLeft < returnTime(baseDistance) + 7) {
      mem.sampling = false;
      mem.stillCount = 0;
      mem.holdI = 0;
      mem.returning = true;
      return null;
    }

    const slow = Math.abs(wl) < 0.148 && Math.abs(wr) < 0.148;
    if (slow) mem.stillCount = (mem.stillCount || 0) + 1;
    else mem.stillCount = 0;

    const errX = num(mem.sampleX, px) - px;
    const errY = num(mem.sampleY, py) - py;
    const along = errX * Math.cos(headingTrue * RAD) +
                  errY * Math.sin(headingTrue * RAD);
    if (Math.abs(along) > 0.03) {
      mem.holdI = clamp(
        num(mem.holdI, 0) + 0.004 * along * dt,
        -0.10,
        0.10
      );
    }
    const holdBias = clamp(
      0.012 * clamp(pitch, -20, 20) +
      0.045 * along -
      0.12 * wheelAvg +
      num(mem.holdI, 0),
      -0.25,
      0.25
    );

    const inRange = range <= 1.50;
    if (!mem.drillStarted && inRange && slow && mem.stillCount >= 3) {
      mem.drillStarted = true;
    }
    const drill = inRange && mem.drillStarted;

    const left = motorCommand(0, 0, wl, holdBias);
    const right = motorCommand(1, 0, wr, holdBias);
    mem.lastDrilling = progress;
    return { left: left, right: right, drill: !!drill };
  }

  function finishTask(sampled) {
    const task = mem.task;
    if (!task) {
      mem.search = null;
      return;
    }
    if (task.type === "hint" &&
        task.index >= 0 && task.index < mem.hints.length) {
      mem.hints[task.index].status = sampled ? 1 : 2;
    } else if (task.type === "grid") {
      mem.gridVisited[task.key] = true;
    }
    mem.task = null;
    mem.search = null;
    mem.navKey = "";
  }

  function makeRing(cx, cy, radius, count) {
    const points = [];
    for (let i = 0; i < count; i++) {
      const a = 2 * PI * i / count;
      const x = clamp(cx + radius * Math.cos(a), 3, mem.mapW - 3);
      const y = clamp(cy + radius * Math.sin(a), 3, mem.mapH - 3);
      let duplicate = false;
      for (let j = 0; j < points.length; j++) {
        if (dist(x, y, points[j].x, points[j].y) < 2.0) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) points.push({ x: x, y: y });
    }

    if (points.length > 1) {
      let nearest = 0;
      let nearestD = 1e30;
      for (let i = 0; i < points.length; i++) {
        const d = dist(px, py, points[i].x, points[i].y);
        if (d < nearestD) {
          nearestD = d;
          nearest = i;
        }
      }
      return points.slice(nearest).concat(points.slice(0, nearest));
    }
    return points;
  }

  function startSearch(task) {
    if (!task) return;
    const radius = task.type === "hint" ? 14 : 12;
    const count = task.type === "hint" ? 16 : 12;
    const points = makeRing(task.x, task.y, radius, count);
    if (points.length === 0) {
      finishTask(false);
      return;
    }

    task.phase = "search";
    mem.search = {
      key: task.key,
      cx: task.x,
      cy: task.y,
      points: points,
      idx: 0,
      level: 0,
      centerScience: science,
      bestScience: science,
      bestX: px,
      bestY: py,
      pointStart: now,
      maxUntil: now + 220
    };
    mem.navKey = "";
  }

  function updateSearch() {
    const s = mem.search;
    if (!s) return;

    if (now > num(s.maxUntil, now + 1)) {
      finishTask(false);
      return;
    }

    if (science > num(s.bestScience, 0)) {
      s.bestScience = science;
      s.bestX = px;
      s.bestY = py;
    }

    if (!s.points || s.points.length === 0) {
      finishTask(false);
      return;
    }

    if (s.idx < s.points.length) {
      const target = s.points[s.idx];
      const d = dist(px, py, target.x, target.y);
      if (d < 3.2) {
        s.idx++;
        s.pointStart = now;
      } else if (now - num(s.pointStart, now) > 24) {
        s.idx++;
        s.pointStart = now;
      }
    }

    if (s.idx < s.points.length) return;

    if (s.level === 0 &&
        s.bestScience > Math.max(0.18, s.centerScience * 1.20)) {
      s.level = 1;
      s.cx = s.bestX;
      s.cy = s.bestY;
      s.points = makeRing(s.cx, s.cy, 7, 8);
      s.idx = 0;
      s.centerScience = s.bestScience;
      s.pointStart = now;
      s.maxUntil = now + 130;
      if (s.points.length > 0) {
        mem.navKey = "";
        return;
      }
    }

    finishTask(false);
  }

  function planFor(task) {
    const d1 = dist(px, py, task.x, task.y);
    const d2 = dist(task.x, task.y, mem.baseX, mem.baseY);
    let extra = task.type === "hint" ? 72 : 52;

    if (mem.search && mem.search.key === task.key) {
      const remaining = Math.max(
        0,
        mem.search.points.length - mem.search.idx
      );
      extra = clamp(remaining * 5.0 + 12, 18, 105);
    }

    const routeMeters = (d1 + d2 + extra) * 1.18;
    const load = 1 + 0.20 * (carried + 0.5);
    const need = routeMeters * num(mem.burn, 0.0009) * load * 1.82 +
      0.085 + 0.022 * carried;
    const time = (d1 + d2 + extra) / 0.82 + 40;
    return { d1: d1, d2: d2, extra: extra, need: need, time: time };
  }

  function chooseTask() {
    let bestHint = null;
    let bestHintScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0 ||
          num(h.blockedUntil, 0) > now ||
          carried >= mem.capacity) continue;

      const task = {
        type: "hint",
        index: i,
        x: h.x,
        y: h.y,
        key: "h:" + i,
        phase: "travel",
        value: h.value
      };
      const p = planFor(task);
      if (p.need > num(mem.maxBattery, battery) - 0.025) continue;
      if (p.time > timeLeft - 8) continue;

      let cost;
      if (carried > 0) {
        cost = 30 + p.d1 +
          1.35 * Math.max(0, p.d2 - baseDistance) +
          0.22 * baseDistance + 0.24 * p.extra;
      } else {
        cost = 32 + p.d1 + 0.72 * p.d2 + 0.24 * p.extra;
      }
      const score = Math.max(0.05, h.value) /
        Math.pow(Math.max(1, cost), 0.84);
      if (score > bestHintScore) {
        bestHintScore = score;
        bestHint = task;
      }
    }

    if (bestHint) return bestHint;

    let bestGrid = null;
    let bestGridScore = -1;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (!g || mem.gridVisited[g.key] || carried >= mem.capacity) continue;

      const task = {
        type: "grid",
        index: i,
        x: g.x,
        y: g.y,
        key: g.key,
        phase: "travel",
        value: 0.35
      };
      const p = planFor(task);
      if (p.need > num(mem.maxBattery, battery) - 0.025) continue;
      if (p.time > timeLeft - 8) continue;

      const cost = 38 + p.d1 + 0.58 * p.d2 + 0.20 * p.extra;
      const score = 0.35 / Math.pow(Math.max(1, cost), 0.82);
      if (score > bestGridScore) {
        bestGridScore = score;
        bestGrid = task;
      }
    }
    return bestGrid;
  }

  function ensureTask() {
    if (mem.task && mem.task.type === "hint") {
      const i = mem.task.index;
      if (i < 0 || i >= mem.hints.length ||
          mem.hints[i].status !== 0) {
        mem.task = null;
        mem.search = null;
      }
    }
    if (mem.task && mem.task.type === "grid" &&
        mem.gridVisited[mem.task.key]) {
      mem.task = null;
      mem.search = null;
    }
    if (!mem.task) mem.task = chooseTask();
  }

  function mustReturn() {
    if (carried >= mem.capacity) return true;
    if (battery < returnEnergy(baseDistance, carried) + 0.025) return true;
    if (timeLeft < returnTime(baseDistance) + (carried > 0 ? 12 : 8)) {
      return true;
    }
    return false;
  }

  if (docked) {
    if (carried > 0) {
      mem.returning = true;
    } else {
      mem.returning = false;
    }
  }

  if (mem.sampling) {
    const out = sampleOutput();
    if (out) return out;
    if (mem.returning && !docked) return goHome();
  }

  if (!docked && !mem.returning && mustReturn()) {
    mem.returning = true;
  }
  if (mem.returning && !docked) return goHome();

  if (siteVisible) {
    if (mem.search) {
      mem.search.pointStart = now;
      mem.search.maxUntil = Math.max(
        num(mem.search.maxUntil, now),
        now + 220
      );
    }

    if (carried >= mem.capacity) {
      if (!docked) {
        mem.returning = true;
        return goHome();
      }
      return stopOutput();
    }

    if (!canBeginSample()) {
      if (docked) return stopOutput();
      mem.returning = true;
      return goHome();
    }

    if (!mem.sampling &&
        (siteDistance <= 1.25 ||
         (siteDistance <= 1.50 && wheelAbs < 0.11))) {
      beginSampling();
    }

    if (mem.sampling) {
      const out = sampleOutput();
      if (out) return out;
      if (mem.returning && !docked) return goHome();
    }

    return navigation(siteBearing, siteDistance, "site", "site");
  }

  if (docked && carried > 0) return stopOutput();

  ensureTask();

  if (docked && mem.task) {
    const p = planFor(mem.task);
    if (p.time > timeLeft - 5) {
      finishTask(false);
      ensureTask();
    }

    if (mem.task) {
      const q = planFor(mem.task);
      if (battery < q.need + 0.025) {
        if (mem.chargeWaitKey !== mem.task.key) {
          mem.chargeWaitKey = mem.task.key;
          mem.chargeWaitStart = now;
          mem.chargeWaitBattery = battery;
        } else if (battery > num(mem.chargeWaitBattery, battery) + 0.008) {
          mem.chargeWaitBattery = battery;
          mem.chargeWaitStart = now;
        }

        if (now - num(mem.chargeWaitStart, now) > 180 &&
            battery < q.need + 0.015) {
          finishTask(false);
          ensureTask();
        } else {
          return stopOutput();
        }
      } else {
        mem.chargeWaitKey = "";
      }
    }
  }

  for (let guard = 0; guard < 5; guard++) {
    ensureTask();

    if (!mem.task) {
      if (docked) return stopOutput();
      mem.returning = true;
      return goHome();
    }

    const task = mem.task;

    if (task.phase === "search") {
      if (!mem.search) {
        startSearch(task);
        if (!mem.search) continue;
      }
      updateSearch();
      if (!mem.search) continue;

      const s = mem.search;
      const q = s.points[s.idx];
      if (!q) {
        finishTask(false);
        continue;
      }
      const d = dist(px, py, q.x, q.y);
      const bearing = Math.atan2(q.y - py, q.x - px) / RAD;
      const key = "search:" + s.key + ":" + s.level + ":" + s.idx;
      return navigation(wrap(bearing - headingTrue), d, "waypoint", key);
    }

    const d = dist(px, py, task.x, task.y);
    if (d < 4.2) {
      if (task.type === "grid" && science < 0.14) {
        finishTask(false);
        continue;
      }
      startSearch(task);
      if (mem.search) continue;
      continue;
    }

    if (docked) {
      const p = planFor(task);
      if (battery < p.need + 0.025) return stopOutput();
      if (p.time > timeLeft - 5) {
        finishTask(false);
        continue;
      }
    } else if (carried > 0) {
      const p = planFor(task);
      if (battery < p.need + 0.035) {
        mem.returning = true;
        return goHome();
      }
    }

    const bearing = Math.atan2(task.y - py, task.x - px) / RAD;
    return navigation(
      wrap(bearing - headingTrue),
      d,
      "waypoint",
      "task:" + task.key
    );
  }

  if (docked) return stopOutput();
  mem.returning = true;
  return goHome();
}

function act(obs, mem) {
  obs = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const PI = Math.PI;
  const RAD = PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const now = num(obs.t, num(mem.clock, 0));
  const rawX = num(obs.x, 200);
  const rawY = num(obs.y, 200);
  const headingRaw = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const wheelAvg = (wl + wr) * 0.5;
  const wheelAbs = (Math.abs(wl) + Math.abs(wr)) * 0.5;
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const battery = Math.max(0, num(obs.battery, 0));
  const solar = Math.max(0, num(obs.solar, 0));
  const carried = Math.max(0, num(obs.carried, 0));
  const carriedValue = Math.max(0, num(obs.carriedValue, 0));
  const delivered = Math.max(0, num(obs.delivered, 0));
  const science = Math.max(0, num(obs.science, 0));
  const pitch = num(obs.pitch, 0);

  if (!mem._v4) {
    const mission = obs.mission || {};
    let mapW = 400;
    let mapH = 400;
    const size = mission.size;
    if (typeof size === "number") {
      mapW = size;
      mapH = size;
    } else if (Array.isArray(size)) {
      mapW = num(size[0], 400);
      mapH = num(size[1], mapW);
    } else if (size && typeof size === "object") {
      mapW = num(size.width, num(size.x, 400));
      mapH = num(size.height, num(size.y, mapW));
    } else {
      mapW = num(mission.width, 400);
      mapH = num(mission.height, 400);
    }
    mapW = Math.max(20, mapW);
    mapH = Math.max(20, mapH);

    const base = mission.base || {};
    mem.mapW = mapW;
    mem.mapH = mapH;
    mem.baseX = num(base.x, mapW * 0.5);
    mem.baseY = num(base.y, mapH * 0.5);
    mem.capacity = Math.max(1, num(mission.capacity, 5));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));

    mem.hints = [];
    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const x = num(h.x, NaN);
      const y = num(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      let value = num(h.estimate, num(h.value, 1));
      if (!(value > 0)) value = 0.15;
      mem.hints.push({
        x: clamp(x, 3, mapW - 3),
        y: clamp(y, 3, mapH - 3),
        value: value,
        status: 0
      });
    }

    mem.grid = [];
    let gx = 0;
    for (let x = 30; x <= mapW - 20; x += 55, gx++) {
      let gy = 0;
      for (let y = 30; y <= mapH - 20; y += 55, gy++) {
        mem.grid.push({
          x: clamp(x, 4, mapW - 4),
          y: clamp(y, 4, mapH - 4),
          key: "g:" + gx + ":" + gy
        });
      }
    }

    mem.gridVisited = {};
    mem.task = null;
    mem.search = null;
    mem.resumeTask = null;
    mem.nextTaskId = 1;
    mem.returning = false;
    mem.lastSignalSearch = -10000;

    mem.clock = now;
    mem._lastT = now;
    mem.headingOffset = 0;
    mem.lastHeadRaw = headingRaw;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.rawPrevX = rawX;
    mem.rawPrevY = rawY;
    mem.gpsFrozen = false;
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;

    mem.calPrevX = rawX;
    mem.calPrevY = rawY;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;

    mem.prevBattery = battery;
    mem.burn = 0.00065;
    mem.energyBucket = 0;
    mem.distanceBucket = 0;
    mem.vEst = 0.52;

    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;

    mem.sampling = false;
    mem.sampleX = rawX;
    mem.sampleY = rawY;
    mem.sampleSiteX = null;
    mem.sampleSiteY = null;
    mem.sampleStart = 0;
    mem.sampleStartDistance = 0;
    mem.stillTicks = 0;
    mem.holdI = 0;
    mem.lastSampleSiteX = null;
    mem.lastSampleSiteY = null;
    mem.suppressSiteUntil = -1;

    mem.motorI = [0, 0];
    mem.motorGain = [3, 3];
    mem.lastTargets = [0, 0];
    mem.prevTargets = [0, 0];
    mem.prevCmd = [0, 0];
    mem.stallTicks = [0, 0];
    mem.deadKick = [0, 0];

    mem.navKey = "";
    mem.navBestDist = 1e9;
    mem.navProgressT = now;
    mem.lastSteer = 0;
    mem.recoverUntil = 0;
    mem.recoverSign = 1;
    mem.lastBumped = false;
    mem.bumpCount = 0;

    mem.slipTicks = 0;
    mem.sandUntil = 0;

    mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayDisabled = [false, false, false, false, false, false, false, false, false];
    mem.rayTravel = 0;
    mem.maxRayTravel = 0;

    mem._v4 = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.grid)) mem.grid = [];
  if (!mem.gridVisited) mem.gridVisited = {};
  if (!Array.isArray(mem.motorI)) mem.motorI = [0, 0];
  if (!Array.isArray(mem.motorGain)) mem.motorGain = [3, 3];
  if (!Array.isArray(mem.lastTargets)) mem.lastTargets = [0, 0];
  if (!Array.isArray(mem.prevTargets)) mem.prevTargets = [0, 0];
  if (!Array.isArray(mem.prevCmd)) mem.prevCmd = [0, 0];
  if (!Array.isArray(mem.stallTicks)) mem.stallTicks = [0, 0];
  if (!Array.isArray(mem.deadKick)) mem.deadKick = [0, 0];
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  if (!Array.isArray(mem.rayDisabled)) mem.rayDisabled = [false, false, false, false, false, false, false, false, false];

  let dt = 0.1;
  if (mem._lastT !== undefined) {
    const td = now - num(mem._lastT, now);
    if (td > 0.015 && td < 0.8) dt = td;
  }
  mem._lastT = now;
  mem.clock = now;

  const oldPX = num(mem.posX, rawX);
  const oldPY = num(mem.posY, rawY);
  const rawStep = dist(rawX, rawY, num(mem.rawPrevX, rawX), num(mem.rawPrevY, rawY));

  const rawDelta = mem.lastHeadRaw === undefined
    ? 0
    : wrap(headingRaw - num(mem.lastHeadRaw, headingRaw));
  if (mem.lastHeadRaw !== undefined) {
    const expected = (wr - wl) / 0.6 * dt / RAD;
    const mismatch = wrap(rawDelta - expected);
    if (Math.abs(mismatch) > 72 && Math.abs(expected) < 36) {
      mem.headingOffset = wrap(num(mem.headingOffset, 0) + mismatch);
    }
  }
  mem.lastHeadRaw = headingRaw;
  let headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  if (mem.gpsFrozen) {
    if (rawStep > 0.8 && rawStep < 8 && !docked) {
      mem.gpsFrozen = false;
      mem.gpsFreezeCount = 0;
      mem.freezeAccX = 0;
      mem.freezeAccY = 0;
      mem.posX = rawX;
      mem.posY = rawY;
    } else if (!docked && wheelAbs > 0.10) {
      const a = headingTrue * RAD;
      mem.posX += wheelAvg * dt * 0.66 * Math.cos(a);
      mem.posY += wheelAvg * dt * 0.66 * Math.sin(a);
    }
  } else if (rawStep < 0.02 && wheelAbs > 0.35 && !docked && !bumped) {
    mem.gpsFreezeCount = (mem.gpsFreezeCount || 0) + 1;
    const a = headingTrue * RAD;
    mem.freezeAccX = num(mem.freezeAccX, 0) + wheelAvg * dt * 0.66 * Math.cos(a);
    mem.freezeAccY = num(mem.freezeAccY, 0) + wheelAvg * dt * 0.66 * Math.sin(a);
    if (mem.gpsFreezeCount >= 14) {
      mem.gpsFrozen = true;
      mem.posX = rawX + mem.freezeAccX;
      mem.posY = rawY + mem.freezeAccY;
    } else {
      mem.posX = 0.60 * oldPX + 0.40 * rawX;
      mem.posY = 0.60 * oldPY + 0.40 * rawY;
    }
  } else {
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;
    if (rawStep > 8 && !docked) {
      mem.posX = oldPX;
      mem.posY = oldPY;
    } else {
      const alpha = wheelAbs > 0.20 ? 0.52 : 0.22;
      mem.posX = oldPX + alpha * (rawX - oldPX);
      mem.posY = oldPY + alpha * (rawY - oldPY);
    }
  }
  mem.rawPrevX = rawX;
  mem.rawPrevY = rawY;

  let px = num(mem.posX, rawX);
  let py = num(mem.posY, rawY);
  let stepX = px - oldPX;
  let stepY = py - oldPY;
  let stepDist = Math.hypot(stepX, stepY);

  const calDX = rawX - num(mem.calPrevX, rawX);
  const calDY = rawY - num(mem.calPrevY, rawY);
  if (!docked && !mem.gpsFrozen && wheelAvg > 0.30 &&
      Math.abs(wr - wl) < 0.13 && rawStep < 1.2) {
    mem.calDX = num(mem.calDX, 0) + calDX;
    mem.calDY = num(mem.calDY, 0) + calDY;
    mem.calSin = num(mem.calSin, 0) + Math.sin(headingRaw * RAD);
    mem.calCos = num(mem.calCos, 0) + Math.cos(headingRaw * RAD);
    mem.calN = (mem.calN || 0) + 1;
    if (Math.hypot(mem.calDX, mem.calDY) > 6 &&
        mem.calN > 12 &&
        Math.hypot(mem.calSin, mem.calCos) > 3) {
      const track = Math.atan2(mem.calDY, mem.calDX) / RAD;
      const avgRaw = Math.atan2(mem.calSin, mem.calCos) / RAD;
      const measuredOffset = wrap(avgRaw - track);
      const err = wrap(measuredOffset - num(mem.headingOffset, 0));
      mem.headingOffset = wrap(
        num(mem.headingOffset, 0) + clamp(err * 0.22, -6, 6)
      );
      mem.calDX = 0;
      mem.calDY = 0;
      mem.calSin = 0;
      mem.calCos = 0;
      mem.calN = 0;
    }
  } else {
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;
  }
  mem.calPrevX = rawX;
  mem.calPrevY = rawY;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  const groundSpeed = stepDist / Math.max(0.04, dt);
  if (!docked && wheelAbs > 0.18 && Math.abs(wr - wl) < 0.45 &&
      groundSpeed > 0.08 && groundSpeed < 1.35) {
    mem.vEst = 0.90 * num(mem.vEst, 0.52) +
      0.10 * clamp(groundSpeed, 0.25, 0.85);
  }
  mem.vEst = clamp(num(mem.vEst, 0.52), 0.35, 0.85);

  const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const hasRays = !!(obs.rays && typeof obs.rays.length === "number");
  const rays = [];
  let allMax = hasRays;
  for (let i = 0; i < 9; i++) {
    const r = clamp(num(hasRays ? obs.rays[i] : 15, 15), 0, 15);
    rays.push(r);
    if (r < 14.7) allMax = false;
    if (Math.abs(r - num(mem.rayLast[i], 15)) < 0.025) {
      mem.rayStale[i] = (mem.rayStale[i] || 0) + 1;
    } else {
      mem.rayStale[i] = 0;
      if (mem.rayDisabled[i] &&
          Math.abs(r - num(mem.rayLast[i], r)) > 0.5) {
        mem.rayDisabled[i] = false;
      }
    }
    mem.rayLast[i] = r;
  }

  mem.rayTravel = num(mem.rayTravel, 0) + stepDist;
  if (mem.rayTravel > 8) {
    for (let i = 0; i < 9; i++) {
      if (mem.rayStale[i] > 150 && rays[i] < 14.7) {
        mem.rayDisabled[i] = true;
      }
    }
    mem.rayTravel = 0;
  }
  let disabledCount = 0;
  for (let i = 0; i < 9; i++) {
    if (mem.rayDisabled[i]) disabledCount++;
  }
  if (allMax && wheelAbs > 0.15) {
    mem.maxRayTravel = num(mem.maxRayTravel, 0) + stepDist;
  } else {
    mem.maxRayTravel = 0;
  }
  const raysBlind = !hasRays || disabledCount >= 6 || mem.maxRayTravel > 45;

  if (wheelAbs > 0.85 && Math.abs(wheelAvg) > 0.30 &&
      groundSpeed < 0.24 && !bumped && !docked) {
    mem.slipTicks = (mem.slipTicks || 0) + 1;
    if (mem.slipTicks > 18) mem.sandUntil = now + 12;
  } else {
    mem.slipTicks = Math.max(0, (mem.slipTicks || 0) - 1);
  }

  const oldBattery = num(mem.prevBattery, battery);
  const db = oldBattery - battery;
  if (!docked && wheelAbs > 0.12 && stepDist > 0.025 &&
      Math.abs(db) < 0.08) {
    mem.energyBucket = num(mem.energyBucket, 0) +
      Math.max(0, db + solar * dt * 0.015);
    mem.distanceBucket = num(mem.distanceBucket, 0) + stepDist;
    if (mem.distanceBucket >= 12) {
      const measured = mem.energyBucket / Math.max(1, mem.distanceBucket);
      if (measured > 0.00015 && measured < 0.008) {
        const oldBurn = num(mem.burn, 0.00065);
        const alpha = measured > oldBurn ? 0.22 : 0.08;
        mem.burn = clamp(oldBurn + alpha * (measured - oldBurn),
                         0.00030, 0.0045);
      }
      mem.energyBucket = 0;
      mem.distanceBucket = 0;
    }
  }
  mem.prevBattery = battery;

  for (let i = 0; i < 2; i++) {
    const actual = i === 0 ? wl : wr;
    const pc = num(mem.prevCmd[i], 0);
    const pt = num(mem.prevTargets[i], 0);
    if (Math.abs(pc) > 0.14 && Math.abs(pt) > 0.14 &&
        actual * pt > 0 && Math.abs(actual) > 0.10) {
      const ratio = Math.abs(actual / pc);
      if (ratio > 1.2 && ratio < 7) {
        mem.motorGain[i] = clamp(
          0.985 * num(mem.motorGain[i], 3) + 0.015 * ratio,
          1.6, 6.2
        );
      }
    }
  }

  if (bumped && !mem.lastBumped) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.35, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.02) {
      mem.recoverSign = 1;
    } else {
      mem.recoverSign = rightDanger > leftDanger ? 1 : -1;
    }
    mem.recoverUntil = now + 1.15;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
  }
  mem.lastBumped = bumped;

  const timeLeft = Math.max(0, num(obs.timeLeft, mem.totalSeconds - now));
  const beacon = obs.beacon;
  let beaconDistance = null;
  if (beacon && Number.isFinite(Number(beacon.distance)) &&
      Number(beacon.distance) <= 25) {
    beaconDistance = clamp(num(beacon.distance, 100), 0, 100);
  }
  const baseDistance = docked
    ? 0
    : (beaconDistance !== null
        ? beaconDistance
        : dist(px, py, mem.baseX, mem.baseY));

  function speedForPlan() {
    return clamp(num(mem.vEst, 0.52), 0.42, 0.75);
  }

  function returnEnergy(d, n) {
    const count = Math.max(0, n);
    const route = Math.max(0, d) * 1.35 + 5;
    return route * num(mem.burn, 0.00065) *
      (1 + 0.20 * count) * 1.8 + 0.08 + 0.025 * count;
  }

  function returnTime(d) {
    if (d <= 2.2) return 0;
    return Math.max(0, d) * 1.25 / speedForPlan() + 18;
  }

  function motorCommand(i, target, actual, bias) {
    target = clamp(target, -0.95, 0.95);
    bias = clamp(num(bias, 0), -0.20, 0.20);
    let integ = num(mem.motorI[i], 0);
    const last = num(mem.lastTargets[i], 0);

    if (target * last < -0.025) {
      integ = 0;
      mem.stallTicks[i] = 0;
    }

    let raw;
    if (Math.abs(target) < 0.055) {
      integ *= 0.18;
      raw = -0.48 * actual + bias;
      if (Math.abs(actual) < 0.045 && Math.abs(bias) < 0.01) raw = 0;
    } else {
      const error = target - actual;
      raw = target / Math.max(1.6, num(mem.motorGain[i], 3)) +
        0.18 * error + integ + bias;

      const proposed = clamp(integ + 0.035 * error * dt, -0.14, 0.14);
      if (Math.abs(raw) < 0.90 || error * raw < 0) integ = proposed;
      raw = target / Math.max(1.6, num(mem.motorGain[i], 3)) +
        0.18 * error + integ + bias;

      if (Math.abs(target) > 0.13 && Math.abs(actual) < 0.075) {
        mem.stallTicks[i] = (mem.stallTicks[i] || 0) + 1;
        if (mem.stallTicks[i] > 10 && mem.stallTicks[i] % 5 === 0) {
          mem.deadKick[i] = clamp(num(mem.deadKick[i], 0) + 0.006, 0, 0.08);
        }
      } else {
        mem.stallTicks[i] = Math.max(0, (mem.stallTicks[i] || 0) - 1);
        if (Math.abs(actual) > 0.18) {
          mem.deadKick[i] = Math.max(0, num(mem.deadKick[i], 0) - 0.001);
        }
      }

      if (Math.abs(target) > 0.13 && Math.abs(actual) < 0.075) {
        const minCmd = 0.105 + num(mem.deadKick[i], 0);
        if (Math.abs(raw) < minCmd) raw = Math.sign(target) * minCmd;
      }
    }

    mem.motorI[i] = clamp(integ, -0.14, 0.14);
    mem.lastTargets[i] = target;
    return clamp(raw, -0.78, 0.78);
  }

  function drive(v, omega, holdBias) {
    let leftTarget = v - omega * 0.30;
    let rightTarget = v + omega * 0.30;
    const maxWheel = Math.max(Math.abs(leftTarget), Math.abs(rightTarget));
    if (maxWheel > 0.90) {
      const scale = 0.90 / maxWheel;
      leftTarget *= scale;
      rightTarget *= scale;
    }

    const bias = clamp(num(holdBias, 0), -0.20, 0.20);
    const left = motorCommand(0, leftTarget, wl, bias);
    const right = motorCommand(1, rightTarget, wr, bias);

    mem.prevCmd[0] = left;
    mem.prevCmd[1] = right;
    mem.prevTargets[0] = leftTarget;
    mem.prevTargets[1] = rightTarget;
    return { left: left, right: right, drill: false };
  }

  function stopOutput() {
    return drive(0, 0, 0);
  }

  function dangerTurn(goalErr) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.35, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.02) {
      return Math.sign(goalErr || 1);
    }
    return rightDanger > leftDanger ? 1 : -1;
  }

  function navigation(goalErr, goalDist, mode, key) {
    goalErr = wrap(goalErr);
    goalDist = Math.max(0, num(goalDist, 0));

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    } else if (goalDist < num(mem.navBestDist, 1e9) - 0.40) {
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    }

    if (now - num(mem.navProgressT, now) > 30 &&
        now >= num(mem.recoverUntil, 0)) {
      mem.recoverSign = dangerTurn(goalErr);
      mem.recoverUntil = now + 1.2;
      mem.navProgressT = now;
      mem.navBestDist = goalDist;
    }

    if (now < num(mem.recoverUntil, 0)) {
      const sign = num(mem.recoverSign, 1) || 1;
      return drive(-0.18, sign * 0.52, 0);
    }

    if (Math.abs(goalErr) > 108) {
      const turn = Math.sign(goalErr) || 1;
      return drive(0, turn * 0.62, 0);
    }

    const candidates = [-85, -70, -55, -40, -25, -10, 0,
                         10, 25, 40, 55, 70, 85,
                         clamp(goalErr, -85, 85)];
    let bestAngle = clamp(goalErr, -85, 85);
    let bestCost = 1e30;
    let bestAhead = 1e9;
    const look = 6.5;

    for (let c = 0; c < candidates.length; c++) {
      const a = candidates[c];
      const ar = a * RAD;
      const ca = Math.cos(ar);
      const sa = Math.sin(ar);
      let cost = Math.pow(wrap(a - goalErr) / 32, 2) +
        0.0005 * Math.abs(wrap(a - num(mem.lastSteer, 0)));
      let ahead = 1e9;

      for (let i = 0; i < 9; i++) {
        if (mem.rayDisabled[i]) continue;
        const r0 = rays[i];
        if (!(r0 > 0.05) || r0 >= 14.75) continue;

        const r = Math.max(0.10, r0 - 0.32);
        const rr = rayAngles[i] * RAD;
        const ox = r * Math.cos(rr);
        const oy = r * Math.sin(rr);
        const along = ox * ca + oy * sa;
        if (along < -0.25 || along > look) continue;
        const lateral = Math.abs(-ox * sa + oy * ca);

        if (along > 0 && lateral < 1.35) ahead = Math.min(ahead, along);
        if (lateral < 1.35) {
          const clearance = 1.25 - lateral;
          if (clearance > 0) {
            cost += clearance * clearance *
              (2.0 + 7.0 / Math.pow(Math.max(0.35, along - 0.25), 2));
          }
        } else if (lateral < 2.1 && along > 0) {
          cost += 0.06 * Math.pow(2.1 - lateral, 2);
        }
      }

      const globalAngle = (headingTrue + a) * RAD;
      const nx = px + 7 * Math.cos(globalAngle);
      const ny = py + 7 * Math.sin(globalAngle);
      if (nx < 3) cost += 2.5 * Math.pow(3 - nx, 2);
      if (ny < 3) cost += 2.5 * Math.pow(3 - ny, 2);
      if (nx > mem.mapW - 3) cost += 2.5 * Math.pow(nx - (mem.mapW - 3), 2);
      if (ny > mem.mapH - 3) cost += 2.5 * Math.pow(ny - (mem.mapH - 3), 2);

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
        bestAhead = ahead;
      }
    }
    mem.lastSteer = bestAngle;

    let cruise = mode === "site" ? 0.34 :
                 mode === "return" ? 0.52 : 0.48;
    if (raysBlind) cruise = Math.min(cruise, 0.34);
    if (mem.bumpCount >= 5) cruise = Math.min(cruise, 0.38);
    if (now < num(mem.sandUntil, 0)) cruise = Math.min(cruise, 0.32);

    let speed = cruise;
    if (Math.abs(bestAngle) > 30) {
      speed = 0;
    } else if (Math.abs(bestAngle) > 18) {
      speed *= 0.55;
    }

    if (mode === "site") {
      if (goalDist < 6) {
        speed = Math.min(speed, Math.max(0, (goalDist - 0.72) * 0.30));
      }
      if (goalDist <= 0.95) speed = 0;
    } else if (mode === "return") {
      if (goalDist < 12) speed = Math.min(speed, 0.10 + 0.14 * goalDist);
      if (goalDist <= 2.15) speed = 0;
    } else {
      if (goalDist < 10) {
        speed = Math.min(
          speed,
          Math.sqrt(Math.max(0, goalDist - 2.25) * 0.16)
        );
      }
      if (goalDist <= 2.4) speed = 0;
    }

    if (bestAhead < 1.1) speed = 0;
    else if (bestAhead < 1.8) speed = Math.min(speed, 0.12);
    else if (bestAhead < 2.7) speed = Math.min(speed, 0.22);
    else if (bestAhead < 3.7) speed = Math.min(speed, 0.32);
    else if (bestAhead < 5.0) speed = Math.min(speed, 0.42);

    if (Math.abs(wheelAvg) > 0.82) speed = 0;
    else if (Math.abs(wheelAvg) > 0.68) speed = Math.min(speed, 0.22);

    const travelAngle = (headingTrue + bestAngle) * RAD;
    const dx = Math.cos(travelAngle);
    const dy = Math.sin(travelAngle);
    if ((px < 5 && dx < 0) || (py < 5 && dy < 0) ||
        (px > mem.mapW - 5 && dx > 0) ||
        (py > mem.mapH - 5 && dy > 0)) {
      speed = Math.min(speed, 0.18);
    } else if ((px < 10 && dx < 0) || (py < 10 && dy < 0) ||
               (px > mem.mapW - 10 && dx > 0) ||
               (py > mem.mapH - 10 && dy > 0)) {
      speed = Math.min(speed, 0.32);
    }

    const omega = clamp(1.55 * bestAngle * RAD, -0.78, 0.78);
    return drive(speed, omega, 0);
  }

  function goHome() {
    if (docked || baseDistance <= 2.15) return stopOutput();

    let err;
    if (beacon && beaconDistance !== null &&
        Number.isFinite(Number(beacon.bearing))) {
      err = num(beacon.bearing, 0);
    } else {
      const bearing = Math.atan2(mem.baseY - py, mem.baseX - px) / RAD;
      err = wrap(bearing - headingTrue);
    }
    return navigation(err, baseDistance, "return", "base");
  }

  function taskObject(kind, x, y, key, index, value) {
    return {
      kind: kind,
      x: clamp(x, 3, mem.mapW - 3),
      y: clamp(y, 3, mem.mapH - 3),
      key: key || ("t:" + (mem.nextTaskId++)),
      index: index === undefined ? -1 : index,
      value: value === undefined ? 1 : value
    };
  }

  function taskValid(task) {
    if (!task) return false;
    if (task.kind === "hint") {
      return task.index >= 0 && task.index < mem.hints.length &&
        mem.hints[task.index].status === 0;
    }
    if (task.kind === "grid") return !mem.gridVisited[task.key];
    return task.kind === "local";
  }

  function candidatePlan(x, y, extra) {
    const d1 = dist(px, py, x, y);
    const d2 = dist(x, y, mem.baseX, mem.baseY);
    const route = d1 + d2 + extra;
    const load = 1 + 0.20 * (carried + 1);
    const energy = route * 1.25 * num(mem.burn, 0.00065) *
      load * 1.8 + 0.10 + 0.025 * (carried + 1);
    const time = route * 1.18 / speedForPlan() + 35;
    return { d1: d1, d2: d2, route: route, energy: energy, time: time };
  }

  function taskPlan(task) {
    let route;
    const s = mem.search;
    if (s && s.key === task.key && s.points && s.idx < s.points.length) {
      let x = px;
      let y = py;
      route = 0;
      for (let j = s.idx; j < s.points.length; j++) {
        const q = s.points[j];
        route += dist(x, y, q.x, q.y);
        x = q.x;
        y = q.y;
      }
      route += dist(x, y, mem.baseX, mem.baseY) + 8;
    } else {
      const d1 = dist(px, py, task.x, task.y);
      const d2 = dist(task.x, task.y, mem.baseX, mem.baseY);
      const extra = task.kind === "hint" ? 65 :
                    task.kind === "local" ? 110 : 45;
      route = d1 + d2 + extra;
    }

    const load = 1 + 0.20 * (carried + 1);
    const energy = route * 1.25 * num(mem.burn, 0.00065) *
      load * 1.8 + 0.10 + 0.025 * (carried + 1);
    const time = route * 1.18 / speedForPlan() + 35;
    return { route: route, energy: energy, time: time };
  }

  function chooseTask() {
    if (carried >= mem.capacity) return null;

    let best = null;
    let bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0) continue;
      const task = taskObject("hint", h.x, h.y, "h:" + i, i, h.value);
      const p = candidatePlan(task.x, task.y, 65);
      if (p.energy > battery - 0.045 || p.time > timeLeft - 7) continue;

      let cost;
      if (carried > 0) {
        const detour = Math.max(0, p.d1 + p.d2 - baseDistance);
        cost = 28 + 0.48 * p.d1 + 1.05 * detour + 0.24 * 65;
      } else {
        cost = 30 + p.d1 + 0.68 * p.d2 + 0.22 * 65;
      }
      const score = Math.max(0.15, h.value) /
        Math.pow(Math.max(1, cost), 0.88);
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    if (best) return best;

    let gridBest = null;
    let gridCost = 1e30;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (!g || mem.gridVisited[g.key]) continue;
      const p = candidatePlan(g.x, g.y, 45);
      if (p.energy > battery - 0.045 || p.time > timeLeft - 7) continue;
      const cost = p.d1 + 0.50 * p.d2;
      if (cost < gridCost) {
        gridCost = cost;
        gridBest = taskObject("grid", g.x, g.y, g.key, -1, 0.3);
      }
    }
    return gridBest;
  }

  function makeRing(cx, cy, radius, count) {
    const points = [];
    for (let i = 0; i < count; i++) {
      const a = 2 * PI * i / count;
      const x = clamp(cx + radius * Math.cos(a), 4, mem.mapW - 4);
      const y = clamp(cy + radius * Math.sin(a), 4, mem.mapH - 4);
      let duplicate = false;
      for (let j = 0; j < points.length; j++) {
        if (dist(x, y, points[j].x, points[j].y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) points.push({ x: x, y: y });
    }

    if (points.length > 1) {
      let nearest = 0;
      let nearestD = 1e30;
      for (let i = 0; i < points.length; i++) {
        const d = dist(px, py, points[i].x, points[i].y);
        if (d < nearestD) {
          nearestD = d;
          nearest = i;
        }
      }
      return points.slice(nearest).concat(points.slice(0, nearest));
    }
    return points;
  }

  function restoreResumeTask() {
    const resume = mem.resumeTask;
    mem.resumeTask = null;
    if (resume && taskValid(resume)) mem.task = resume;
  }

  function finishSearch() {
    const s = mem.search;
    const task = mem.task;
    if (task && task.kind === "hint" &&
        task.index >= 0 && task.index < mem.hints.length &&
        mem.hints[task.index].status === 0) {
      mem.hints[task.index].status = 2;
    } else if (task && task.kind === "grid") {
      mem.gridVisited[task.key] = true;
    }

    mem.search = null;
    mem.task = null;
    mem.navKey = "";
    if (task && task.kind === "local") {
      mem.lastSignalSearch = now;
      restoreResumeTask();
    }
  }

  function startSearch(task) {
    if (!task) return;
    let radius;
    let count;
    if (task.kind === "hint") {
      radius = 14;
      count = 12;
    } else if (task.kind === "local") {
      radius = 20;
      count = 16;
    } else {
      radius = 12;
      count = 10;
    }

    const points = makeRing(task.x, task.y, radius, count);
    if (!points.length) {
      finishSearch();
      return;
    }

    mem.search = {
      key: task.key,
      cx: task.x,
      cy: task.y,
      points: points,
      idx: 0,
      level: 0,
      centerScience: science,
      bestScience: science,
      bestX: px,
      bestY: py,
      pointStart: now,
      arriveT: null,
      maxUntil: now + (task.kind === "local" ? 420 : 360)
    };
    mem.navKey = "";
  }

  function updateSearch() {
    const s = mem.search;
    if (!s) return;
    if (now > num(s.maxUntil, now + 1)) {
      finishSearch();
      return;
    }
    if (science > num(s.bestScience, 0)) {
      s.bestScience = science;
      s.bestX = px;
      s.bestY = py;
    }
    if (!s.points || !s.points.length) {
      finishSearch();
      return;
    }

    if (s.idx < s.points.length) {
      const q = s.points[s.idx];
      const d = dist(px, py, q.x, q.y);
      if (d < 2.5) {
        if (s.arriveT === null) s.arriveT = now;
        if (now - s.arriveT >= 0.65) {
          s.idx++;
          s.arriveT = null;
          s.pointStart = now;
        }
      } else {
        s.arriveT = null;
        if (now - s.pointStart > 38) {
          s.idx++;
          s.pointStart = now;
        }
      }
    }

    if (s.idx >= s.points.length) {
      const gain = s.bestScience - s.centerScience;
      const moved = dist(s.cx, s.cy, s.bestX, s.bestY);
      const threshold = Math.max(0.08, Math.abs(s.centerScience) * 0.10);
      if (s.level === 0 && gain > threshold && moved > 3.5) {
        s.cx = s.bestX;
        s.cy = s.bestY;
        s.centerScience = s.bestScience;
        s.level = 1;
        s.points = makeRing(s.cx, s.cy, 7, 8);
        s.idx = 0;
        s.pointStart = now;
        s.arriveT = null;
        s.maxUntil = now + 180;
        mem.navKey = "";
        if (!s.points.length) finishSearch();
      } else {
        finishSearch();
      }
    }
  }

  function ensureTask() {
    if (mem.task && !taskValid(mem.task)) {
      mem.task = null;
      mem.search = null;
    }
    if (!mem.task) mem.task = chooseTask();
  }

  function discardTask() {
    const task = mem.task;
    if (task && task.kind === "hint" &&
        task.index >= 0 && task.index < mem.hints.length &&
        mem.hints[task.index].status === 0) {
      mem.hints[task.index].status = 2;
    } else if (task && task.kind === "grid") {
      mem.gridVisited[task.key] = true;
    }
    mem.task = null;
    mem.search = null;
    mem.navKey = "";
    if (task && task.kind === "local") {
      mem.lastSignalSearch = now;
      restoreResumeTask();
    }
  }

  const siteObs = obs.site;
  let reportedSiteDistance = 99;
  let reportedSiteBearing = 0;
  let hasReportedSite = false;
  if (siteObs && Number.isFinite(Number(siteObs.distance))) {
    reportedSiteDistance = clamp(num(siteObs.distance, 99), 0, 20);
    reportedSiteBearing = wrap(num(siteObs.bearing, 0));
    hasReportedSite = reportedSiteDistance <= 8.5;
  }

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const justSampled = carried > oldCarried + 0.01 ||
                      carriedValue > oldCarriedValue + 0.01;
  const justDelivered = delivered > oldDelivered + 0.01 ||
                        (docked && carried < oldCarried - 0.01);

  if (justSampled) {
    const sx = Number.isFinite(Number(mem.sampleSiteX))
      ? Number(mem.sampleSiteX)
      : num(mem.sampleX, px);
    const sy = Number.isFinite(Number(mem.sampleSiteY))
      ? Number(mem.sampleSiteY)
      : num(mem.sampleY, py);
    mem.lastSampleSiteX = sx;
    mem.lastSampleSiteY = sy;
    mem.suppressSiteUntil = now + 0.6;

    for (let i = 0; i < mem.hints.length; i++) {
      if (dist(sx, sy, mem.hints[i].x, mem.hints[i].y) < 25) {
        mem.hints[i].status = 1;
      }
    }

    const task = mem.task;
    const search = mem.search;
    let linked = false;
    if (task) {
      if (task.kind === "local") {
        linked = true;
      } else if (task.kind === "hint" || task.kind === "grid") {
        linked = dist(sx, sy, task.x, task.y) < 28 ||
          !!(search && search.key === task.key);
      }
    }

    if (linked || (task && !taskValid(task))) {
      const wasLocal = task && task.kind === "local";
      mem.task = null;
      mem.search = null;
      mem.navKey = "";
      if (wasLocal) restoreResumeTask();
    }

    mem.sampling = false;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }

  if (justDelivered) {
    mem.returning = false;
    mem.sampling = false;
  }

  mem.prevCarried = carried;
  mem.prevCarriedValue = carriedValue;
  mem.prevDelivered = delivered;

  let siteVisible = false;
  let siteDistance = 99;
  let siteBearing = 0;
  let siteGX = NaN;
  let siteGY = NaN;
  if (hasReportedSite) {
    siteDistance = reportedSiteDistance;
    siteBearing = reportedSiteBearing;
    const a = (headingTrue + siteBearing) * RAD;
    siteGX = px + siteDistance * Math.cos(a);
    siteGY = py + siteDistance * Math.sin(a);

    const recentlySampledSame =
      now < num(mem.suppressSiteUntil, -1) &&
      Number.isFinite(Number(mem.lastSampleSiteX)) &&
      Number.isFinite(Number(mem.lastSampleSiteY)) &&
      dist(siteGX, siteGY, Number(mem.lastSampleSiteX),
           Number(mem.lastSampleSiteY)) < 2.5;
    siteVisible = !recentlySampledSame;
  }

  function beginSampling() {
    mem.sampling = true;
    mem.sampleX = px;
    mem.sampleY = py;
    mem.sampleSiteX = Number.isFinite(siteGX) ? siteGX : null;
    mem.sampleSiteY = Number.isFinite(siteGY) ? siteGY : null;
    mem.sampleStart = now;
    mem.sampleStartDistance = siteDistance;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }

  function sampleOutput() {
    if (!mem.sampling) return null;

    const progress = Math.max(0, num(obs.drilling, 0));
    let range = 99;
    let matchingSite = false;

    if (siteVisible &&
        Number.isFinite(Number(mem.sampleSiteX)) &&
        Number.isFinite(Number(mem.sampleSiteY))) {
      matchingSite = dist(
        siteGX, siteGY,
        Number(mem.sampleSiteX), Number(mem.sampleSiteY)
      ) < 5;
    }

    if (siteVisible && matchingSite) {
      range = siteDistance;
    } else if (Number.isFinite(Number(mem.sampleSiteX)) &&
               Number.isFinite(Number(mem.sampleSiteY))) {
      range = dist(px, py, Number(mem.sampleSiteX), Number(mem.sampleSiteY));
    } else {
      range = dist(px, py, num(mem.sampleX, px), num(mem.sampleY, py)) +
        num(mem.sampleStartDistance, 1);
    }

    if ((range > 1.72 && progress < 5.8) ||
        (now - num(mem.sampleStart, now) > 15 && progress < 5.8)) {
      mem.sampling = false;
      mem.stillTicks = 0;
      mem.holdI = 0;
      return null;
    }

    if (!docked && progress < 5.8) {
      const required = returnEnergy(baseDistance, carried + 1) + 0.04;
      if (battery < required ||
          timeLeft < returnTime(baseDistance) + 6) {
        mem.sampling = false;
        mem.returning = true;
        return null;
      }
    }

    const slow = Math.abs(wl) < 0.13 && Math.abs(wr) < 0.13;
    if (slow) mem.stillTicks = (mem.stillTicks || 0) + 1;
    else mem.stillTicks = 0;

    const ex = num(mem.sampleX, px) - px;
    const ey = num(mem.sampleY, py) - py;
    const along = ex * Math.cos(headingTrue * RAD) +
                  ey * Math.sin(headingTrue * RAD);
    const velAlong = (stepX * Math.cos(headingTrue * RAD) +
                      stepY * Math.sin(headingTrue * RAD)) /
                     Math.max(0.04, dt);

    if (Math.abs(along) > 0.02) {
      mem.holdI = clamp(
        num(mem.holdI, 0) + 0.006 * along * dt,
        -0.08, 0.08
      );
    }
    const holdSpeed = clamp(0.38 * along - 0.30 * velAlong, -0.13, 0.13);
    const holdBias = clamp(
      0.0035 * clamp(pitch, -25, 25) + num(mem.holdI, 0),
      -0.12, 0.12
    );
    const cmd = drive(holdSpeed, 0, holdBias);
    const inRange = range <= 1.48;
    const drill = inRange && slow && mem.stillTicks >= 2;
    return { left: cmd.left, right: cmd.right, drill: !!drill };
  }

  function canStartSample() {
    if (carried >= mem.capacity) return false;
    if (!docked) {
      if (battery < returnEnergy(baseDistance, carried + 1) + 0.13) return false;
      if (timeLeft < returnTime(baseDistance) + 12) return false;
    } else if (battery < returnEnergy(baseDistance, carried + 1) + 0.04) {
      return false;
    }
    return true;
  }

  function maybeStartSignalSearch() {
    if (mem.search || mem.sampling || mem.returning ||
        carried >= mem.capacity || science < 0.70 ||
        now - num(mem.lastSignalSearch, -10000) < 100 ||
        mem.resumeTask) return;

    if (mem.task && mem.task.kind === "local") return;
    if (mem.task && dist(px, py, mem.task.x, mem.task.y) <= 28) return;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.status === 0 && dist(px, py, h.x, h.y) < 26) return;
    }

    if (mem.task) mem.resumeTask = mem.task;
    mem.task = taskObject(
      "local", px, py, "local:" + Math.floor(now) + ":" + mem.nextTaskId++, -1, 1
    );
    mem.lastSignalSearch = now;
    startSearch(mem.task);
  }

  if (docked) mem.returning = false;

  if (docked && carried > 0) return stopOutput();

  if (!mem.sampling && !docked) {
    const homeNeed = returnEnergy(baseDistance, carried);
    if (carried >= mem.capacity ||
        battery < homeNeed + (carried > 0 ? 0.08 : 0.10) ||
        timeLeft < returnTime(baseDistance) + (carried > 0 ? 10 : 5)) {
      mem.returning = true;
    }
  }

  if (mem.returning && !docked) return goHome();

  if (mem.sampling) {
    const out = sampleOutput();
    if (out) return out;
    if (mem.returning && !docked) return goHome();
  }

  if (siteVisible && !mem.returning) {
    if (carried >= mem.capacity || !canStartSample()) {
      if (!docked) {
        mem.returning = true;
        return goHome();
      }
      return stopOutput();
    }

    if (!mem.sampling &&
        (siteDistance <= 1.12 ||
         (siteDistance <= 1.48 && wheelAbs < 0.13))) {
      beginSampling();
      const out = sampleOutput();
      if (out) return out;
    }

    return navigation(siteBearing, siteDistance, "site", "visible-site");
  }

  if (!mem.returning && !mem.sampling) maybeStartSignalSearch();

  for (let guard = 0; guard < 6; guard++) {
    ensureTask();

    if (!mem.task) {
      if (docked) return stopOutput();
      mem.returning = true;
      return goHome();
    }

    const task = mem.task;

    if (task.kind === "local" && !mem.search) {
      startSearch(task);
      if (!mem.search) continue;
    }

    if (mem.search && mem.search.key === task.key) {
      updateSearch();
      if (!mem.task || !mem.search) continue;

      const p = taskPlan(mem.task);
      if (p.time > timeLeft - 5) {
        if (docked) {
          discardTask();
          continue;
        }
        mem.returning = true;
        return goHome();
      }
      if (p.energy > battery - 0.035) {
        if (docked) return stopOutput();
        mem.returning = true;
        return goHome();
      }

      const s = mem.search;
      const q = s.points[s.idx];
      if (!q) {
        finishSearch();
        continue;
      }
      const d = dist(px, py, q.x, q.y);
      const bearing = Math.atan2(q.y - py, q.x - px) / RAD;
      const key = "search:" + s.key + ":" + s.level + ":" + s.idx;
      return navigation(wrap(bearing - headingTrue), d, "waypoint", key);
    }

    const d = dist(px, py, task.x, task.y);
    if (d < 4.5) {
      if (task.kind === "grid" && science < 0.15) {
        mem.gridVisited[task.key] = true;
        mem.task = null;
        mem.search = null;
        continue;
      }
      startSearch(task);
      continue;
    }

    const p = taskPlan(task);
    if (p.time > timeLeft - 5) {
      if (docked) {
        discardTask();
        continue;
      }
      mem.returning = true;
      return goHome();
    }
    if (p.energy > battery - 0.035) {
      if (docked) return stopOutput();
      mem.returning = true;
      return goHome();
    }

    const bearing = Math.atan2(task.y - py, task.x - px) / RAD;
    return navigation(
      wrap(bearing - headingTrue),
      d,
      "waypoint",
      "task:" + task.key
    );
  }

  if (docked) return stopOutput();
  mem.returning = true;
  return goHome();
}

function act(obs, mem) {
  obs = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const PI = Math.PI;
  const RAD = PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, fallback) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
  };
  const finite = (v) =>
    v !== null && v !== undefined && Number.isFinite(Number(v));
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);
  const sign = (x) => x < 0 ? -1 : 1;

  const now = num(obs.t, num(mem.clock, 0));
  const rawX = num(obs.x, 200);
  const rawY = num(obs.y, 200);
  const headingRaw = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const wheelAvg = 0.5 * (wl + wr);
  const wheelAbs = 0.5 * (Math.abs(wl) + Math.abs(wr));
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const battery = Math.max(0, num(obs.battery, 0));
  const solar = Math.max(0, num(obs.solar, 0));
  const carried = Math.max(0, num(obs.carried, 0));
  const carriedValue = Math.max(0, num(obs.carriedValue, 0));
  const delivered = Math.max(0, num(obs.delivered, 0));
  const science = Math.max(0, num(obs.science, 0));
  const pitch = num(obs.pitch, 0);

  if (!mem._v5) {
    const mission = obs.mission || {};
    let mapW = 400;
    let mapH = 400;
    const size = mission.size;
    if (typeof size === "number") {
      mapW = size;
      mapH = size;
    } else if (Array.isArray(size)) {
      mapW = num(size[0], 400);
      mapH = num(size[1], mapW);
    } else if (size && typeof size === "object") {
      mapW = num(size.width, num(size.x, 400));
      mapH = num(size.height, num(size.y, mapW));
    } else {
      mapW = num(mission.width, 400);
      mapH = num(mission.height, 400);
    }
    mapW = Math.max(20, mapW);
    mapH = Math.max(20, mapH);

    const base = mission.base || {};
    mem.mapW = mapW;
    mem.mapH = mapH;
    mem.baseX = num(base.x, mapW * 0.5);
    mem.baseY = num(base.y, mapH * 0.5);
    mem.capacity = Math.max(1, num(mission.capacity, 5));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));

    mem.hints = [];
    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const x = num(h.x, NaN);
      const y = num(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      let value = num(h.estimate, num(h.value, 1));
      if (!(value > 0)) value = 0.2;
      mem.hints.push({
        x: clamp(x, 3, mapW - 3),
        y: clamp(y, 3, mapH - 3),
        value: value,
        status: 0
      });
    }

    mem.grid = [];
    let gx = 0;
    for (let x = 35; x <= mapW - 25; x += 55, gx++) {
      let gy = 0;
      for (let y = 35; y <= mapH - 25; y += 55, gy++) {
        mem.grid.push({
          x: clamp(x, 4, mapW - 4),
          y: clamp(y, 4, mapH - 4),
          key: "g:" + gx + ":" + gy
        });
        gy++;
      }
      gx++;
    }
    mem.gridVisited = {};

    mem.task = null;
    mem.search = null;
    mem.resumeTask = null;
    mem.nextTaskId = 1;
    mem.returning = false;
    mem.lastLocalX = null;
    mem.lastLocalY = null;
    mem.lastLocalT = -10000;
    mem.localCooldown = 0;

    mem.clock = now;
    mem._lastT = now;
    mem.headingOffset = 0;
    mem.lastHeadRaw = headingRaw;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.rawPrevX = rawX;
    mem.rawPrevY = rawY;
    mem.gpsFrozen = false;
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;

    mem.calPrevX = rawX;
    mem.calPrevY = rawY;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;

    mem.prevBattery = battery;
    mem.burn = 0.0009;
    mem.energyBucket = 0;
    mem.distanceBucket = 0;
    mem.vEst = 0.48;

    mem.prevCarried = carried;
    mem.prevCarriedValue = carriedValue;
    mem.prevDelivered = delivered;

    mem.sampling = false;
    mem.sampleX = rawX;
    mem.sampleY = rawY;
    mem.sampleSiteX = null;
    mem.sampleSiteY = null;
    mem.sampleStart = 0;
    mem.stillTicks = 0;
    mem.holdI = 0;
    mem.lastSampleX = null;
    mem.lastSampleY = null;
    mem.suppressSiteUntil = -1;

    mem.motorI = [0, 0];
    mem.motorGain = [3, 3];
    mem.lastTargets = [0, 0];
    mem.prevCmd = [0, 0];
    mem.stallTicks = [0, 0];
    mem.deadKick = [0, 0];

    mem.navKey = "";
    mem.navBestDist = 1e9;
    mem.navProgressT = now;
    mem.lastSteer = 0;
    mem.recoverUntil = 0;
    mem.recoverSign = 1;
    mem.lastBumped = false;
    mem.bumpCount = 0;

    mem.slipTicks = 0;
    mem.sandUntil = 0;

    mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayDisabled = [false, false, false, false, false, false, false, false, false];
    mem.rayTravel = 0;

    mem.baseScience = science;
    mem._v5 = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.grid)) mem.grid = [];
  if (!mem.gridVisited) mem.gridVisited = {};
  if (!Array.isArray(mem.motorI)) mem.motorI = [0, 0];
  if (!Array.isArray(mem.motorGain)) mem.motorGain = [3, 3];
  if (!Array.isArray(mem.lastTargets)) mem.lastTargets = [0, 0];
  if (!Array.isArray(mem.prevCmd)) mem.prevCmd = [0, 0];
  if (!Array.isArray(mem.stallTicks)) mem.stallTicks = [0, 0];
  if (!Array.isArray(mem.deadKick)) mem.deadKick = [0, 0];
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  if (!Array.isArray(mem.rayDisabled)) mem.rayDisabled = [false, false, false, false, false, false, false, false, false];

  let dt = 0.1;
  if (mem._lastT !== undefined) {
    const td = now - num(mem._lastT, now);
    if (td > 0.015 && td < 0.8) dt = td;
  }
  mem._lastT = now;
  mem.clock = now;

  const oldPX = num(mem.posX, rawX);
  const oldPY = num(mem.posY, rawY);
  const rawStep = dist(rawX, rawY, num(mem.rawPrevX, rawX), num(mem.rawPrevY, rawY));

  let headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));
  const headingDelta = wrap(headingRaw - num(mem.lastHeadRaw, headingRaw));
  const expectedYaw = (wr - wl) / 0.6 * dt / RAD;
  const yawMismatch = wrap(headingDelta - expectedYaw);
  if (mem.lastHeadRaw !== undefined &&
      Math.abs(yawMismatch) > 55 &&
      Math.abs(expectedYaw) < 20) {
    mem.headingOffset = wrap(
      num(mem.headingOffset, 0) + clamp(yawMismatch, -150, 150)
    );
    headingTrue = wrap(headingRaw - mem.headingOffset);
  }
  mem.lastHeadRaw = headingRaw;

  if (mem.gpsFrozen) {
    if (rawStep > 0.35 && rawStep < 12 && !docked) {
      mem.gpsFrozen = false;
      mem.gpsFreezeCount = 0;
      mem.freezeAccX = 0;
      mem.freezeAccY = 0;
      mem.posX = rawX;
      mem.posY = rawY;
    } else if (!docked && wheelAbs > 0.10 && !bumped) {
      const a = headingTrue * RAD;
      mem.posX += wheelAvg * dt * 0.62 * Math.cos(a);
      mem.posY += wheelAvg * dt * 0.62 * Math.sin(a);
    }
  } else if (rawStep < 0.015 && wheelAbs > 0.32 && !docked && !bumped) {
    mem.gpsFreezeCount = (mem.gpsFreezeCount || 0) + 1;
    const a = headingTrue * RAD;
    mem.freezeAccX = num(mem.freezeAccX, 0) +
      wheelAvg * dt * 0.62 * Math.cos(a);
    mem.freezeAccY = num(mem.freezeAccY, 0) +
      wheelAvg * dt * 0.62 * Math.sin(a);
    if (mem.gpsFreezeCount >= 20) {
      mem.gpsFrozen = true;
      mem.posX = rawX + mem.freezeAccX;
      mem.posY = rawY + mem.freezeAccY;
    } else {
      mem.posX = 0.78 * oldPX + 0.22 * rawX;
      mem.posY = 0.78 * oldPY + 0.22 * rawY;
    }
  } else {
    mem.gpsFreezeCount = 0;
    mem.freezeAccX = 0;
    mem.freezeAccY = 0;
    if (rawStep > 12 && !docked) {
      mem.posX = oldPX;
      mem.posY = oldPY;
    } else {
      const alpha = wheelAbs > 0.20 ? 0.56 : 0.22;
      mem.posX = oldPX + alpha * (rawX - oldPX);
      mem.posY = oldPY + alpha * (rawY - oldPY);
    }
  }
  mem.rawPrevX = rawX;
  mem.rawPrevY = rawY;

  let px = num(mem.posX, rawX);
  let py = num(mem.posY, rawY);
  let stepX = px - oldPX;
  let stepY = py - oldPY;
  let stepDist = Math.hypot(stepX, stepY);

  const calDX = rawX - num(mem.calPrevX, rawX);
  const calDY = rawY - num(mem.calPrevY, rawY);
  if (!docked && !mem.gpsFrozen && wheelAvg > 0.28 &&
      Math.abs(wr - wl) < 0.16 && rawStep > 0.015 && rawStep < 1.5) {
    mem.calDX = num(mem.calDX, 0) + calDX;
    mem.calDY = num(mem.calDY, 0) + calDY;
    mem.calSin = num(mem.calSin, 0) + Math.sin(headingRaw * RAD);
    mem.calCos = num(mem.calCos, 0) + Math.cos(headingRaw * RAD);
    mem.calN = (mem.calN || 0) + 1;
    if (Math.hypot(mem.calDX, mem.calDY) > 5 &&
        mem.calN > 10 &&
        Math.hypot(mem.calSin, mem.calCos) > 3) {
      const track = Math.atan2(mem.calDY, mem.calDX) / RAD;
      const avgRaw = Math.atan2(mem.calSin, mem.calCos) / RAD;
      const measuredOffset = wrap(avgRaw - track);
      const err = wrap(measuredOffset - num(mem.headingOffset, 0));
      if (Math.abs(err) < 40) {
        mem.headingOffset = wrap(
          num(mem.headingOffset, 0) + clamp(err * 0.08, -4, 4)
        );
      }
      mem.calDX = 0;
      mem.calDY = 0;
      mem.calSin = 0;
      mem.calCos = 0;
      mem.calN = 0;
    }
  } else {
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;
  }
  mem.calPrevX = rawX;
  mem.calPrevY = rawY;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  const groundSpeed = stepDist / Math.max(0.04, dt);
  if (!docked && !mem.gpsFrozen && wheelAbs > 0.20 &&
      groundSpeed > 0.16 && groundSpeed < 1.35 && rawStep < 1.5) {
    mem.vEst = 0.94 * num(mem.vEst, 0.48) +
      0.06 * clamp(groundSpeed, 0.25, 0.85);
  }
  mem.vEst = clamp(num(mem.vEst, 0.48), 0.30, 0.85);

  const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const hasRays = !!(obs.rays && typeof obs.rays.length === "number");
  const rays = [];
  let disabledCount = 0;
  for (let i = 0; i < 9; i++) {
    const r = clamp(num(hasRays ? obs.rays[i] : 15, 15), 0, 15);
    rays.push(r);

    if (Math.abs(r - num(mem.rayLast[i], 15)) < 0.025) {
      mem.rayStale[i] = (mem.rayStale[i] || 0) + 1;
    } else {
      mem.rayStale[i] = 0;
      if (mem.rayDisabled[i] &&
          Math.abs(r - num(mem.rayLast[i], r)) > 0.5) {
        mem.rayDisabled[i] = false;
      }
    }
    mem.rayLast[i] = r;
  }

  mem.rayTravel = num(mem.rayTravel, 0) + stepDist;
  if (mem.rayTravel > 18) {
    for (let i = 0; i < 9; i++) {
      if (mem.rayStale[i] > 220 && rays[i] < 14.7) {
        mem.rayDisabled[i] = true;
      }
    }
    mem.rayTravel = 0;
  }
  for (let i = 0; i < 9; i++) {
    if (mem.rayDisabled[i]) disabledCount++;
  }
  const raysBlind = !hasRays || disabledCount >= 6;

  if (!docked && wheelAbs > 0.82 && Math.abs(wheelAvg) > 0.28 &&
      groundSpeed < 0.24 && !bumped) {
    mem.slipTicks = (mem.slipTicks || 0) + 1;
    if (mem.slipTicks > 18) mem.sandUntil = now + 15;
  } else {
    mem.slipTicks = Math.max(0, (mem.slipTicks || 0) - 1);
  }

  const oldBattery = num(mem.prevBattery, battery);
  const db = oldBattery - battery;
  if (!docked && wheelAbs > 0.12 && stepDist > 0.025 &&
      Math.abs(db) < 0.10) {
    mem.energyBucket = num(mem.energyBucket, 0) +
      Math.max(0, db + solar * dt * 0.012);
    mem.distanceBucket = num(mem.distanceBucket, 0) + stepDist;
    if (mem.distanceBucket >= 9) {
      const measured = mem.energyBucket / Math.max(1, mem.distanceBucket);
      if (measured > 0.00008 && measured < 0.012) {
        const oldBurn = num(mem.burn, 0.0009);
        const alpha = measured > oldBurn ? 0.20 : 0.08;
        mem.burn = clamp(oldBurn + alpha * (measured - oldBurn),
                         0.00030, 0.010);
      }
      mem.energyBucket = 0;
      mem.distanceBucket = 0;
    }
  }
  mem.prevBattery = battery;

  for (let i = 0; i < 2; i++) {
    const actual = i === 0 ? wl : wr;
    const cmd = num(mem.prevCmd[i], 0);
    const target = num(mem.lastTargets[i], 0);
    if (Math.abs(cmd) > 0.14 && Math.abs(target) > 0.14 &&
        actual * target > 0 && Math.abs(actual) > 0.10) {
      const ratio = Math.abs(actual / cmd);
      if (ratio > 1.0 && ratio < 7.0) {
        mem.motorGain[i] = clamp(
          0.99 * num(mem.motorGain[i], 3) + 0.01 * ratio,
          1.4, 6.5
        );
      }
    }
  }

  if (bumped && !mem.lastBumped) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.35, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    mem.recoverSign = rightDanger > leftDanger ? 1 : -1;
    mem.recoverUntil = now + 1.15;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
  }
  mem.lastBumped = bumped;

  const timeLeft = Math.max(0, num(obs.timeLeft, mem.totalSeconds - now));

  const oldCarried = num(mem.prevCarried, carried);
  const oldCarriedValue = num(mem.prevCarriedValue, carriedValue);
  const oldDelivered = num(mem.prevDelivered, delivered);
  const justSampled = carried > oldCarried + 0.01 ||
                      carriedValue > oldCarriedValue + 0.01;
  const justDelivered = delivered > oldDelivered + 0.01 ||
                        (docked && carried < oldCarried - 0.01);

  if (justSampled) {
    const sx = finite(mem.sampleSiteX)
      ? Number(mem.sampleSiteX)
      : num(mem.sampleX, px);
    const sy = finite(mem.sampleSiteY)
      ? Number(mem.sampleSiteY)
      : num(mem.sampleY, py);
    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.suppressSiteUntil = now + 0.45;

    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i] &&
          dist(sx, sy, mem.hints[i].x, mem.hints[i].y) < 25) {
        mem.hints[i].status = 1;
      }
    }
    if (mem.task && mem.task.kind === "hint" &&
        dist(sx, sy, mem.task.x, mem.task.y) < 28 &&
        mem.task.index >= 0 && mem.task.index < mem.hints.length) {
      mem.hints[mem.task.index].status = 1;
    }
    if (mem.search) mem.search.sampled = true;
    mem.sampling = false;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }

  if (justDelivered) {
    mem.returning = false;
    mem.sampling = false;
    mem.task = null;
    mem.search = null;
    mem.resumeTask = null;
    mem.navKey = "";
  }

  mem.prevCarried = carried;
  mem.prevCarriedValue = carriedValue;
  mem.prevDelivered = delivered;

  let siteVisible = false;
  let siteDistance = 99;
  let siteBearing = 0;
  let siteGX = NaN;
  let siteGY = NaN;
  const siteObs = obs.site;
  if (siteObs && finite(siteObs.distance)) {
    siteDistance = clamp(num(siteObs.distance, 99), 0, 12);
    siteBearing = wrap(num(siteObs.bearing, 0));
    const a = (headingTrue + siteBearing) * RAD;
    siteGX = px + siteDistance * Math.cos(a);
    siteGY = py + siteDistance * Math.sin(a);
    siteVisible = siteDistance <= 8.5;

    if (siteVisible && now < num(mem.suppressSiteUntil, -1) &&
        finite(mem.lastSampleX) && finite(mem.lastSampleY) &&
        dist(siteGX, siteGY, Number(mem.lastSampleX),
             Number(mem.lastSampleY)) < 3) {
      siteVisible = false;
    }
  }

  const beacon = obs.beacon;
  const beaconDistance =
    beacon && finite(beacon.distance) && Number(beacon.distance) <= 25
      ? Math.max(0, num(beacon.distance, 0))
      : null;
  const gpsBaseDistance = dist(px, py, mem.baseX, mem.baseY);
  const baseDistance = docked
    ? 0
    : (beaconDistance !== null ? beaconDistance : gpsBaseDistance);

  function returnEnergy(d, n) {
    const count = Math.max(0, n);
    return Math.max(0, d) * 1.62 * num(mem.burn, 0.0009) *
      (1 + 0.20 * count) + 0.11 + 0.045 * count;
  }

  function returnTime(d) {
    if (d <= 2.2) return 0;
    const speed = clamp(num(mem.vEst, 0.48) * 0.76, 0.28, 0.66);
    return (d - 2.2) / speed + 20;
  }

  function routeEnergy(route, n) {
    const count = Math.max(0, n);
    return (Math.max(0, route) * 1.55 + 8) *
      num(mem.burn, 0.0009) *
      (1 + 0.20 * count) + 0.12 + 0.05 * count;
  }

  function motorCommand(i, target, actual, bias) {
    target = clamp(target, -0.72, 0.72);
    bias = clamp(num(bias, 0), -0.14, 0.14);
    let integ = num(mem.motorI[i], 0);
    const last = num(mem.lastTargets[i], 0);

    if (target * last < -0.025) {
      integ = 0;
      mem.stallTicks[i] = 0;
    }

    let raw;
    if (Math.abs(target) < 0.045) {
      integ *= 0.35;
      raw = -0.52 * actual + bias;
      if (Math.abs(actual) < 0.035 && Math.abs(bias) < 0.008) raw = 0;
    } else {
      const error = target - actual;
      raw = target / Math.max(1.4, num(mem.motorGain[i], 3)) +
        0.24 * error + integ + bias;

      const proposed = clamp(integ + 0.07 * error * dt, -0.18, 0.18);
      if (Math.abs(raw) < 0.92 || error * raw < 0) integ = proposed;
      raw = target / Math.max(1.4, num(mem.motorGain[i], 3)) +
        0.24 * error + integ + bias;

      if (Math.abs(target) > 0.13 && Math.abs(actual) < 0.075) {
        mem.stallTicks[i] = (mem.stallTicks[i] || 0) + 1;
        if (mem.stallTicks[i] > 8 && mem.stallTicks[i] % 5 === 0) {
          mem.deadKick[i] = clamp(
            num(mem.deadKick[i], 0) + 0.006, 0, 0.10
          );
        }
      } else {
        mem.stallTicks[i] = Math.max(0, (mem.stallTicks[i] || 0) - 1);
        if (Math.abs(actual) > 0.16) {
          mem.deadKick[i] = Math.max(
            0, num(mem.deadKick[i], 0) - 0.001
          );
        }
      }

      if (Math.abs(target) > 0.13 && Math.abs(actual) < 0.075) {
        const minimum = 0.12 + num(mem.deadKick[i], 0);
        if (Math.abs(raw) < minimum) raw = Math.sign(target) * minimum;
      }
    }

    mem.motorI[i] = clamp(integ, -0.18, 0.18);
    return clamp(raw, -0.68, 0.68);
  }

  function drive(v, omega, holdBias) {
    let leftTarget = v - omega * 0.30;
    let rightTarget = v + omega * 0.30;
    const maxWheel = Math.max(Math.abs(leftTarget), Math.abs(rightTarget));
    if (maxWheel > 0.72) {
      const scale = 0.72 / maxWheel;
      leftTarget *= scale;
      rightTarget *= scale;
    }
    const bias = clamp(num(holdBias, 0), -0.14, 0.14);
    const left = motorCommand(0, leftTarget, wl, bias);
    const right = motorCommand(1, rightTarget, wr, bias);
    mem.lastTargets[0] = leftTarget;
    mem.lastTargets[1] = rightTarget;
    mem.prevCmd[0] = left;
    mem.prevCmd[1] = right;
    return { left: left, right: right, drill: false };
  }

  function stopOutput() {
    return drive(0, 0, 0);
  }

  function dangerTurn(goalErr) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.35, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.02) {
      return Math.sign(goalErr || 1);
    }
    return rightDanger > leftDanger ? 1 : -1;
  }

  function navigation(goalErr, goalDist, mode, key) {
    goalErr = wrap(goalErr);
    goalDist = Math.max(0, num(goalDist, 0));

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    } else if (goalDist < num(mem.navBestDist, 1e9) - 0.40) {
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    }

    if (goalDist > 4 &&
        now - num(mem.navProgressT, now) > 35 &&
        now >= num(mem.recoverUntil, 0)) {
      mem.recoverSign = dangerTurn(goalErr);
      mem.recoverUntil = now + 1.0;
      mem.navProgressT = now;
      mem.navBestDist = goalDist;
    }

    if (now < num(mem.recoverUntil, 0)) {
      const turn = num(mem.recoverSign, 1) || 1;
      return drive(-0.22, turn * 0.52, 0);
    }

    if ((mode === "return" && goalDist <= 2.25) ||
        (mode === "site" && goalDist <= 1.0) ||
        (mode === "waypoint" && goalDist <= 2.4)) {
      return drive(0, 0, 0);
    }

    if (Math.abs(goalErr) > 115) {
      return drive(0, sign(goalErr) * 0.72, 0);
    }

    const candidates = [
      -90, -75, -60, -45, -30, -20, -10, 0,
      10, 20, 30, 45, 60, 75, 90,
      clamp(goalErr, -95, 95)
    ];
    let bestAngle = clamp(goalErr, -90, 90);
    let bestCost = 1e30;
    let bestAhead = 1e9;
    const look = 7;

    for (let c = 0; c < candidates.length; c++) {
      const a = candidates[c];
      const ar = a * RAD;
      const ca = Math.cos(ar);
      const sa = Math.sin(ar);
      let cost = Math.pow(wrap(a - goalErr) / 36, 2) +
        0.0007 * Math.abs(wrap(a - num(mem.lastSteer, 0)));
      let ahead = 1e9;

      for (let i = 0; i < 9; i++) {
        if (mem.rayDisabled[i]) continue;
        const r0 = rays[i];
        if (!(r0 > 0.02) || r0 >= 14.75) continue;

        const r = Math.max(0.12, r0 - 0.32);
        const rr = rayAngles[i] * RAD;
        const ox = r * Math.cos(rr);
        const oy = r * Math.sin(rr);
        const along = ox * ca + oy * sa;
        if (along < -0.3 || along > look) continue;
        const lateral = Math.abs(-ox * sa + oy * ca);

        if (along > 0 && lateral < 1.45) ahead = Math.min(ahead, along);
        if (lateral < 1.45) {
          const clearance = 1.45 - lateral;
          cost += clearance * clearance *
            (1.2 + 6.5 / Math.max(0.35, along + 0.25));
        } else if (lateral < 2.2 && along > 0) {
          cost += 0.05 * Math.pow(2.2 - lateral, 2);
        }
      }

      const globalAngle = (headingTrue + a) * RAD;
      const nx = px + 7 * Math.cos(globalAngle);
      const ny = py + 7 * Math.sin(globalAngle);
      if (nx < 3) cost += 2.5 * Math.pow(3 - nx, 2);
      if (ny < 3) cost += 2.5 * Math.pow(3 - ny, 2);
      if (nx > mem.mapW - 3) cost += 2.5 * Math.pow(nx - (mem.mapW - 3), 2);
      if (ny > mem.mapH - 3) cost += 2.5 * Math.pow(ny - (mem.mapH - 3), 2);

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
        bestAhead = ahead;
      }
    }
    mem.lastSteer = bestAngle;

    let cruise = mode === "site" ? 0.34 :
                 mode === "return" ? 0.56 : 0.54;
    if (raysBlind) cruise = Math.min(cruise, 0.48);
    if (mem.bumpCount >= 4) cruise = Math.min(cruise, 0.42);
    if (now < num(mem.sandUntil, 0)) cruise = Math.min(cruise, 0.34);

    let speed = cruise;
    if (Math.abs(bestAngle) > 50) {
      speed = 0;
    } else if (Math.abs(bestAngle) > 28) {
      speed *= 0.55;
    }

    if (mode === "site") {
      if (goalDist < 6) {
        speed = Math.min(speed, clamp((goalDist - 1.0) * 0.34, 0, 0.34));
      }
      if (goalDist <= 1.0) speed = 0;
    } else if (mode === "return") {
      if (goalDist < 12) {
        speed = Math.min(speed, Math.max(0, 0.10 + 0.15 * (goalDist - 2.25)));
      }
      if (goalDist <= 2.25) speed = 0;
    } else {
      if (goalDist < 10) {
        speed = Math.min(
          speed,
          Math.sqrt(Math.max(0, goalDist - 2.4) * 0.20)
        );
      }
      if (goalDist <= 2.4) speed = 0;
    }

    if (bestAhead < 1.2) speed = 0;
    else if (bestAhead < 2.0) speed = Math.min(speed, 0.12);
    else if (bestAhead < 3.0) speed = Math.min(speed, 0.22);
    else if (bestAhead < 4.2) speed = Math.min(speed, 0.34);

    const travelAngle = (headingTrue + bestAngle) * RAD;
    const dx = Math.cos(travelAngle);
    const dy = Math.sin(travelAngle);
    if ((px < 5 && dx < 0) || (py < 5 && dy < 0) ||
        (px > mem.mapW - 5 && dx > 0) ||
        (py > mem.mapH - 5 && dy > 0)) {
      speed = Math.min(speed, 0.20);
    } else if ((px < 10 && dx < 0) || (py < 10 && dy < 0) ||
               (px > mem.mapW - 10 && dx > 0) ||
               (py > mem.mapH - 10 && dy > 0)) {
      speed = Math.min(speed, 0.34);
    }

    const omega = clamp(2.1 * bestAngle * RAD, -0.78, 0.78);
    return drive(speed, omega, 0);
  }

  function goHome() {
    if (docked || baseDistance <= 2.25) return stopOutput();

    let err;
    if (beacon && beaconDistance !== null && finite(beacon.bearing)) {
      err = num(beacon.bearing, 0);
    } else {
      const bearing = Math.atan2(mem.baseY - py, mem.baseX - px) / RAD;
      err = wrap(bearing - headingTrue);
    }
    return navigation(err, baseDistance, "return", "home");
  }

  function startReturn() {
    mem.returning = true;
    mem.sampling = false;
    mem.stillTicks = 0;
    mem.holdI = 0;
    mem.task = null;
    mem.search = null;
    mem.resumeTask = null;
    mem.navKey = "";
  }

  function canBeginSample() {
    if (carried >= mem.capacity) return false;
    if (docked) return battery > 0.08 && timeLeft > 7;
    if (battery < returnEnergy(baseDistance, carried + 1) + 0.06) return false;
    if (timeLeft < returnTime(baseDistance) + 12) return false;
    return true;
  }

  function beginSampling() {
    mem.sampling = true;
    mem.sampleX = px;
    mem.sampleY = py;
    mem.sampleSiteX = finite(siteGX) ? siteGX : null;
    mem.sampleSiteY = finite(siteGY) ? siteGY : null;
    mem.sampleStart = now;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }

  function sampleOutput() {
    if (!mem.sampling) return null;

    const progress = Math.max(0, num(obs.drilling, 0));
    let range = 99;
    let matchingSite = false;

    if (siteVisible && finite(mem.sampleSiteX) && finite(mem.sampleSiteY)) {
      matchingSite = dist(
        siteGX, siteGY,
        Number(mem.sampleSiteX), Number(mem.sampleSiteY)
      ) < 5.0;
    }

    if (siteVisible && matchingSite) {
      range = siteDistance;
      mem.sampleSiteX = 0.70 * Number(mem.sampleSiteX) + 0.30 * siteGX;
      mem.sampleSiteY = 0.70 * Number(mem.sampleSiteY) + 0.30 * siteGY;
    } else if (finite(mem.sampleSiteX) && finite(mem.sampleSiteY)) {
      range = dist(px, py, Number(mem.sampleSiteX), Number(mem.sampleSiteY));
    } else {
      range = dist(px, py, num(mem.sampleX, px), num(mem.sampleY, py));
    }

    if (!docked && progress < 5.8 &&
        battery < returnEnergy(baseDistance, carried + 1) + 0.025) {
      startReturn();
      return null;
    }
    if (!docked && progress < 5.8 &&
        timeLeft < returnTime(baseDistance) + 7) {
      startReturn();
      return null;
    }

    if (range > 1.43) {
      if (siteVisible && matchingSite) {
        return navigation(siteBearing, siteDistance, "site", "sample-approach");
      }
      if (finite(mem.sampleSiteX) && finite(mem.sampleSiteY)) {
        const bearing = Math.atan2(
          Number(mem.sampleSiteY) - py,
          Number(mem.sampleSiteX) - px
        ) / RAD;
        return navigation(
          wrap(bearing - headingTrue),
          range,
          "site",
          "sample-approach"
        );
      }
      mem.sampling = false;
      mem.stillTicks = 0;
      return null;
    }

    const slow = Math.abs(wl) < 0.14 && Math.abs(wr) < 0.14;
    if (slow) mem.stillTicks = (mem.stillTicks || 0) + 1;
    else mem.stillTicks = 0;

    const ex = num(mem.sampleX, px) - px;
    const ey = num(mem.sampleY, py) - py;
    const along = ex * Math.cos(headingTrue * RAD) +
                  ey * Math.sin(headingTrue * RAD);
    const holdSpeed = clamp(
      0.40 * along - 0.34 * wheelAvg,
      -0.11,
      0.11
    );
    const holdBias = clamp(0.0035 * clamp(pitch, -18, 18), -0.08, 0.08);
    const cmd = drive(holdSpeed, 0, holdBias);
    const drill = range <= 1.43 && slow && mem.stillTicks >= 2;
    return { left: cmd.left, right: cmd.right, drill: !!drill };
  }

  function searchLength(task) {
    if (!task) return 150;
    if (task.kind === "grid") return 95;
    return 160;
  }

  function candidatePlan(task) {
    const d1 = dist(px, py, task.x, task.y);
    const d2 = dist(task.x, task.y, mem.baseX, mem.baseY);
    const route = d1 + d2 + searchLength(task);
    const energy = routeEnergy(route, carried + 1);
    const speed = Math.max(0.28, num(mem.vEst, 0.48) * 0.72);
    const time = route / speed + 32;
    return { d1: d1, d2: d2, route: route, energy: energy, time: time };
  }

  function chooseTask() {
    if (carried >= mem.capacity) return null;

    let best = null;
    let bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0) continue;
      const task = {
        kind: "hint",
        index: i,
        x: h.x,
        y: h.y,
        key: "h:" + i,
        phase: "travel",
        value: h.value
      };
      const p = candidatePlan(task);
      if (p.energy > battery - 0.035 || p.time > timeLeft - 8) continue;

      let cost;
      if (carried > 0) {
        const detour = Math.max(0, p.d1 + p.d2 - baseDistance);
        cost = 22 + 0.55 * p.d1 + detour + 0.34 * searchLength(task);
      } else {
        cost = 28 + p.d1 + 0.68 * p.d2 + 0.40 * searchLength(task);
      }
      const score = Math.max(0.15, h.value) /
        Math.pow(Math.max(1, cost), 0.90);
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    if (best) return best;

    let gridBest = null;
    let gridBestScore = -1;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (!g || mem.gridVisited[g.key]) continue;
      const task = {
        kind: "grid",
        index: i,
        x: g.x,
        y: g.y,
        key: g.key,
        phase: "travel",
        value: 0.25
      };
      const p = candidatePlan(task);
      if (p.energy > battery - 0.035 || p.time > timeLeft - 8) continue;

      const cost = 32 + p.d1 + 0.62 * p.d2 + 0.36 * searchLength(task);
      const score = 0.25 / Math.pow(Math.max(1, cost), 0.82);
      if (score > gridBestScore) {
        gridBestScore = score;
        gridBest = task;
      }
    }
    return gridBest;
  }

  function makeRing(cx, cy, radius, count, startX, startY) {
    const pts = [];
    for (let i = 0; i < count; i++) {
      const a = 2 * PI * i / count;
      const x = clamp(cx + radius * Math.cos(a), 4, mem.mapW - 4);
      const y = clamp(cy + radius * Math.sin(a), 4, mem.mapH - 4);
      let duplicate = false;
      for (let j = 0; j < pts.length; j++) {
        if (dist(x, y, pts[j].x, pts[j].y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) pts.push({ x: x, y: y });
    }

    if (pts.length <= 1) return pts;
    let nearest = 0;
    let nearestD = 1e30;
    for (let i = 0; i < pts.length; i++) {
      const d = dist(startX, startY, pts[i].x, pts[i].y);
      if (d < nearestD) {
        nearestD = d;
        nearest = i;
      }
    }
    return pts.slice(nearest).concat(pts.slice(0, nearest));
  }

  function buildSearchPoints(cx, cy, startX, startY) {
    const points = [{ x: cx, y: cy }];
    let lastX = cx;
    let lastY = cy;

    const inner = makeRing(cx, cy, 8, 8, startX, startY);
    for (let i = 0; i < inner.length; i++) {
      const p = inner[i];
      if (dist(p.x, p.y, lastX, lastY) > 1) points.push(p);
      lastX = p.x;
      lastY = p.y;
    }

    const outer = makeRing(cx, cy, 16, 16, lastX, lastY);
    for (let i = 0; i < outer.length; i++) {
      const p = outer[i];
      if (dist(p.x, p.y, lastX, lastY) > 1) points.push(p);
      lastX = p.x;
      lastY = p.y;
    }
    return points;
  }

  function buildRefinePoints(cx, cy, startX, startY) {
    const points = [{ x: cx, y: cy }];
    const ring = makeRing(cx, cy, 7, 8, startX, startY);
    for (let i = 0; i < ring.length; i++) {
      if (dist(ring[i].x, ring[i].y, cx, cy) > 1) points.push(ring[i]);
    }
    return points;
  }

  function startSearch(task) {
    if (!task) return;
    const points = buildSearchPoints(task.x, task.y, px, py);
    if (!points.length) {
      finishTask();
      return;
    }
    task.phase = "scan";
    mem.search = {
      key: task.key,
      cx: task.x,
      cy: task.y,
      points: points,
      idx: 0,
      level: 0,
      centerScience: science,
      bestScience: science,
      bestX: px,
      bestY: py,
      pointStart: now,
      pointBest: 1e9,
      arriveAt: null,
      maxUntil: now + (task.kind === "hint" ? 500 : 360),
      sampled: false
    };
    mem.navKey = "";
  }

  function restoreResumeTask() {
    const resume = mem.resumeTask;
    mem.resumeTask = null;
    if (resume) mem.task = resume;
  }

  function finishTask() {
    const task = mem.task;
    if (task) {
      if (task.kind === "hint" &&
          task.index >= 0 && task.index < mem.hints.length &&
          mem.hints[task.index].status === 0) {
        mem.hints[task.index].status = 2;
      } else if (task.kind === "grid") {
        mem.gridVisited[task.key] = true;
      }
      if (task.kind === "local") {
        mem.lastLocalX = task.x;
        mem.lastLocalY = task.y;
        mem.lastLocalT = now;
        mem.localCooldown = now + 45;
      }
    }
    mem.search = null;
    mem.task = null;
    mem.navKey = "";
    if (task && task.kind === "local") restoreResumeTask();
  }

  function updateSearch() {
    const s = mem.search;
    if (!s) return false;

    if (now > num(s.maxUntil, now + 1) ||
        !s.points || !s.points.length) {
      finishTask();
      return false;
    }

    if (science > num(s.bestScience, 0)) {
      s.bestScience = science;
      s.bestX = px;
      s.bestY = py;
    }

    if (s.idx < s.points.length) {
      const q = s.points[s.idx];
      const d = dist(px, py, q.x, q.y);
      if (d < 3.0) {
        if (s.arriveAt === null) s.arriveAt = now;
        if (now - num(s.arriveAt, now) >= 0.35) {
          s.idx++;
          s.arriveAt = null;
          s.pointStart = now;
          s.pointBest = 1e9;
        }
      } else {
        s.arriveAt = null;
        if (d < num(s.pointBest, 1e9) - 0.45) {
          s.pointBest = d;
          s.pointStart = now;
        } else if (s.pointBest > 1e8) {
          s.pointBest = d;
          s.pointStart = now;
        }
        if (now - num(s.pointStart, now) > 58) {
          s.idx++;
          s.pointStart = now;
          s.pointBest = 1e9;
        }
      }
    }

    if (s.idx >= s.points.length) {
      const gain = s.bestScience - s.centerScience;
      const threshold = Math.max(0.08, Math.abs(s.centerScience) * 0.18);
      if (s.level === 0 && gain > threshold) {
        s.cx = s.bestX;
        s.cy = s.bestY;
        s.centerScience = s.bestScience;
        s.level = 1;
        s.points = buildRefinePoints(s.cx, s.cy, px, py);
        s.idx = 0;
        s.pointStart = now;
        s.pointBest = 1e9;
        s.arriveAt = null;
        s.maxUntil = now + 150;
        mem.navKey = "";
      } else {
        finishTask();
        return false;
      }
    }
    return !!mem.search;
  }

  function taskRemainingRoute(task) {
    const s = mem.search;
    if (s && s.key === task.key && s.points && s.idx < s.points.length) {
      let x = px;
      let y = py;
      let route = 0;
      for (let j = s.idx; j < s.points.length; j++) {
        const q = s.points[j];
        route += dist(x, y, q.x, q.y);
        x = q.x;
        y = q.y;
      }

      if (task.kind === "local" && mem.resumeTask) {
        const r = mem.resumeTask;
        route += dist(x, y, r.x, r.y);
        route += dist(r.x, r.y, mem.baseX, mem.baseY);
        route += searchLength(r);
      } else {
        route += dist(x, y, mem.baseX, mem.baseY);
      }
      return route;
    }

    if (task.kind === "local" && mem.resumeTask) {
      const r = mem.resumeTask;
      return dist(px, py, task.x, task.y) +
        dist(task.x, task.y, r.x, r.y) +
        dist(r.x, r.y, mem.baseX, mem.baseY) +
        searchLength(r);
    }

    return dist(px, py, task.x, task.y) +
      searchLength(task) +
      dist(task.x, task.y, mem.baseX, mem.baseY);
  }

  function activePlan(task) {
    const route = taskRemainingRoute(task);
    const speed = Math.max(0.28, num(mem.vEst, 0.48) * 0.72);
    return {
      route: route,
      energy: routeEnergy(route, carried + 1),
      time: route / speed + 32
    };
  }

  function maybeStartSignalSearch() {
    if (mem.search || mem.sampling || mem.returning ||
        carried > 0 || now < num(mem.localCooldown, 0)) return;
    if (science < Math.max(0.22, num(mem.baseScience, 0) + 0.12)) return;
    if (science - num(mem.baseScience, 0) < 0.08) return;
    if (mem.task && mem.task.kind === "local") return;
    if (mem.task && dist(px, py, mem.task.x, mem.task.y) < 12) return;

    if (finite(mem.lastLocalX) && finite(mem.lastLocalY) &&
        now - num(mem.lastLocalT, -10000) < 190 &&
        dist(px, py, Number(mem.lastLocalX), Number(mem.lastLocalY)) < 20) {
      return;
    }

    mem.resumeTask = mem.task;
    const localTask = {
      kind: "local",
      index: -1,
      x: px,
      y: py,
      key: "local:" + Math.floor(now) + ":" + (mem.nextTaskId++),
      phase: "scan",
      value: 1
    };
    mem.task = localTask;
    mem.localCooldown = now + 45;
    mem.lastLocalX = px;
    mem.lastLocalY = py;
    mem.lastLocalT = now;
    startSearch(localTask);
  }

  if (justDelivered) {
    mem.returning = false;
  }

  if (docked) {
    mem.returning = false;
    if (carried > 0) return stopOutput();
  }

  if (mem.sampling) {
    const out = sampleOutput();
    if (out) return out;
    if (mem.returning && !docked) return goHome();
  }

  if (!docked && !mem.returning && !mem.sampling) {
    const homeNeed = returnEnergy(baseDistance, carried);
    if (carried >= mem.capacity ||
        battery < homeNeed + 0.09 ||
        timeLeft < returnTime(baseDistance) + (carried > 0 ? 12 : 8)) {
      startReturn();
    }
  }
  if (mem.returning && !docked) return goHome();

  if (siteVisible) {
    if (carried >= mem.capacity || !canBeginSample()) {
      if (!docked) {
        startReturn();
        return goHome();
      }
      return stopOutput();
    }

    if (!mem.sampling &&
        (siteDistance <= 1.08 ||
         (siteDistance <= 1.43 && wheelAbs < 0.13))) {
      beginSampling();
      const out = sampleOutput();
      if (out) return out;
    }

    return navigation(siteBearing, siteDistance, "site", "visible-site");
  }

  if (!mem.task) mem.task = chooseTask();
  if (!mem.search) maybeStartSignalSearch();

  for (let guard = 0; guard < 7; guard++) {
    if (!mem.task) mem.task = chooseTask();

    if (!mem.task) {
      if (docked) return stopOutput();
      startReturn();
      return goHome();
    }

    const task = mem.task;

    if (task.kind === "local" && !mem.search) {
      startSearch(task);
      if (!mem.search) continue;
    }

    if (task.phase === "scan") {
      updateSearch();
      if (!mem.task || mem.task !== task || !mem.search) continue;

      const plan = activePlan(task);
      if (plan.time > timeLeft - 5) {
        if (docked) {
          finishTask();
          continue;
        }
        startReturn();
        return goHome();
      }
      if (plan.energy > battery - 0.025) {
        if (docked) return stopOutput();
        startReturn();
        return goHome();
      }

      const s = mem.search;
      const q = s.points[s.idx];
      if (!q) {
        finishTask();
        continue;
      }
      const d = dist(px, py, q.x, q.y);
      const bearing = Math.atan2(q.y - py, q.x - px) / RAD;
      const key = "wp:" + s.key + ":" + s.level + ":" + s.idx;
      return navigation(wrap(bearing - headingTrue), d, "waypoint", key);
    }

    const d = dist(px, py, task.x, task.y);
    if (task.kind === "grid" && d < 4.0 &&
        science < Math.max(0.12, num(mem.baseScience, 0) + 0.02)) {
      finishTask();
      continue;
    }
    if (d < 4.0) {
      startSearch(task);
      continue;
    }

    const plan = activePlan(task);
    if (plan.time > timeLeft - 5) {
      if (docked) {
        finishTask();
        continue;
      }
      startReturn();
      return goHome();
    }
    if (plan.energy > battery - 0.025) {
      if (docked) return stopOutput();
      startReturn();
      return goHome();
    }

    const bearing = Math.atan2(task.y - py, task.x - px) / RAD;
    return navigation(
      wrap(bearing - headingTrue),
      d,
      "waypoint",
      "task:" + task.key
    );
  }

  if (docked) return stopOutput();
  startReturn();
  return goHome();
}

function act(obs, mem) {
  obs = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const PI = Math.PI;
  const RAD = PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const finite = (v) =>
    v !== null && v !== undefined && Number.isFinite(Number(v));
  const num = (v, fallback) => finite(v) ? Number(v) : fallback;
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const now = num(obs.t, num(mem.clock, 0));
  const rawX = num(obs.x, 200);
  const rawY = num(obs.y, 200);
  const headingRaw = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const wheelAvg = (wl + wr) * 0.5;
  const wheelAbs = (Math.abs(wl) + Math.abs(wr)) * 0.5;
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const battery = Math.max(0, num(obs.battery, 0));
  const solar = Math.max(0, num(obs.solar, 0));
  const carried = Math.max(0, num(obs.carried, 0));
  const carriedValue = Math.max(0, num(obs.carriedValue, 0));
  const delivered = Math.max(0, num(obs.delivered, 0));
  const science = Math.max(0, num(obs.science, 0));
  const pitch = num(obs.pitch, 0);

  if (!mem._v6) {
    const mission = obs.mission || {};
    const size = mission.size;
    let mapW = 400;
    let mapH = 400;

    if (typeof size === "number") {
      mapW = size;
      mapH = size;
    } else if (Array.isArray(size)) {
      mapW = num(size[0], 400);
      mapH = num(size[1], mapW);
    } else if (size && typeof size === "object") {
      mapW = num(size.width, num(size.x, 400));
      mapH = num(size.height, num(size.y, mapW));
    } else {
      mapW = num(mission.width, 400);
      mapH = num(mission.height, 400);
    }

    mapW = Math.max(20, mapW);
    mapH = Math.max(20, mapH);
    const base = mission.base || {};

    mem.mapW = mapW;
    mem.mapH = mapH;
    mem.baseX = num(base.x, mapW * 0.5);
    mem.baseY = num(base.y, mapH * 0.5);
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));

    mem.hints = [];
    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const x = num(h.x, NaN);
      const y = num(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      let value = num(h.estimate, num(h.value, 1));
      if (!(value > 0)) value = 0.15;
      mem.hints.push({
        x: clamp(x, 4, mapW - 4),
        y: clamp(y, 4, mapH - 4),
        value: value,
        status: 0
      });
    }

    mem.grid = [];
    let gi = 0;
    for (let x = 32; x <= mapW - 24; x += 55) {
      for (let y = 32; y <= mapH - 24; y += 55) {
        mem.grid.push({
          x: clamp(x, 4, mapW - 4),
          y: clamp(y, 4, mapH - 4),
          key: "g:" + gi++
        });
      }
    }

    mem.gridVisited = {};
    mem.task = null;
    mem.search = null;
    mem.nextTaskId = 1;
    mem.returning = false;

    mem.clock = now;
    mem._lastT = now;
    mem.headingOffset = 0;
    mem.lastHeadRaw = headingRaw;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.rawPrevX = rawX;
    mem.rawPrevY = rawY;
    mem.gpsFrozen = false;
    mem.gpsFreezeCount = 0;

    mem.calPrevX = rawX;
    mem.calPrevY = rawY;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;

    mem.speedEst = 0.36;
    mem.burn = 0.0012;
    mem.energyBucket = 0;
    mem.distanceBucket = 0;
    mem.prevBattery = battery;

    mem.lastCarried = carried;
    mem.lastCarriedValue = carriedValue;
    mem.lastDelivered = delivered;

    mem.sampling = false;
    mem.sampleX = rawX;
    mem.sampleY = rawY;
    mem.sampleSiteX = null;
    mem.sampleSiteY = null;
    mem.sampleHeading = headingRaw;
    mem.sampleStart = 0;
    mem.stillTicks = 0;
    mem.holdI = 0;
    mem.lastSampleX = null;
    mem.lastSampleY = null;
    mem.suppressSiteUntil = -1;

    mem.motorGain = [3, 3];
    mem.motorIntegral = [0, 0];
    mem.motorStall = [0, 0];
    mem.prevCmd = [0, 0];
    mem.prevTarget = [0, 0];

    mem.navKey = "";
    mem.navBestDist = 1e9;
    mem.navProgressT = now;
    mem.lastSteer = 0;
    mem.recoverUntil = 0;
    mem.recoverSign = 1;
    mem.lastBumped = false;
    mem.bumpCount = 0;

    mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayDisabled = [false, false, false, false, false, false, false, false, false];
    mem.rayTravel = 0;

    mem.baseScience = science;
    mem._v6 = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.grid)) mem.grid = [];
  if (!mem.gridVisited) mem.gridVisited = {};
  if (!Array.isArray(mem.motorGain)) mem.motorGain = [3, 3];
  if (!Array.isArray(mem.motorIntegral)) mem.motorIntegral = [0, 0];
  if (!Array.isArray(mem.motorStall)) mem.motorStall = [0, 0];
  if (!Array.isArray(mem.prevCmd)) mem.prevCmd = [0, 0];
  if (!Array.isArray(mem.prevTarget)) mem.prevTarget = [0, 0];
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  if (!Array.isArray(mem.rayDisabled)) mem.rayDisabled = [false, false, false, false, false, false, false, false, false];

  let dt = 0.1;
  const oldT = num(mem._lastT, now);
  if (now - oldT > 0.015 && now - oldT < 0.8) dt = now - oldT;
  mem._lastT = now;
  mem.clock = now;

  const oldPX = num(mem.posX, rawX);
  const oldPY = num(mem.posY, rawY);
  const rawPrevX = num(mem.rawPrevX, rawX);
  const rawPrevY = num(mem.rawPrevY, rawY);
  const rawStep = dist(rawX, rawY, rawPrevX, rawPrevY);

  let headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));
  const headingDelta = wrap(headingRaw - num(mem.lastHeadRaw, headingRaw));
  const expectedYaw = (wr - wl) / 0.6 * dt / RAD;
  const yawMismatch = wrap(headingDelta - expectedYaw);
  if (mem.lastHeadRaw !== undefined &&
      Math.abs(expectedYaw) < 25 &&
      Math.abs(yawMismatch) > 65) {
    mem.headingOffset = wrap(
      num(mem.headingOffset, 0) + clamp(yawMismatch, -150, 150)
    );
    headingTrue = wrap(headingRaw - mem.headingOffset);
  }
  mem.lastHeadRaw = headingRaw;

  if (!docked && !bumped && rawStep < 0.015 && wheelAbs > 0.28) {
    mem.gpsFreezeCount = (mem.gpsFreezeCount || 0) + 1;
  } else {
    mem.gpsFreezeCount = 0;
  }
  if (mem.gpsFreezeCount > 14) mem.gpsFrozen = true;

  if (mem.gpsFrozen) {
    if (rawStep > 0.45 && rawStep < 10 && !docked) {
      mem.gpsFrozen = false;
      mem.gpsFreezeCount = 0;
      mem.posX = rawX;
      mem.posY = rawY;
    } else if (!docked && !bumped && wheelAbs > 0.08) {
      const a = headingTrue * RAD;
      const odom = wheelAvg * dt * 0.68;
      mem.posX = oldPX + odom * Math.cos(a);
      mem.posY = oldPY + odom * Math.sin(a);
    }
  } else if (rawStep > 10 && !docked) {
    mem.posX = oldPX;
    mem.posY = oldPY;
  } else {
    const alpha = wheelAbs > 0.16 ? 0.38 : 0.18;
    mem.posX = oldPX + alpha * (rawX - oldPX);
    mem.posY = oldPY + alpha * (rawY - oldPY);
  }
  mem.rawPrevX = rawX;
  mem.rawPrevY = rawY;

  let px = num(mem.posX, rawX);
  let py = num(mem.posY, rawY);
  let stepX = px - oldPX;
  let stepY = py - oldPY;
  let stepDist = Math.hypot(stepX, stepY);

  const calDX = rawX - num(mem.calPrevX, rawX);
  const calDY = rawY - num(mem.calPrevY, rawY);
  if (!docked && !mem.gpsFrozen && wheelAvg > 0.20 &&
      Math.abs(wr - wl) < 0.13 && rawStep > 0.015 && rawStep < 1.3) {
    mem.calDX = num(mem.calDX, 0) + calDX;
    mem.calDY = num(mem.calDY, 0) + calDY;
    mem.calSin = num(mem.calSin, 0) + Math.sin(headingRaw * RAD) * rawStep;
    mem.calCos = num(mem.calCos, 0) + Math.cos(headingRaw * RAD) * rawStep;
    mem.calN = (mem.calN || 0) + 1;

    if (Math.hypot(mem.calDX, mem.calDY) > 5.5 &&
        mem.calN > 16 &&
        Math.hypot(mem.calSin, mem.calCos) > 2.5) {
      const track = Math.atan2(mem.calDY, mem.calDX) / RAD;
      const avgRaw = Math.atan2(mem.calSin, mem.calCos) / RAD;
      const measured = wrap(avgRaw - track);
      const error = wrap(measured - num(mem.headingOffset, 0));
      if (Math.abs(error) < 50) {
        mem.headingOffset = wrap(
          num(mem.headingOffset, 0) + clamp(error * 0.12, -4, 4)
        );
      }
      mem.calDX = 0;
      mem.calDY = 0;
      mem.calSin = 0;
      mem.calCos = 0;
      mem.calN = 0;
    }
  } else {
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;
  }
  mem.calPrevX = rawX;
  mem.calPrevY = rawY;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  const groundSpeed = stepDist / Math.max(0.04, dt);
  if (!docked && !mem.gpsFrozen && wheelAbs > 0.18 &&
      rawStep > 0.025 && rawStep < 1.5 &&
      groundSpeed > 0.10 && groundSpeed < 1.5) {
    mem.speedEst = 0.94 * num(mem.speedEst, 0.36) +
      0.06 * clamp(groundSpeed, 0.22, 0.85);
  }
  mem.speedEst = clamp(num(mem.speedEst, 0.36), 0.22, 0.85);

  const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const hasRays = !!(obs.rays && typeof obs.rays.length === "number");
  const rays = [];
  let disabledCount = 0;

  for (let i = 0; i < 9; i++) {
    const r = clamp(num(hasRays ? obs.rays[i] : 15, 15), 0, 15);
    rays.push(r);
    if (Math.abs(r - num(mem.rayLast[i], 15)) < 0.025) {
      mem.rayStale[i] = (mem.rayStale[i] || 0) + 1;
    } else {
      mem.rayStale[i] = 0;
      if (mem.rayDisabled[i] &&
          Math.abs(r - num(mem.rayLast[i], r)) > 0.5) {
        mem.rayDisabled[i] = false;
      }
    }
    mem.rayLast[i] = r;
  }

  mem.rayTravel = num(mem.rayTravel, 0) + stepDist;
  if (mem.rayTravel > 18) {
    for (let i = 0; i < 9; i++) {
      if (mem.rayStale[i] > 280 && rays[i] < 14.7) {
        mem.rayDisabled[i] = true;
      }
    }
    mem.rayTravel = 0;
  }
  for (let i = 0; i < 9; i++) {
    if (mem.rayDisabled[i]) disabledCount++;
  }
  const raysBlind = !hasRays || disabledCount >= 7;

  if (bumped && !mem.lastBumped) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.35, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) < 0.02) {
      mem.recoverSign = -num(mem.recoverSign, 1);
      if (!mem.recoverSign) mem.recoverSign = 1;
    } else {
      mem.recoverSign = rightDanger > leftDanger ? 1 : -1;
    }
    mem.recoverUntil = now + 1.0;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
  }
  mem.lastBumped = bumped;

  const oldBattery = num(mem.prevBattery, battery);
  const db = oldBattery - battery;
  if (db > 0.06 && stepDist < 1.0) {
    mem.burn = clamp(num(mem.burn, 0.0012) * 1.18, 0.00045, 0.006);
  }
  if (!docked && wheelAbs > 0.10 && stepDist > 0.025 &&
      Math.abs(db) < 0.08) {
    mem.energyBucket = num(mem.energyBucket, 0) +
      Math.max(0, db + solar * dt * 0.08);
    mem.distanceBucket = num(mem.distanceBucket, 0) + stepDist;
    if (mem.distanceBucket >= 10) {
      const measured = mem.energyBucket / Math.max(1, mem.distanceBucket);
      if (measured > 0.00015 && measured < 0.009) {
        const oldBurn = num(mem.burn, 0.0012);
        const alpha = measured > oldBurn ? 0.18 : 0.06;
        mem.burn = clamp(oldBurn + alpha * (measured - oldBurn),
                         0.00045, 0.006);
      }
      mem.energyBucket = 0;
      mem.distanceBucket = 0;
    }
  }
  mem.prevBattery = battery;

  for (let i = 0; i < 2; i++) {
    const actual = i === 0 ? wl : wr;
    const previousCmd = num(mem.prevCmd[i], 0);
    const previousTarget = num(mem.prevTarget[i], 0);
    if (Math.abs(previousCmd) > 0.10 &&
        Math.abs(previousTarget) > 0.09 &&
        actual * previousTarget > 0 &&
        Math.abs(actual) > 0.07) {
      const ratio = Math.abs(actual / previousCmd);
      if (ratio > 0.5 && ratio < 8) {
        mem.motorGain[i] = clamp(
          0.98 * num(mem.motorGain[i], 3) + 0.02 * ratio,
          1.2, 6.5
        );
      }
    }
  }

  const timeLeft = Math.max(0, num(obs.timeLeft, mem.totalSeconds - now));

  let siteVisible = false;
  let siteDistance = 99;
  let siteBearing = 0;
  let siteGX = NaN;
  let siteGY = NaN;
  const siteObs = obs.site;
  if (siteObs && finite(siteObs.distance)) {
    siteDistance = clamp(num(siteObs.distance, 99), 0, 12);
    siteBearing = wrap(num(siteObs.bearing, 0));
    const a = (headingTrue + siteBearing) * RAD;
    siteGX = px + siteDistance * Math.cos(a);
    siteGY = py + siteDistance * Math.sin(a);
    siteVisible = siteDistance <= 8.5;
  }

  const oldCarried = num(mem.lastCarried, carried);
  const oldCarriedValue = num(mem.lastCarriedValue, carriedValue);
  const oldDelivered = num(mem.lastDelivered, delivered);
  const justSampled = carried > oldCarried + 0.01 ||
                      carriedValue > oldCarriedValue + 0.01;
  const justDelivered = delivered > oldDelivered + 0.01 ||
                        (docked && carried < oldCarried - 0.01);

  if (justSampled) {
    const sx = finite(mem.sampleSiteX) ? Number(mem.sampleSiteX) :
               (Number.isFinite(siteGX) ? siteGX : px);
    const sy = finite(mem.sampleSiteY) ? Number(mem.sampleSiteY) :
               (Number.isFinite(siteGY) ? siteGY : py);
    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.suppressSiteUntil = now + 0.7;

    for (let i = 0; i < mem.hints.length; i++) {
      if (dist(sx, sy, mem.hints[i].x, mem.hints[i].y) < 9) {
        mem.hints[i].status = 1;
      }
    }

    const task = mem.task;
    if (task) {
      let linked = false;
      if (task.kind === "hint") {
        linked = !!(mem.search && mem.search.key === task.key) ||
          dist(sx, sy, task.x, task.y) < 30;
        if (linked && task.index >= 0 && task.index < mem.hints.length) {
          mem.hints[task.index].status = 1;
        }
      } else if (task.kind === "grid") {
        linked = !!(mem.search && mem.search.key === task.key) ||
          dist(sx, sy, task.x, task.y) < 12;
        if (linked) mem.gridVisited[task.key] = true;
      }
      if (linked) {
        mem.task = null;
        mem.search = null;
        mem.navKey = "";
      }
    }

    mem.sampling = false;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }

  if (justDelivered) {
    mem.returning = false;
    mem.sampling = false;
    mem.task = null;
    mem.search = null;
    mem.navKey = "";
  }

  if (siteVisible && now < num(mem.suppressSiteUntil, -1) &&
      finite(mem.lastSampleX) && finite(mem.lastSampleY) &&
      dist(siteGX, siteGY, Number(mem.lastSampleX),
           Number(mem.lastSampleY)) < 2.5) {
    siteVisible = false;
  }

  mem.lastCarried = carried;
  mem.lastCarriedValue = carriedValue;
  mem.lastDelivered = delivered;

  const beacon = obs.beacon;
  let beaconDistance = null;
  if (beacon && finite(beacon.distance) &&
      Number(beacon.distance) <= 25) {
    beaconDistance = clamp(num(beacon.distance, 100), 0, 100);
  }
  const gpsBaseDistance = dist(px, py, mem.baseX, mem.baseY);
  const baseDistance = docked ? 0 :
    (beaconDistance !== null ? beaconDistance : gpsBaseDistance);

  function effectiveSpeed() {
    return clamp(num(mem.speedEst, 0.36) * 0.78, 0.24, 0.52);
  }

  function energyNeed(d, n) {
    const count = Math.max(0, n);
    const route = Math.max(0, d) * 1.46 + 8;
    return route * num(mem.burn, 0.0012) *
      (1 + 0.20 * count) + 0.14 + 0.035 * count;
  }

  function returnTime(d) {
    return Math.max(0, d) / effectiveSpeed() + 30;
  }

  function motorCommand(i, target, actual, bias) {
    target = clamp(target, -0.56, 0.56);
    bias = clamp(num(bias, 0), -0.12, 0.12);

    let integral = num(mem.motorIntegral[i], 0);
    const oldTarget = num(mem.prevTarget[i], 0);
    if (target * oldTarget < -0.02) {
      integral = 0;
      mem.motorStall[i] = 0;
    }

    let command;
    if (Math.abs(target) < 0.025) {
      integral *= 0.2;
      command = -0.38 * actual + bias;
      if (Math.abs(actual) < 0.035 && Math.abs(bias) < 0.008) command = 0;
    } else {
      const error = target - actual;
      integral = clamp(integral + 0.055 * error * dt, -0.12, 0.12);
      command = target / Math.max(1.2, num(mem.motorGain[i], 3)) +
        0.20 * error + integral + bias;

      if (Math.abs(target) > 0.035 && Math.abs(actual) < 0.05) {
        mem.motorStall[i] = (mem.motorStall[i] || 0) + 1;
        if (mem.motorStall[i] > 4 && Math.abs(command) < 0.075) {
          command = Math.sign(target) * 0.075;
        }
      } else {
        mem.motorStall[i] = Math.max(0, (mem.motorStall[i] || 0) - 1);
      }
    }

    mem.motorIntegral[i] = integral;
    return clamp(command, -0.70, 0.70);
  }

  function drive(v, omega, holdBias) {
    let leftTarget = v - omega * 0.30;
    let rightTarget = v + omega * 0.30;
    const maxWheel = Math.max(Math.abs(leftTarget), Math.abs(rightTarget));
    if (maxWheel > 0.56) {
      const scale = 0.56 / maxWheel;
      leftTarget *= scale;
      rightTarget *= scale;
    }

    const bias = clamp(num(holdBias, 0), -0.12, 0.12);
    const left = motorCommand(0, leftTarget, wl, bias);
    const right = motorCommand(1, rightTarget, wr, bias);

    mem.prevTarget[0] = leftTarget;
    mem.prevTarget[1] = rightTarget;
    mem.prevCmd[0] = left;
    mem.prevCmd[1] = right;
    return { left: left, right: right, drill: false };
  }

  function stopOutput() {
    return drive(0, 0, 0);
  }

  function dangerTurn(goalErr) {
    let rightDanger = 0;
    let leftDanger = 0;
    for (let i = 0; i < 9; i++) {
      if (mem.rayDisabled[i]) continue;
      const q = 1 / Math.max(0.35, rays[i]);
      if (rayAngles[i] < 0) rightDanger += q;
      else if (rayAngles[i] > 0) leftDanger += q;
    }
    if (Math.abs(rightDanger - leftDanger) > 0.02) {
      return rightDanger > leftDanger ? 1 : -1;
    }
    if (Math.abs(goalErr) > 8) return Math.sign(goalErr);
    mem.recoverSign = -num(mem.recoverSign, 1);
    if (!mem.recoverSign) mem.recoverSign = 1;
    return mem.recoverSign;
  }

  function navigation(goalErr, goalDist, mode, key, stopAt) {
    goalErr = wrap(goalErr);
    goalDist = Math.max(0, num(goalDist, 0));
    stopAt = Math.max(0, num(stopAt, 1.8));

    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    } else if (goalDist < num(mem.navBestDist, 1e9) - 0.45) {
      mem.navBestDist = goalDist;
      mem.navProgressT = now;
    }

    if (bumped && now < num(mem.recoverUntil, 0)) {
      const s = num(mem.recoverSign, 1) || 1;
      return drive(-0.14, s * 0.42, 0);
    }

    if (goalDist > 4 &&
        now - num(mem.navProgressT, now) > 28 &&
        now >= num(mem.recoverUntil, 0)) {
      mem.recoverSign = dangerTurn(goalErr);
      mem.recoverUntil = now + 1.0;
      mem.navProgressT = now;
      mem.navBestDist = goalDist;
      return drive(-0.14, mem.recoverSign * 0.42, 0);
    }

    if (now < num(mem.recoverUntil, 0)) {
      const s = num(mem.recoverSign, 1) || 1;
      return drive(-0.14, s * 0.42, 0);
    }

    if (goalDist <= stopAt) return drive(0, 0, 0);

    if (Math.abs(goalErr) > 120) {
      return drive(0, Math.sign(goalErr) * 0.55, 0);
    }

    const candidates = [
      -85, -70, -55, -40, -25, -12, 0,
       12,  25,  40,  55,  70, 85,
      clamp(goalErr, -90, 90)
    ];
    let bestAngle = clamp(goalErr, -90, 90);
    let bestCost = 1e30;
    let bestAhead = 1e9;
    const look = 6.0;

    for (let c = 0; c < candidates.length; c++) {
      const a = candidates[c];
      const ar = a * RAD;
      const ca = Math.cos(ar);
      const sa = Math.sin(ar);
      let cost = Math.pow(wrap(a - goalErr) / 32, 2) +
        0.0005 * Math.abs(wrap(a - num(mem.lastSteer, 0)));
      let ahead = 1e9;

      for (let i = 0; i < 9; i++) {
        if (mem.rayDisabled[i]) continue;
        const r0 = rays[i];
        if (!(r0 > 0.02) || r0 >= 14.75) continue;

        const r = Math.max(0.12, r0 - 0.35);
        const rr = rayAngles[i] * RAD;
        const ox = r * Math.cos(rr);
        const oy = r * Math.sin(rr);
        const along = ox * ca + oy * sa;
        if (along < -0.25 || along > look) continue;
        const lateral = Math.abs(-ox * sa + oy * ca);

        if (along > 0 && lateral < 1.45) {
          ahead = Math.min(ahead, along);
          const clearance = 1.45 - lateral;
          cost += clearance * clearance *
            (2.0 + 9.0 / Math.max(0.35, along));
        } else if (along > 0 && lateral < 2.2) {
          cost += 0.045 * Math.pow(2.2 - lateral, 2);
        }
      }

      const globalAngle = (headingTrue + a) * RAD;
      const nx = px + 5.5 * Math.cos(globalAngle);
      const ny = py + 5.5 * Math.sin(globalAngle);
      if (nx < 3) cost += 1.5 * Math.pow(3 - nx, 2);
      if (ny < 3) cost += 1.5 * Math.pow(3 - ny, 2);
      if (nx > mem.mapW - 3) cost += 1.5 * Math.pow(nx - (mem.mapW - 3), 2);
      if (ny > mem.mapH - 3) cost += 1.5 * Math.pow(ny - (mem.mapH - 3), 2);

      if (cost < bestCost) {
        bestCost = cost;
        bestAngle = a;
        bestAhead = ahead;
      }
    }
    mem.lastSteer = bestAngle;

    let speed = mode === "site" ? 0.24 :
                mode === "return" ? 0.36 : 0.34;
    if (raysBlind) speed = Math.min(speed, 0.28);
    if (mem.bumpCount >= 5) speed = Math.min(speed, 0.30);

    if (Math.abs(bestAngle) > 60) {
      speed = 0;
    } else if (Math.abs(bestAngle) > 35) {
      speed = Math.min(speed, 0.10);
    } else if (Math.abs(bestAngle) > 20) {
      speed = Math.min(speed, 0.18);
    }

    const remaining = Math.max(0, goalDist - stopAt);
    speed = Math.min(speed, Math.sqrt(remaining * 0.20));

    if (bestAhead < 0.9) speed = 0;
    else if (bestAhead < 1.6) speed = Math.min(speed, 0.10);
    else if (bestAhead < 2.5) speed = Math.min(speed, 0.18);
    else if (bestAhead < 3.7) speed = Math.min(speed, 0.27);

    const travelAngle = (headingTrue + bestAngle) * RAD;
    const dx = Math.cos(travelAngle);
    const dy = Math.sin(travelAngle);
    if ((px < 5 && dx < 0) || (py < 5 && dy < 0) ||
        (px > mem.mapW - 5 && dx > 0) ||
        (py > mem.mapH - 5 && dy > 0)) {
      speed = Math.min(speed, 0.12);
    } else if ((px < 10 && dx < 0) || (py < 10 && dy < 0) ||
               (px > mem.mapW - 10 && dx > 0) ||
               (py > mem.mapH - 10 && dy > 0)) {
      speed = Math.min(speed, 0.24);
    }

    const omega = clamp(1.25 * bestAngle * RAD, -0.68, 0.68);
    return drive(speed, omega, 0);
  }

  function goHome() {
    if (docked || baseDistance <= 1.25) return stopOutput();

    let err;
    if (beacon && beaconDistance !== null && finite(beacon.bearing)) {
      err = num(beacon.bearing, 0);
    } else {
      const bearing = Math.atan2(mem.baseY - py, mem.baseX - px) / RAD;
      err = wrap(bearing - headingTrue);
    }
    return navigation(err, baseDistance, "return", "home", 1.25);
  }

  function startReturn() {
    mem.returning = true;
    mem.sampling = false;
    mem.stillTicks = 0;
    mem.holdI = 0;
    mem.task = null;
    mem.search = null;
    mem.navKey = "";
  }

  function canStartSample() {
    if (carried >= mem.capacity) return false;
    if (docked) return battery > 0.05 && timeLeft > 7;
    if (battery < energyNeed(baseDistance, carried + 1) + 0.10) return false;
    if (timeLeft < returnTime(baseDistance) + 16) return false;
    return true;
  }

  function beginSampling() {
    mem.sampling = true;
    mem.sampleX = px;
    mem.sampleY = py;
    mem.sampleSiteX = Number.isFinite(siteGX) ? siteGX : null;
    mem.sampleSiteY = Number.isFinite(siteGY) ? siteGY : null;
    mem.sampleHeading = headingTrue;
    mem.sampleStart = now;
    mem.stillTicks = 0;
    mem.holdI = 0;
  }

  function sampleOutput() {
    if (!mem.sampling) return null;

    const progress = Math.max(0, num(obs.drilling, 0));
    if (!docked && progress < 5.8 &&
        (battery < energyNeed(baseDistance, carried + 1) + 0.025 ||
         timeLeft < returnTime(baseDistance) + 8)) {
      startReturn();
      return null;
    }

    let range = 99;
    if (siteVisible) {
      range = siteDistance;
      if (Number.isFinite(siteGX) && Number.isFinite(siteGY)) {
        if (!finite(mem.sampleSiteX) || !finite(mem.sampleSiteY)) {
          mem.sampleSiteX = siteGX;
          mem.sampleSiteY = siteGY;
        } else if (dist(siteGX, siteGY,
                        Number(mem.sampleSiteX), Number(mem.sampleSiteY)) < 6) {
          mem.sampleSiteX = 0.75 * Number(mem.sampleSiteX) + 0.25 * siteGX;
          mem.sampleSiteY = 0.75 * Number(mem.sampleSiteY) + 0.25 * siteGY;
        }
      }
    } else if (finite(mem.sampleSiteX) && finite(mem.sampleSiteY)) {
      range = dist(px, py, Number(mem.sampleSiteX), Number(mem.sampleSiteY));
    }

    if (range > 1.45) {
      if (siteVisible) {
        return navigation(siteBearing, siteDistance, "site",
                          "sample-approach", 0.70);
      }
      if (finite(mem.sampleSiteX) && finite(mem.sampleSiteY)) {
        const bearing = Math.atan2(
          Number(mem.sampleSiteY) - py,
          Number(mem.sampleSiteX) - px
        ) / RAD;
        return navigation(wrap(bearing - headingTrue), range, "site",
                          "sample-approach", 0.70);
      }
      const idle = drive(0, 0, 0);
      return { left: idle.left, right: idle.right, drill: false };
    }

    const anchorX = num(mem.sampleX, px);
    const anchorY = num(mem.sampleY, py);
    const sh = num(mem.sampleHeading, headingTrue) * RAD;
    const along = (anchorX - px) * Math.cos(sh) +
                  (anchorY - py) * Math.sin(sh);
    const holdSpeed = clamp(
      0.45 * along - 0.55 * wheelAvg,
      -0.11, 0.11
    );
    const holdBias = clamp(0.0028 * clamp(pitch, -22, 22), -0.08, 0.08);
    const cmd = drive(holdSpeed, 0, holdBias);

    const slow = Math.abs(wl) < 0.12 && Math.abs(wr) < 0.12;
    if (slow) mem.stillTicks = (mem.stillTicks || 0) + 1;
    else mem.stillTicks = 0;

    const drill = range <= 1.45 &&
      slow && mem.stillTicks >= 2 &&
      Math.abs(holdSpeed) < 0.045;

    return { left: cmd.left, right: cmd.right, drill: !!drill };
  }

  function searchLength(task) {
    if (!task) return 100;
    return task.kind === "hint" ? 115 : 58;
  }

  function makeRing(cx, cy, radius, count, startX, startY) {
    const pts = [];
    for (let i = 0; i < count; i++) {
      const a = 2 * PI * i / count;
      const x = clamp(cx + radius * Math.cos(a), 4, mem.mapW - 4);
      const y = clamp(cy + radius * Math.sin(a), 4, mem.mapH - 4);
      let duplicate = false;
      for (let j = 0; j < pts.length; j++) {
        if (dist(x, y, pts[j].x, pts[j].y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) pts.push({ x: x, y: y });
    }

    if (pts.length <= 1) return pts;
    let nearest = 0;
    let nearestD = 1e30;
    for (let i = 0; i < pts.length; i++) {
      const d = dist(startX, startY, pts[i].x, pts[i].y);
      if (d < nearestD) {
        nearestD = d;
        nearest = i;
      }
    }
    return pts.slice(nearest).concat(pts.slice(0, nearest));
  }

  function taskValid(task) {
    if (!task) return false;
    if (task.kind === "hint") {
      return task.index >= 0 && task.index < mem.hints.length &&
        mem.hints[task.index].status === 0;
    }
    if (task.kind === "grid") return !mem.gridVisited[task.key];
    return false;
  }

  function candidatePlan(task, assumedSearch) {
    const d1 = dist(px, py, task.x, task.y);
    const d2 = dist(task.x, task.y, mem.baseX, mem.baseY);
    const route = d1 + d2 + assumedSearch;
    const time = route / effectiveSpeed() + 42;
    const energy = energyNeed(route, carried + 1);
    return { d1: d1, d2: d2, route: route, time: time, energy: energy };
  }

  function chooseTask() {
    if (carried >= mem.capacity) return null;

    let best = null;
    let bestScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0) continue;

      const task = {
        kind: "hint",
        index: i,
        x: h.x,
        y: h.y,
        key: "h:" + i,
        phase: 0,
        value: Math.max(0.15, h.value)
      };
      const p = candidatePlan(task, 90);
      if (p.energy > battery - 0.12 || p.time > timeLeft - 10) continue;

      let cost;
      if (carried > 0) {
        const detour = Math.max(0, p.d1 + p.d2 - baseDistance);
        cost = 24 + p.d1 + 0.82 * detour + 0.36 * 90;
      } else {
        cost = 28 + p.d1 + 0.66 * p.d2 + 0.36 * 90;
      }
      const score = task.value / Math.pow(Math.max(1, cost), 0.86);
      if (score > bestScore) {
        bestScore = score;
        best = task;
      }
    }
    if (best) return best;

    let gridBest = null;
    let gridScore = -1;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (!g || mem.gridVisited[g.key]) continue;

      const task = {
        kind: "grid",
        index: i,
        x: g.x,
        y: g.y,
        key: g.key,
        phase: 0,
        value: 0.28
      };
      const p = candidatePlan(task, 58);
      if (p.energy > battery - 0.12 || p.time > timeLeft - 10) continue;

      const cost = 32 + p.d1 + 0.65 * p.d2 + 0.35 * 58;
      const score = task.value / Math.pow(Math.max(1, cost), 0.82);
      if (score > gridScore) {
        gridScore = score;
        gridBest = task;
      }
    }
    return gridBest;
  }

  function startSearch(task) {
    if (!task) return;

    const points = [{ x: task.x, y: task.y }];
    const inner = makeRing(task.x, task.y, 8, 8, px, py);
    for (let i = 0; i < inner.length; i++) {
      let duplicate = false;
      for (let j = 0; j < points.length; j++) {
        if (dist(inner[i].x, inner[i].y,
                 points[j].x, points[j].y) < 2) {
          duplicate = true;
          break;
        }
      }
      if (!duplicate) points.push(inner[i]);
    }

    task.phase = 1;
    mem.search = {
      key: task.key,
      cx: task.x,
      cy: task.y,
      points: points,
      idx: 0,
      phase: 0,
      outerDone: false,
      refined: false,
      startScience: science,
      bestScience: science,
      bestX: px,
      bestY: py,
      arrival: null,
      pointStart: now,
      pointBest: 1e9
    };
    mem.navKey = "";
  }

  function finishTask() {
    const task = mem.task;
    if (task) {
      if (task.kind === "hint" &&
          task.index >= 0 && task.index < mem.hints.length &&
          mem.hints[task.index].status === 0) {
        mem.hints[task.index].status = 2;
      } else if (task.kind === "grid") {
        mem.gridVisited[task.key] = true;
      }
    }
    mem.task = null;
    mem.search = null;
    mem.navKey = "";
  }

  function updateSearch() {
    const s = mem.search;
    if (!s) return;

    if (science > num(s.bestScience, 0) + 0.002) {
      s.bestScience = science;
      s.bestX = px;
      s.bestY = py;
    }

    if (s.idx < s.points.length) {
      const q = s.points[s.idx];
      const d = dist(px, py, q.x, q.y);

      if (d < 2.55) {
        if (s.arrival === null) s.arrival = now;
        if (now - num(s.arrival, now) >= 0.35) {
          s.idx++;
          s.arrival = null;
          s.pointStart = now;
          s.pointBest = 1e9;
          mem.navKey = "";
        }
      } else {
        s.arrival = null;
        if (d < num(s.pointBest, 1e9) - 0.40) {
          s.pointBest = d;
          s.pointStart = now;
        } else if (s.pointBest > 1e8) {
          s.pointBest = d;
          s.pointStart = now;
        }
        if (now - num(s.pointStart, now) > 38) {
          s.idx++;
          s.pointStart = now;
          s.pointBest = 1e9;
          mem.navKey = "";
        }
      }
    }

    if (s.idx < s.points.length) return;

    const gain = num(s.bestScience, science) - num(s.startScience, science);
    const signalThreshold = Math.max(0.010, Math.abs(s.startScience) * 0.07);

    if (mem.task && mem.task.kind === "hint" &&
        s.phase === 0 && !s.outerDone &&
        (gain > signalThreshold ||
         s.bestScience > num(mem.baseScience, 0) + 0.02 ||
         mem.task.value > 1.4)) {
      s.outerDone = true;
      s.phase = 1;
      s.points = makeRing(s.cx, s.cy, 17, 12, px, py);
      s.idx = 0;
      s.arrival = null;
      s.pointStart = now;
      s.pointBest = 1e9;
      mem.navKey = "";
      if (s.points.length) return;
    }

    if (mem.task && mem.task.kind === "hint" &&
        !s.refined && gain > Math.max(0.025, Math.abs(s.startScience) * 0.16) &&
        dist(px, py, s.bestX, s.bestY) > 2.5) {
      s.refined = true;
      s.phase = 2;
      s.points = [{ x: clamp(s.bestX, 4, mem.mapW - 4),
                    y: clamp(s.bestY, 4, mem.mapH - 4) }];
      s.idx = 0;
      s.arrival = null;
      s.pointStart = now;
      s.pointBest = 1e9;
      mem.navKey = "";
      return;
    }

    finishTask();
  }

  function activePlan(task) {
    let route;
    const s = mem.search;

    if (s && s.key === task.key &&
        s.points && s.idx < s.points.length) {
      let x = px;
      let y = py;
      route = 0;
      for (let j = s.idx; j < s.points.length; j++) {
        const q = s.points[j];
        route += dist(x, y, q.x, q.y);
        x = q.x;
        y = q.y;
      }
      route += dist(x, y, mem.baseX, mem.baseY) + 7;
      if (task.kind === "hint" && s.phase === 0 && !s.outerDone) {
        route += 28;
      }
    } else {
      route = dist(px, py, task.x, task.y) +
        dist(task.x, task.y, mem.baseX, mem.baseY) +
        searchLength(task);
    }

    return {
      route: route,
      energy: energyNeed(route, carried + 1),
      time: route / effectiveSpeed() + 42
    };
  }

  if (docked) {
    mem.returning = false;
    if (carried > 0) return stopOutput();
  }

  if (mem.sampling && !docked) {
    const out = sampleOutput();
    if (out) return out;
    if (mem.returning) return goHome();
  }

  if (!docked && !mem.returning) {
    const homeEnergy = energyNeed(baseDistance, carried);
    const homeTime = returnTime(baseDistance);
    if (carried >= mem.capacity ||
        battery < homeEnergy + (carried > 0 ? 0.13 : 0.08) ||
        timeLeft < homeTime + (carried > 0 ? 18 : 8)) {
      startReturn();
    }
  }
  if (mem.returning && !docked) return goHome();

  if (siteVisible && !mem.returning && !mem.sampling) {
    if (carried >= mem.capacity || !canStartSample()) {
      if (!docked) {
        startReturn();
        return goHome();
      }
      return stopOutput();
    }

    if (siteDistance <= 1.40) {
      beginSampling();
      const out = sampleOutput();
      if (out) return out;
    }
    return navigation(siteBearing, siteDistance, "site",
                      "visible-site", 0.70);
  }

  for (let guard = 0; guard < 7; guard++) {
    if (mem.task && !taskValid(mem.task)) {
      mem.task = null;
      mem.search = null;
      mem.navKey = "";
    }
    if (!mem.task) mem.task = chooseTask();

    if (!mem.task) {
      if (docked) return stopOutput();
      startReturn();
      return goHome();
    }

    const task = mem.task;

    if (task.phase !== 1) {
      const d = dist(px, py, task.x, task.y);
      if (d < 4.0) {
        startSearch(task);
        continue;
      }

      const plan = activePlan(task);
      if (plan.time > timeLeft - 8) {
        if (docked) {
          finishTask();
          continue;
        }
        startReturn();
        return goHome();
      }
      if (plan.energy > battery - 0.08) {
        if (docked) return stopOutput();
        startReturn();
        return goHome();
      }

      const bearing = Math.atan2(task.y - py, task.x - px) / RAD;
      return navigation(wrap(bearing - headingTrue), d,
                        "waypoint", "task:" + task.key, 1.9);
    }

    updateSearch();
    if (!mem.task || !mem.search) continue;

    const plan = activePlan(mem.task);
    if (plan.time > timeLeft - 8) {
      if (docked) {
        finishTask();
        continue;
      }
      startReturn();
      return goHome();
    }
    if (plan.energy > battery - 0.08) {
      if (docked) return stopOutput();
      startReturn();
      return goHome();
    }

    const s = mem.search;
    const q = s.points[s.idx];
    if (!q) {
      finishTask();
      continue;
    }
    const d = dist(px, py, q.x, q.y);
    const bearing = Math.atan2(q.y - py, q.x - px) / RAD;
    const key = "search:" + s.key + ":" + s.phase + ":" + s.idx;
    return navigation(wrap(bearing - headingTrue), d,
                      "waypoint", key, 1.85);
  }

  if (docked) return stopOutput();
  startReturn();
  return goHome();
