function act(obs, mem) {
  obs = obs || {};
  if (!mem || typeof mem !== "object") mem = {};

  const RAD = Math.PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const finite = (v) =>
    v !== null && v !== undefined && Number.isFinite(Number(v));
  const num = (v, fallback) => finite(v) ? Number(v) : fallback;
  const wrap = (a) => {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x2 - x1, y2 - y1);

  const now = num(obs.t, num(mem.clock, 0));
  const rawX = num(obs.x, 200);
  const rawY = num(obs.y, 200);
  const headingRaw = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const wheelAvg = (wl + wr) * 0.5;
  const wheelAbs = (Math.abs(wl) + Math.abs(wr)) * 0.5;
  const pitch = num(obs.pitch, 0);
  const battery = Math.max(0, num(obs.battery, 0));
  const solar = Math.max(0, num(obs.solar, 0));
  const carried = Math.max(0, num(obs.carried, 0));
  const carriedValue = Math.max(0, num(obs.carriedValue, 0));
  const delivered = Math.max(0, num(obs.delivered, 0));
  const science = Math.max(0, num(obs.science, 0));
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;

  if (!mem._v7) {
    const mission = obs.mission || {};
    const size = mission.size;
    let mapW = 400;
    let mapH = 400;

    if (typeof size === "number") {
      mapW = size;
      mapH = size;
    } else if (Array.isArray(size)) {
      mapW = num(size[0], 400);
      mapH = num(size[1], mapW);
    } else if (size && typeof size === "object") {
      mapW = num(size.width, num(size.x, 400));
      mapH = num(size.height, num(size.y, mapW));
    } else {
      mapW = num(mission.width, 400);
      mapH = num(mission.height, mapW);
    }

    mapW = Math.max(20, mapW);
    mapH = Math.max(20, mapH);
    const base = mission.base || {};

    mem.mapW = mapW;
    mem.mapH = mapH;
    mem.baseX = num(base.x, mapW * 0.5);
    mem.baseY = num(base.y, mapH * 0.5);
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));

    mem.hints = [];
    const hints = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hints.length; i++) {
      const h = hints[i] || {};
      const x = num(h.x, NaN);
      const y = num(h.y, NaN);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      let value = num(h.estimate, num(h.value, 1));
      if (!(value > 0)) value = 0.2;
      mem.hints.push({
        x: clamp(x, 4, mapW - 4),
        y: clamp(y, 4, mapH - 4),
        value: value,
        status: 0
      });
    }

    mem.grid = [];
    let gi = 0;
    for (let x = 30; x <= mapW - 20; x += 45) {
      for (let y = 30; y <= mapH - 20; y += 45) {
        mem.grid.push({
          x: clamp(x, 4, mapW - 4),
          y: clamp(y, 4, mapH - 4),
          key: "g:" + gi++
        });
      }
    }
    mem.gridVisited = {};

    mem.task = null;
    mem.search = null;
    mem.nextTaskId = 1;
    mem.returning = false;
    mem.localCooldown = 0;

    mem.clock = now;
    mem._lastT = now;
    mem.headingOffset = 0;
    mem.lastHeadRaw = headingRaw;

    mem.posX = rawX;
    mem.posY = rawY;
    mem.rawPrevX = rawX;
    mem.rawPrevY = rawY;
    mem.gpsFrozen = false;
    mem.gpsFreezeCount = 0;

    mem.calPrevX = rawX;
    mem.calPrevY = rawY;
    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;

    mem.speedEst = 0.50;
    mem.speedDistance = 0;
    mem.speedTime = 0;
    mem.burn = 0.0011;
    mem.energyBucket = 0;
    mem.distanceBucket = 0;
    mem.energyShock = 0;
    mem.prevBattery = battery;

    mem.lastCarried = carried;
    mem.lastCarriedValue = carriedValue;
    mem.lastDelivered = delivered;

    mem.sampling = false;
    mem.sampleX = rawX;
    mem.sampleY = rawY;
    mem.sampleSiteX = null;
    mem.sampleSiteY = null;
    mem.sampleHeading = headingRaw;
    mem.stillTicks = 0;
    mem.lastSampleX = null;
    mem.lastSampleY = null;
    mem.suppressSiteUntil = -1;

    mem.motorGain = [2.7, 2.7];
    mem.motorIntegral = [0, 0];
    mem.motorStall = [0, 0];
    mem.prevCmd = [0, 0];
    mem.prevTarget = [0, 0];

    mem.navKey = "";
    mem.navBestDist = 1e9;
    mem.navProgressT = now;
    mem.navRecoveries = 0;
    mem.navFailedKey = "";
    mem.lastSteer = 0;
    mem.recoverUntil = 0;
    mem.recoverSign = 1;
    mem.lastBumped = false;
    mem.bumpCount = 0;

    mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
    mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
    mem.rayBad = [false, false, false, false, false, false, false, false, false];
    mem.rayTravel = 0;

    mem.baseScience = science;
    mem._v7 = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.grid)) mem.grid = [];
  if (!mem.gridVisited) mem.gridVisited = {};
  if (!Array.isArray(mem.motorGain)) mem.motorGain = [2.7, 2.7];
  if (!Array.isArray(mem.motorIntegral)) mem.motorIntegral = [0, 0];
  if (!Array.isArray(mem.motorStall)) mem.motorStall = [0, 0];
  if (!Array.isArray(mem.prevCmd)) mem.prevCmd = [0, 0];
  if (!Array.isArray(mem.prevTarget)) mem.prevTarget = [0, 0];
  if (!Array.isArray(mem.rayLast)) mem.rayLast = [15, 15, 15, 15, 15, 15, 15, 15, 15];
  if (!Array.isArray(mem.rayStale)) mem.rayStale = [0, 0, 0, 0, 0, 0, 0, 0, 0];
  if (!Array.isArray(mem.rayBad)) mem.rayBad = [false, false, false, false, false, false, false, false, false];

  let dt = 0.1;
  const oldT = num(mem._lastT, now);
  if (now - oldT > 0.015 && now - oldT < 0.9) dt = now - oldT;
  mem._lastT = now;
  mem.clock = now;

  const oldPX = num(mem.posX, rawX);
  const oldPY = num(mem.posY, rawY);
  const rawPrevX = num(mem.rawPrevX, rawX);
  const rawPrevY = num(mem.rawPrevY, rawY);
  const rawStep = dist(rawX, rawY, rawPrevX, rawPrevY);

  let headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));
  const headingDelta = wrap(headingRaw - num(mem.lastHeadRaw, headingRaw));
  const expectedYaw = (wr - wl) / 0.6 * dt / RAD;
  const yawMismatch = wrap(headingDelta - expectedYaw);
  if (Math.abs(expectedYaw) < 25 && Math.abs(yawMismatch) > 70) {
    mem.headingOffset = wrap(
      num(mem.headingOffset, 0) + clamp(yawMismatch, -150, 150)
    );
  }
  mem.lastHeadRaw = headingRaw;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  if (!docked && wheelAbs > 0.22 && rawStep < 0.015) {
    mem.gpsFreezeCount = (mem.gpsFreezeCount || 0) + 1;
  } else if (rawStep > 0.04 || docked || wheelAbs < 0.10) {
    mem.gpsFreezeCount = 0;
  }
  if (mem.gpsFreezeCount > 18) mem.gpsFrozen = true;

  if (mem.gpsFrozen) {
    if (rawStep > 0.45 && rawStep < 10 && !docked) {
      mem.gpsFrozen = false;
      mem.gpsFreezeCount = 0;
      mem.posX = rawX;
      mem.posY = rawY;
    } else if (!docked && wheelAbs > 0.07) {
      const a = headingTrue * RAD;
      const odom = wheelAvg * dt * 0.72;
      mem.posX = oldPX + odom * Math.cos(a);
      mem.posY = oldPY + odom * Math.sin(a);
    }
  } else if (rawStep > 12 && !docked) {
    mem.posX = oldPX;
    mem.posY = oldPY;
  } else {
    const alpha = docked ? 0.30 : (wheelAbs > 0.15 ? 0.48 : 0.18);
    mem.posX = oldPX + alpha * (rawX - oldPX);
    mem.posY = oldPY + alpha * (rawY - oldPY);
