    mem.calDX = 0;
    mem.calDY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calN = 0;
  }
  mem.calPrevX = rawX;
  mem.calPrevY = rawY;
  mem.rawPrevX = rawX;
  mem.rawPrevY = rawY;
  headingTrue = wrap(headingRaw - num(mem.headingOffset, 0));

  let px = num(mem.posX, rawX);
  let py = num(mem.posY, rawY);
  const stepX = px - oldPX;
  const stepY = py - oldPY;
  const stepDist = Math.hypot(stepX, stepY);

  if (!docked && !mem.gpsFrozen && wheelAbs > 0.15 && stepDist < 1.2) {
    mem.speedDistance = num(mem.speedDistance, 0) + stepDist;
    mem.speedTime = num(mem.speedTime, 0) + dt;
    if (mem.speedTime >= 4) {
      const measured = mem.speedDistance / Math.max(0.5, mem.speedTime) * 1.10;
      if (measured > 0.12 && measured < 1.2) {
        mem.speedEst = 0.88 * num(mem.speedEst, 0.50) +
          0.12 * clamp(measured, 0.23, 0.90);
      }
      mem.speedDistance = 0;
      mem.speedTime = 0;
    }
  } else if (mem.gpsFrozen) {
    mem.speedDistance = 0;
    mem.speedTime = 0;
  }
  mem.speedEst = clamp(num(mem.speedEst, 0.50), 0.25, 0.90);

  const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  const hasRays = !!(obs.rays && typeof obs.rays.length === "number");
  const rays = [];
  for (let i = 0; i < 9; i++) {
    const r = clamp(num(hasRays ? obs.rays[i] : 15, 15), 0, 15);
    rays.push(r);
    if (Math.abs(r - num(mem.rayLast[i], 15)) < 0.025) {
      mem.rayStale[i] = (mem.rayStale[i] || 0) + 1;
    } else {
      mem.rayStale[i] = 0;
      if (mem.rayBad[i] &&
          Math.abs(r - num(mem.rayLast[i], r)) > 0.5) {
        mem.rayBad[i] = false;
      }
    }
    mem.rayLast[i] = r;
  }
  mem.rayTravel = num(mem.rayTravel, 0) + stepDist;
  if (mem.rayTravel > 6) {
    for (let i = 0; i < 9; i++) {
      if (mem.rayStale[i] > 160 && rays[i] < 14.7) mem.rayBad[i] = true;
    }
    mem.rayTravel = 0;
  }

  const oldBattery = num(mem.prevBattery, battery);
  const db = oldBattery - battery;
  if (!docked && db > 0.055 && stepDist < 0.6) {
    mem.burn = clamp(num(mem.burn, 0.0011) * 1.16, 0.0004, 0.008);
    mem.energyShock = Math.min(0.24, num(mem.energyShock, 0) + 0.035);
  }
  if (!docked && stepDist > 0.015 && db >= 0) {
