  for (let i = 0; i < 2; i++) {
    const actual = i === 0 ? wl : wr;
    const previousCmd = num(mem.prevCmd[i], 0);
    const previousTarget = num(mem.prevTarget[i], 0);
    if (Math.abs(previousCmd) > 0.11 &&
        Math.abs(previousTarget) > 0.10 &&
        actual * previousTarget > 0 &&
        Math.abs(actual) > 0.07) {
      const ratio = Math.abs(actual / previousCmd);
      if (ratio > 0.55 && ratio < 8) {
