    if (rightDanger > leftDanger + 0.02) mem.recoverSign = 1;
    else if (leftDanger > rightDanger + 0.02) mem.recoverSign = -1;
    else mem.recoverSign = -num(mem.recoverSign, 1);
    if (!mem.recoverSign) mem.recoverSign = 1;
    mem.recoverUntil = now + 1.2;
    mem.bumpCount = (mem.bumpCount || 0) + 1;
  }
  mem.lastBumped = bumped;

  const timeLeft = Math.max(0, num(obs.timeLeft, mem.totalSeconds - now));

  let siteVisible = false;
  let siteDistance = 99;
  let siteBearing = 0;
  let siteGX = NaN;
  let siteGY = NaN;
  const siteObs = obs.site;
  if (siteObs && finite(siteObs.distance)) {
    siteDistance = clamp(num(siteObs.distance, 99), 0, 12);
    siteBearing = wrap(num(siteObs.bearing, 0));
    const a = (headingTrue + siteBearing) * RAD;
    siteGX = px + siteDistance * Math.cos(a);
    siteGY = py + siteDistance * Math.sin(a);
    siteVisible = siteDistance <= 8.5;
  }
  if (siteVisible && now < num(mem.suppressSiteUntil, -1) &&
      finite(mem.lastSampleX) && finite(mem.lastSampleY) &&
      dist(siteGX, siteGY, Number(mem.lastSampleX),
           Number(mem.lastSampleY)) < 2.8) {
    siteVisible = false;
  }

  const beacon = obs.beacon;
  let beaconDistance = null;
  if (beacon && finite(beacon.distance) &&
      Number(beacon.distance) <= 25) {
    beaconDistance = Math.max(0, num(beacon.distance, 100));
  }
  const gpsBaseDistance = dist(px, py, mem.baseX, mem.baseY);
  const baseDistance = docked ? 0 :
    (beaconDistance !== null ? beaconDistance : gpsBaseDistance);

  const oldCarried = num(mem.lastCarried, carried);
  const oldCarriedValue = num(mem.lastCarriedValue, carriedValue);
  const oldDelivered = num(mem.lastDelivered, delivered);
  const justSampled = carried > oldCarried + 0.01 ||
                      carriedValue > oldCarriedValue + 0.01;
  const justDelivered = delivered > oldDelivered + 0.01 ||
                        (docked && carried < oldCarried - 0.01);

  if (justSampled) {
    const sx = finite(mem.sampleSiteX) ? Number(mem.sampleSiteX) :
      (Number.isFinite(siteGX) ? siteGX : px);
    const sy = finite(mem.sampleSiteY) ? Number(mem.sampleSiteY) :
      (Number.isFinite(siteGY) ? siteGY : py);
    mem.lastSampleX = sx;
    mem.lastSampleY = sy;
    mem.suppressSiteUntil = now + 1.0;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h && h.status === 0 && dist(sx, sy, h.x, h.y) < 8) {
        h.status = 1;
      }
    }

    const task = mem.task;
    if (task) {
      let linked = false;
      if (task.kind === "hint") {
        linked = (mem.search && mem.search.key === task.key) ||
          dist(sx, sy, task.x, task.y) < 30;
        if (linked && task.index >= 0 && task.index < mem.hints.length) {
          mem.hints[task.index].status = 1;
        }
      } else if (task.kind === "grid") {
        linked = (mem.search && mem.search.key === task.key) ||
          dist(sx, sy, task.x, task.y) < 14;
        if (linked) mem.gridVisited[task.key] = true;
      } else if (task.kind === "local") {
        linked = true;
      }
      if (linked) {
