// heading = compass + bias; bias learned from GPS displacement on straight commanded runs
function updateHeading(obs, mem) {
  const straight = mem.lastL > 0.2 && mem.lastR > 0.2 &&
    Math.abs(mem.lastL - mem.lastR) < 0.2 && !mem.gpsFrozen && !obs.bumped;
  if (straight) {
    if (!mem.ref) mem.ref = { x: obs.x, y: obs.y };
    else if (dist(mem.ref.x, mem.ref.y, obs.x, obs.y) >= 8) {
      const g = Math.atan2(obs.y - mem.ref.y, obs.x - mem.ref.x) * R2D;
      const e = wrap(g - wrap((obs.heading || 0) + mem.bias));
      mem.bias = wrap(mem.bias + 0.25 * e);
      mem.ref = { x: obs.x, y: obs.y };
    }
  } else mem.ref = null;
  mem.hd = wrap((obs.heading || 0) + mem.bias);
}

function readRays(obs, mem) {
  const r = obs.rays || [];
  const moving = mem.lastAvg > 0.15;
  const d = [];
  for (let i = 0; i < 9; i++) {
    let v = Number(r[i]);
    if (!(v > 0)) v = 15;
    if (v > 15) v = 15;
    if (moving) {
      if (mem.rLast[i] === v) mem.rCnt[i] = (mem.rCnt[i] || 0) + 1;
      else { mem.rCnt[i] = 0; mem.rLast[i] = v; }
    }
    if ((mem.rCnt[i] || 0) > 80) v = 15; // sensor looks stuck
    d.push(v);
  }
  return d;
}

// err: degrees, positive = target to the left
function drive(err, v) {
  const ae = Math.abs(err);
  if (ae > 45) {
    const s = err > 0 ? 1 : -1;
    return mk(-0.3 * s, 0.3 * s);
  }
  let spd = v * (1 - ae / 60);
  if (spd < MINF) spd = MINF;
  const steer = clamp(0.012 * err, -0.25, 0.25);
  return mk(spd - steer, spd + steer);
}

function driveTo(err, v, d) {
  const front = Math.min(d[3], d[4], d[5]);
