    let v = Number(r[i]);
    if (!(v > 0)) v = 15;
    if (v > 15) v = 15;
    if (moving) {
      if (mem.rLast[i] === v) mem.rCnt[i] = (mem.rCnt[i] || 0) + 1;
      else { mem.rCnt[i] = 0; mem.rLast[i] = v; }
    }
    if ((mem.rCnt[i] || 0) > 80) v = 15; // sensor looks stuck
    d.push(v);
  }
  return d;
}

// err in degrees, positive = target to the left
function steerCmd(err, v) {
  const ae = Math.abs(err);
  if (ae > 60) {
    const s = err > 0 ? 1 : -1;
    return mk(-0.3 * s, 0.3 * s);
  }
  let spd = v * (1 - ae / 90);
  if (spd < MINF) spd = MINF;
  const st = clamp(KS * err, -0.3, 0.3);
  return mk(spd - st, spd + st);
}

function slowF(d) {
  const f = Math.min(d[3], d[4], d[5]);
  return f < 5 ? clamp((f - 1.5) / 3.5, 0.35, 1) : 1;
}

function navTo(o, mem, tx, ty, v, d, stopR) {
  const dd = dist(o.x, o.y, tx, ty);
  if (dd <= stopR) return null;
  const err = wrap(Math.atan2(ty - o.y, tx - o.x) * R2D - mem.hd);
  return steerCmd(err, clamp(0.15 + 0.15 * dd, 0.2, v) * slowF(d));
}

function openSide(d) {
  const L = Math.min(d[5], d[6], d[7], d[8]);
  const R = Math.min(d[0], d[1], d[2], d[3]);
  return L >= R ? 1 : -1;
}

function startBack(mem, d) {
  mem.avDir = openSide(d);
  mem.backT = 15;
}

function siteWorld(o, mem, s) {
  const a = (mem.hd + s.bearing) * D2R;
  return { x: o.x + s.distance * Math.cos(a), y: o.y + s.distance * Math.sin(a) };
}

function drillStep(o, obs, mem) {
  const el = obs.drilling || 0;
  const avg = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  const moved = dist(o.x, o.y, mem.dX, mem.dY);
  if (el >= 6.3) {
    mem.drilling = false; mem.holdI = 0;
    const s = mem.dSite;
    addSkip(mem, s.x, s.y, 1);
    for (const h of mem.hints) {
      if (h !== mem.cur && dist(h.x, h.y, s.x, s.y) < 15) h.done = true;
    }
    mem.sampledN++;
    return zero();
  }
  if (moved > 3.0 || mem.ticks - mem.dT0 > 200) {
    mem.drilling = false; mem.holdI = 0;
    addSkip(mem, mem.dSite.x, mem.dSite.y, 2);
    return zero();
  }
  mem.holdI = clamp(mem.holdI - 0.05 * avg, -0.4, 0.4);
  const c = clamp(mem.holdI - 1.5 * avg, -0.4, 0.4);
  return { left: c, right: c, drill: true };
}

function siteStep(o, obs, mem, d, s, sw) {
  const sp = (Math.abs(obs.wheelLeft || 0) + Math.abs(obs.wheelRight || 0)) / 2;
  if (s.distance <= 1.3) {
    if (sp < 0.12) {
      mem.drilling = true; mem.dT0 = mem.ticks;
      mem.dX = o.x; mem.dY = o.y; mem.dSite = sw; mem.holdI = 0;
      mem.pos = [];
      return { left: 0, right: 0, drill: true };
    }
    return zero();
  }
  return steerCmd(s.bearing, clamp(0.15 + 0.12 * s.distance, 0.2, 0.35) * slowF(d));
}

function pushScience(o, obs, mem) {
  if (!(obs.science > 1.0) || mem.pushed >= 6 || obs.site) return;
  for (const h of mem.hints) if (!h.done && dist(h.x, h.y, o.x, o.y) < 10) return;
  for (const p of mem.skip) if (dist(p.x, p.y, o.x, o.y) < 10) return;
  mem.hints.push(newHint(o.x, o.y, Math.max(0.1, obs.science * 3)));
  mem.pushed++;
}

function pickTarget(o, mem) {
  for (let pass = 0; pass < 3; pass++) {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.done) continue;
      const d = dist(o.x, o.y, h.x, h.y);
      const s = h.est / (d + 50);
      if (s > bs) { bs = s; best = h; }
    }
    if (best) {
      best.arrived = false; best.bad = 0; best.t0 = mem.ticks;
      best.wps = []; best.wi = 0;
      mem.cur = best;
      return;
    }
    if (!mem.gridAdded) { addGrid(mem); continue; }
    if (mem.cycles >= 1) break;
    for (const h of mem.hints) { h.done = false; h.bad = 0; }
    mem.cycles++;
  }
  mem.cur = null;
}

// rectangle around the hint (half sides 9 x 6), starting at the nearest corner
function lawnPts(o, c) {
  const offs = [[-9, -6], [9, -6], [9, 6], [-9, 6]];
  const pts = offs.map(p => ({ x: clamp(c.x + p[0], 3, 397), y: clamp(c.y + p[1], 3, 397) }));
  let k = 0, best = 1e9;
  for (let i = 0; i < 4; i++) {
    const dd = dist(o.x, o.y, pts[i].x, pts[i].y);
    if (dd < best) { best = dd; k = i; }
  }
  return [pts[k], pts[(k + 1) % 4], pts[(k + 2) % 4], pts[(k + 3) % 4]];
}

function deliverStep(o, obs, mem, d) {
  const b = obs.beacon;
  const haveB = !!(b && b.distance <= 20);
  const dB = dist(o.x, o.y, mem.base.x, mem.base.y);
  const dd = haveB ? b.distance : dB;
  if (dd <= 2.4) {
    mem.pos = [];
    mem.dockT++;
    if (mem.dockT > 60 && mem.purpose === 'deliver') {
      mem.mode = 'explore'; mem.dockT = 0; mem.noDelUntil = (obs.t || 0) + 60;
    }
    return zero();
  }
  mem.dockT = 0;
  if (haveB) return steerCmd(b.bearing, clamp(0.15 + 0.12 * dd, 0.2, CRUISE) * slowF(d));
  return navTo(o, mem, mem.base.x, mem.base.y, CRUISE, d, 2.0) || zero();
}

function decide(o, obs, mem, d) {
  const carried = obs.carried || 0;
  const dB = dist(o.x, o.y, mem.base.x, mem.base.y);
  const fwd = mem.lastAvg > 0.15;

  if (mem.drilling) { mem.pos = []; return drillStep(o, obs, mem); }

  // bump recovery
  if (obs.bumped) {
    mem.bumpN++;
    startBack(mem, d);
    if (mem.cur) mem.cur.bad += 0.5;
    mem.pos = [];
  }
  // stuck: barely moved in ~10 s
  if (mem.backT <= 0 && mem.avT <= 0 && !mem.gpsFrozen && mem.pos.length >= 101) {
    const p = mem.pos[0];
    if (dist(o.x, o.y, p.x, p.y) < 1.0) {
      mem.escN++;
      startBack(mem, d);
      if (mem.cur) mem.cur.bad += 1;
      mem.pos = [];
    }
  }
  if (mem.backT > 0) {
    mem.backT--;
    if (mem.backT === 0) mem.avT = 12;
    return mk(-0.3, -0.3);
  }
  if (mem.avT > 0) {
    mem.avT--;
    return mk(-0.3 * mem.avDir, 0.3 * mem.avDir);
  }
  // obstacle directly ahead while moving: pivot toward open side
  const front = Math.min(d[3], d[4], d[5]);
  if (fwd && front < 2.0 && dB > 4) {
    mem.avDir = openSide(d);
    mem.avT = 8;
    return mk(-0.25 * mem.avDir, 0.25 * mem.avDir);
  }

  // delivery triggers
  if (mem.mode !== 'deliver') {
    if (carried > 0) {
      const eta = dB / 0.35 + 90;
      const urgent = carried >= mem.cap || obs.timeLeft < eta || obs.battery < 0.25;
      const opp = (obs.t || 0) >= mem.noDelUntil &&
        ((carried >= 3 && dB < 60) || (carried >= 2 && dB < 30) || (carried >= 1 && dB < 12));
      if (urgent || opp) { mem.mode = 'deliver'; mem.purpose = 'deliver'; mem.dockT = 0; }
    } else if (obs.battery < 0.12 && obs.timeLeft > 150) {
      mem.mode = 'deliver'; mem.purpose = 'rest'; mem.dockT = 0;
    }
  }
  if (mem.mode === 'deliver') {
    if (mem.purpose === 'deliver' && carried === 0) {
      mem.mode = 'explore';
    } else if (mem.purpose === 'rest' && (obs.battery > 0.5 || obs.timeLeft < 60)) {
      mem.mode = 'explore';
    } else {
      return deliverStep(o, obs, mem, d);
    }
  }

  // nearby site: approach and drill
  const s = obs.site;
  if (s && carried < mem.cap) {
    const sw = siteWorld(o, mem, s);
    if (!findSkip(mem, sw.x, sw.y)) {
      if ((obs.t || 0) - mem.lastSiteT > 1.0) mem.siteT0 = obs.t || 0;
      mem.lastSiteT = obs.t || 0;
      if ((obs.t || 0) - mem.siteT0 <= 60) {
        return siteStep(o, obs, mem, d, s, sw);
      }
      addSkip(mem, sw.x, sw.y, 2);
    }
  }

  pushScience(o, obs, mem);

  if (!mem.cur || mem.cur.done) pickTarget(o, mem);
  const cur = mem.cur;
  if (!cur) return zero();

  if (cur.bad >= 3 || mem.ticks - cur.t0 > 2000) {
    cur.done = true; mem.cur = null;
    return zero();
  }
  if (!cur.arrived) {
    if (dist(o.x, o.y, cur.x, cur.y) < 4) {
      cur.arrived = true;
      cur.wps = lawnPts(o, cur);
      cur.wi = 0;
      cur.sT = mem.ticks;
    } else {
      return navTo(o, mem, cur.x, cur.y, CRUISE, d, 3.0) || zero();
    }
  }
  if (cur.wi >= cur.wps.length || mem.ticks - cur.sT > 900) {
    cur.done = true;
    markNear(mem, cur.x, cur.y, 10);
    mem.cur = null;
    return zero();
  }
  const w = cur.wps[cur.wi];
  if (dist(o.x, o.y, w.x, w.y) < 1.5) { cur.wi++; return zero(); }
  return navTo(o, mem, w.x, w.y, CRUISE, d, 1.0) || zero();
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.ticks++;

  // GPS freeze detection with dead reckoning from wheel speeds
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.frozen++;
  else { mem.frozen = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  mem.gpsFrozen = mem.frozen > 40 && mem.lastAvg > 0.15;
  if (mem.gpsFrozen) {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
    mem.px += v * 0.1 * Math.cos(mem.hd * D2R);
    mem.py += v * 0.1 * Math.sin(mem.hd * D2R);
  } else {
    mem.px = obs.x; mem.py = obs.y;
  }

  const o = Object.assign({}, obs, { x: mem.px, y: mem.py });
  mem.pos.push({ x: o.x, y: o.y });
  if (mem.pos.length > 101) mem.pos.shift();

  updateHeading(o, mem);
  const d = readRays(obs, mem);
  const cmd = decide(o, obs, mem, d);
  mem.lastL = cmd.left; mem.lastR = cmd.right;
  mem.lastAvg = (cmd.left + cmd.right) / 2;
  return { left: cmd.left, right: cmd.right, drill: !!cmd.drill };
}

function act(obs, mem) {
  try {
    return step(obs, mem);
  } catch (e) {
    return zero();
  }
}

const D2R = Math.PI / 180;
const R2D = 180 / Math.PI;
const CRUISE = 0.4;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(bx - ax, by - ay); }
function mk(l, r, drill) { return { left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!drill }; }
function zero() { return mk(0, 0, false); }

function newHint(x, y, est) {
  return { x: x, y: y, est: est, done: false, bad: 0, arrived: false, t0: 0,
    wps: [], wi: 0, sT: 0, sb: 0, sx: x, sy: y, refined: false };
}

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.base = m.base || { x: obs.x || 200, y: obs.y || 200 };
  mem.cap = m.capacity || 5;
  mem.hints = (m.hints || []).map(h =>
    newHint(h.x, h.y, typeof h.estimate === 'number' ? Math.max(h.estimate, 0.05) : 1));
  mem.gridAdded = false; mem.cycles = 0; mem.pushed = 0;
  mem.bias = 0; mem.ref = null; mem.hd = obs.heading || 0;
  mem.skip = [];
  mem.mode = 'explore'; mem.dockT = 0; mem.noDel = -1;
  mem.cur = null;
  mem.drilling = false; mem.dT0 = 0; mem.dX = 0; mem.dY = 0; mem.dSite = null; mem.holdI = 0;
  mem.siteAct = null;
  mem.backT = 0; mem.turnT = 0; mem.turnDir = 1;
  mem.lastL = 0; mem.lastR = 0; mem.lastAvg = 0;
  mem.rLast = []; mem.rCnt = [];
  mem.hist = [];
  mem.ticks = 0; mem.bumpN = 0; mem.sampledN = 0; mem.stuckN = 0;
  mem.frozen = 0; mem.lastGx = NaN; mem.lastGy = NaN; mem.gpsFrozen = false;
  mem.px = obs.x; mem.py = obs.y;
}

function addGrid(mem) {
  mem.gridAdded = true;
  for (const gx of [60, 200, 340]) for (const gy of [60, 200, 340]) {
    mem.hints.push(newHint(gx, gy, 0.3));
  }
}

function findSkip(mem, x, y) {
  for (const s of mem.skip) if (dist(s.x, s.y, x, y) < 4) return s;
  return null;
}
function addSkip(mem, x, y, inc) {
  const s = findSkip(mem, x, y);
  if (s) s.n += inc; else mem.skip.push({ x: x, y: y, n: inc });
}
function markNear(mem, x, y, r) {
  for (const h of mem.hints) if (dist(h.x, h.y, x, y) < r) h.done = true;
}

// heading = compass + bias; bias learned from GPS track on straight forward runs
function updateHeading(obs, mem, o) {
  const straight = mem.lastL > 0.15 && mem.lastR > 0.15 &&
    Math.abs(mem.lastL - mem.lastR) < 0.25 && !mem.gpsFrozen &&
    mem.backT <= 0 && mem.turnT <= 0;
  if (straight) {
    if (!mem.ref) mem.ref = { x: o.x, y: o.y };
    else if (dist(mem.ref.x, mem.ref.y, o.x, o.y) >= 6) {
      const g = Math.atan2(o.y - mem.ref.y, o.x - mem.ref.x) * R2D;
      const e = wrap(g - wrap((obs.heading || 0) + mem.bias));
      mem.bias = wrap(mem.bias + 0.2 * e);
      mem.ref = { x: o.x, y: o.y };
    }
  } else mem.ref = null;
  mem.hd = wrap((obs.heading || 0) + mem.bias);
}

function readRays(obs, mem) {
  const r = obs.rays || [];
  const moving = mem.lastAvg > 0.15;
  const d = [];
  for (let i = 0; i < 9; i++) {
    let v = Number(r[i]);
    if (!(v > 0)) v = 15;
    if (v > 15) v = 15;
    if (moving) {
      if (mem.rLast[i] === v) mem.rCnt[i] = (mem.rCnt[i] || 0) + 1;
      else { mem.rCnt[i] = 0; mem.rLast[i] = v; }
    }
    if ((mem.rCnt[i] || 0) > 80) v = 15; // sensor looks stuck
    d.push(v);
  }
  return d;
}

// a: degrees, positive = left. Gentle gain, capped, pivot for large errors.
function steerTo(a, v) {
  const ae = Math.abs(a);
  if (ae > 55) {
    const s = a > 0 ? 1 : -1;
    return mk(-0.3 * s, 0.3 * s, false);
  }
  const vv = Math.max(0.2, v * (1 - ae / 90));
  const st = clamp(0.003 * a, -0.12, 0.12);
  return mk(vv - st, vv + st, false);
}

function openSide(d) {
  const L = Math.min(d[5], d[6], d[7], d[8]);
  const R = Math.min(d[0], d[1], d[2], d[3]);
  return L >= R ? 1 : -1;
}

function openPivot(d) {
  const s = openSide(d);
  return mk(-0.3 * s, 0.3 * s, false);
}

// choose a direction (degrees) close to target bearing tb that is free of obstacles
function chooseAngle(d, tb) {
  let best = -1, bs = 1e9;
  for (let i = 0; i < 9; i++) {
    const r = d[i];
    const lo = i > 0 ? d[i - 1] : r;
    const hi = i < 8 ? d[i + 1] : r;
    if (r < 2.5 || lo < 1.8 || hi < 1.8) continue;
    const s = Math.abs(ANG[i] - tb);
    if (s < bs) { bs = s; best = i; }
  }
  if (best < 0) return null;
  if (bs <= 12) return tb;
  return ANG[best];
}

function avoidDrive(d, tb, v) {
  const f = Math.min(d[3], d[4], d[5]);
  const vv = f < 4 ? v * clamp((f - 1.2) / 2.8, 0.3, 1) : v;
  const a = chooseAngle(d, tb);
  if (a === null) return openPivot(d);
  return steerTo(a, vv);
}

function navPt(o, mem, tx, ty, v, stopR, d) {
  const dd = dist(o.x, o.y, tx, ty);
  if (dd <= stopR) return null;
  const tb = wrap(Math.atan2(ty - o.y, tx - o.x) * R2D - mem.hd);
  return avoidDrive(d, tb, clamp(0.15 + 0.15 * dd, 0.2, v));
}

function siteWorld(o, mem, s) {
  const a = (mem.hd + s.bearing) * D2R;
  return { x: o.x + s.distance * Math.cos(a), y: o.y + s.distance * Math.sin(a) };
}

function siteStep(o, obs, mem, d, s) {
  const sp = (Math.abs(obs.wheelLeft || 0) + Math.abs(obs.wheelRight || 0)) / 2;
  if (s.distance <= 1.3) {
    if (sp < 0.12) {
      const sw = siteWorld(o, mem, s);
      mem.drilling = true; mem.dT0 = mem.ticks;
      mem.dX = o.x; mem.dY = o.y; mem.dSite = sw; mem.holdI = 0;
      return mk(0, 0, true);
    }
    return zero();
  }
  const v = clamp(0.12 + 0.12 * s.distance, 0.2, 0.3);
  if (s.distance < 3) return steerTo(s.bearing, v);
  return avoidDrive(d, s.bearing, v);
}

function drillStep(o, obs, mem) {
  const el = typeof obs.drilling === 'number' ? obs.drilling : (mem.ticks - mem.dT0) * 0.1;
  const avg = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  const moved = dist(o.x, o.y, mem.dX, mem.dY);
  if (el >= 6.3) {
    mem.drilling = false; mem.holdI = 0;
    const s = mem.dSite;
    addSkip(mem, s.x, s.y, 1);
    mem.sampledN++;
    return zero();
  }
  if (moved > 2.5 || mem.ticks - mem.dT0 > 200) {
    mem.drilling = false; mem.holdI = 0;
    addSkip(mem, mem.dSite.x, mem.dSite.y, 2);
    return zero();
  }
  mem.holdI = clamp(mem.holdI - 0.1 * avg, -0.3, 0.3);
  const c = clamp(mem.holdI - 2 * avg, -0.3, 0.3);
  return mk(c, c, true);
}

function pushScience(o, obs, mem) {
  if (!(obs.science > 1.0) || mem.pushed >= 5 || obs.site) return;
  for (const h of mem.hints) if (!h.done && dist(h.x, h.y, o.x, o.y) < 10) return;
  for (const p of mem.skip) if (dist(p.x, p.y, o.x, o.y) < 10) return;
  mem.hints.push(newHint(o.x, o.y, Math.max(0.2, obs.science * 3)));
  mem.pushed++;
}

function pickTarget(o, mem) {
  for (let pass = 0; pass < 3; pass++) {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.done) continue;
      const dd = dist(o.x, o.y, h.x, h.y);
      const s = h.est / (dd + 60);
      if (s > bs) { bs = s; best = h; }
    }
    if (best) {
      best.arrived = false; best.bad = 0; best.t0 = mem.ticks;
      best.wps = []; best.wi = 0; best.sb = 0; best.sx = best.x; best.sy = best.y; best.refined = false;
      mem.cur = best;
      return;
    }
    if (!mem.gridAdded) { addGrid(mem); continue; }
    if (mem.cycles >= 1) break;
    for (const h of mem.hints) { h.done = false; h.bad = 0; }
    mem.cycles++;
  }
  mem.cur = null;
}

// square of half-side h around (cx, cy), starting at the nearest corner
function squarePts(o, cx, cy, h) {
  const offs = [[-h, -h], [h, -h], [h, h], [-h, h]];
  const pts = offs.map(p => ({ x: clamp(cx + p[0], 3, 397), y: clamp(cy + p[1], 3, 397) }));
  let k = 0, best = 1e9;
  for (let i = 0; i < 4; i++) {
    const dd = dist(o.x, o.y, pts[i].x, pts[i].y);
    if (dd < best) { best = dd; k = i; }
  }
  return [pts[k], pts[(k + 1) % 4], pts[(k + 2) % 4], pts[(k + 3) % 4], pts[k]];
}

function finishTarget(mem, cur) {
  cur.done = true;
  markNear(mem, cur.x, cur.y, 10);
  mem.cur = null;
}

function runTarget(o, obs, mem, d) {
  if (!mem.cur || mem.cur.done) pickTarget(o, mem);
  const cur = mem.cur;
  if (!cur) return null;
  if (cur.bad >= 3 || mem.ticks - cur.t0 > 3000) { finishTarget(mem, cur); return null; }
  if (obs.science > cur.sb) { cur.sb = obs.science; cur.sx = o.x; cur.sy = o.y; }
  if (!cur.arrived) {
    if (dist(o.x, o.y, cur.x, cur.y) < 3) {
      cur.arrived = true;
      cur.wps = squarePts(o, cur.x, cur.y, 6);
      cur.wi = 0; cur.sT = mem.ticks;
    } else {
      return navPt(o, mem, cur.x, cur.y, CRUISE, 2.5, d);
    }
  }
  if (cur.wi >= cur.wps.length || mem.ticks - cur.sT > 700) {
    if (!cur.refined && cur.sb > 0.4) {
      cur.refined = true;
      cur.wps = squarePts(o, cur.sx, cur.sy, 4);
      cur.wi = 0; cur.sT = mem.ticks;
    } else {
      finishTarget(mem, cur);
      return null;
    }
  }
  const w = cur.wps[cur.wi];
  if (dist(o.x, o.y, w.x, w.y) < 1.5) { cur.wi++; return zero(); }
  return navPt(o, mem, w.x, w.y, CRUISE, 1.0, d);
}

function deliverStep(o, obs, mem, d, dB, t) {
  const b = obs.beacon;
  const haveB = !!(b && b.distance <= 20);
  const dd = haveB ? b.distance : dB;
  if (dd <= 2.2) {
    mem.dockT++;
    if (mem.dockT > 60) { mem.mode = 'explore'; mem.dockT = 0; mem.noDel = t + 90; }
    return zero();
  }
  mem.dockT = 0;
  if (haveB) return avoidDrive(d, b.bearing, clamp(0.15 + 0.12 * dd, 0.2, CRUISE));
  const r = navPt(o, mem, mem.base.x, mem.base.y, CRUISE, 2.0, d);
  return r || zero();
}

function decide(o, obs, mem, d, t) {
  const carried = obs.carried || 0;
  const dB = dist(o.x, o.y, mem.base.x, mem.base.y);
  const tl = typeof obs.timeLeft === 'number' ? obs.timeLeft : (1200 - t);

  // bump recovery
  if (obs.bumped && mem.backT <= 0) {
    mem.bumpN++;
    mem.backT = 12;
    mem.turnT = 0;
    mem.hist = [];
    if (mem.cur) mem.cur.bad += 1;
  }
  // stuck recovery: barely moved while commanding forward
  if (mem.backT <= 0 && mem.turnT <= 0 && !mem.gpsFrozen && mem.hist.length >= 150 && mem.lastAvg > 0.1) {
    const p = mem.hist[0];
    if (dist(o.x, o.y, p.x, p.y) < 1.5) {
      mem.stuckN++;
      mem.backT = 15;
      mem.hist = [];
      if (mem.cur) mem.cur.bad += 1;
    }
  }
  if (mem.backT > 0) {
    mem.backT--;
    if (mem.backT === 0) { mem.turnDir = openSide(d); mem.turnT = 8; }
    return mk(-0.3, -0.3, false);
  }
  if (mem.turnT > 0) {
    mem.turnT--;
    return mk(-0.3 * mem.turnDir, 0.3 * mem.turnDir, false);
  }

  // delivery triggers
  if (mem.mode === 'explore' && carried > 0) {
    const eta = dB / 0.4 + 60;
    const urgent = carried >= mem.cap || tl < eta || obs.battery < 0.2;
    const opp = t >= mem.noDel && ((carried >= 2 && dB < 25) || (carried >= 1 && dB < 8));
    if (urgent || opp) { mem.mode = 'deliver'; mem.dockT = 0; }
  }
  if (mem.mode === 'deliver') {
    if (carried === 0) { mem.mode = 'explore'; mem.dockT = 0; }
    else return deliverStep(o, obs, mem, d, dB, t);
  }

  // nearby site: approach and drill
  const s = obs.site;
  if (!s) mem.siteAct = null;
  if (s && carried < mem.cap) {
    const sw = siteWorld(o, mem, s);
    if (!findSkip(mem, sw.x, sw.y)) {
      if (!mem.siteAct || dist(mem.siteAct.x, mem.siteAct.y, sw.x, sw.y) > 5) {
        mem.siteAct = { x: sw.x, y: sw.y, t0: t };
      }
      if (t - mem.siteAct.t0 < 50) return siteStep(o, obs, mem, d, s);
      addSkip(mem, sw.x, sw.y, 2);
    }
  }

  pushScience(o, obs, mem);

  if (!mem.cur || mem.cur.done) pickTarget(o, mem);
  if (!mem.cur && carried > 0) {
    mem.mode = 'deliver'; mem.dockT = 0;
    return deliverStep(o, obs, mem, d, dB, t);
  }
  const r = runTarget(o, obs, mem, d);
  return r || zero();
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.ticks++;
  const t = typeof obs.t === 'number' ? obs.t : mem.ticks * 0.1;

  // GPS freeze detection with dead reckoning from wheel speeds
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.frozen++;
  else { mem.frozen = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  mem.gpsFrozen = mem.frozen > 30 && mem.lastAvg > 0.15;
  if (mem.gpsFrozen) {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
    mem.px += v * 0.1 * Math.cos(mem.hd * D2R);
    mem.py += v * 0.1 * Math.sin(mem.hd * D2R);
  } else {
    mem.px = obs.x; mem.py = obs.y;
  }
  const o = { x: mem.px, y: mem.py };
  mem.hist.push({ x: o.x, y: o.y });
  if (mem.hist.length > 150) mem.hist.shift();

  updateHeading(obs, mem, o);
  const d = readRays(obs, mem);
  const cmd = mem.drilling ? drillStep(o, obs, mem) : decide(o, obs, mem, d, t);
  mem.lastL = cmd.left; mem.lastR = cmd.right;
  mem.lastAvg = (cmd.left + cmd.right) / 2;
  return { left: cmd.left, right: cmd.right, drill: !!cmd.drill };
}

function act(obs, mem) {
  try {
    return step(obs, mem);
  } catch (e) {
    return zero();
  }
}

const D2R = Math.PI / 180;
const R2D = 180 / Math.PI;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const CRUISE = 0.4;
const LAWN = [[-12, -7], [12, -7], [12, 7], [-12, 7]];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(bx - ax, by - ay); }
function mk(l, r, drill) { return { left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!drill }; }
function zero() { return mk(0, 0, false); }

function newHint(x, y, est) {
  return { x: x, y: y, est: est, done: false, dead: false, bad: 0, arrived: false, t0: 0, wps: [], wi: 0, lt0: 0 };
}

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.base = m.base ? { x: m.base.x, y: m.base.y } : { x: obs.x || 200, y: obs.y || 200 };
  mem.cap = m.capacity || 5;
  mem.hints = (m.hints || []).map(h => newHint(h.x, h.y, typeof h.estimate === 'number' ? Math.max(0.05, h.estimate) : 1));
  mem.gridAdded = false; mem.cycles = 0; mem.pushed = 0;
  mem.skip = []; mem.bad = [];
  mem.bias = 0; mem.ref = null; mem.hd = obs.heading || 0;
  mem.lastGx = NaN; mem.lastGy = NaN; mem.frozen = 0; mem.gpsFrozen = false;
  mem.px = obs.x || mem.base.x; mem.py = obs.y || mem.base.y;
  mem.hist = []; mem.escLog = []; mem.esc = null; mem.escN = 0;
  mem.lastBumped = false; mem.bumpEdge = false;
  mem.mode = 'explore'; mem.dockT = 0;
  mem.cur = null;
  mem.drill = null; mem.holdI = 0;
  mem.siteKey = null; mem.siteT0 = 0;
  mem.rLast = []; mem.rCnt = [];
  mem.lastL = 0; mem.lastR = 0; mem.lastAvg = 0; mem.lastMag = 0;
  mem.ticks = 0; mem.t = 0; mem.sampled = 0;
}

function addGrid(mem) {
  mem.gridAdded = true;
  for (const gx of [60, 150, 250, 340]) for (const gy of [60, 150, 250, 340]) {
    mem.hints.push(newHint(gx, gy, 0.25));
  }
}

function nearSkip(mem, x, y) {
  for (const s of mem.skip) if (dist(s.x, s.y, x, y) < 5) return true;
  return false;
}
function addSkip(mem, x, y) { mem.skip.push({ x: x, y: y }); }

function inBad(mem, x, y) {
  for (const z of mem.bad) if (dist(z.x, z.y, x, y) < z.r + 2) return true;
  return false;
}

function markNear(mem, x, y, r) {
  for (const h of mem.hints) if (dist(h.x, h.y, x, y) < r) h.done = true;
}
function markSampled(mem, x, y) {
  for (const h of mem.hints) if (dist(h.x, h.y, x, y) < 12) { h.done = true; h.dead = true; }
}

function updatePos(obs, mem) {
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.frozen++;
  else { mem.frozen = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  mem.gpsFrozen = mem.frozen > 25 && Math.abs(mem.lastAvg) > 0.1;
  if (mem.gpsFrozen) {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
    mem.px += v * 0.1 * Math.cos(mem.hd * D2R);
    mem.py += v * 0.1 * Math.sin(mem.hd * D2R);
  } else {
    mem.px = obs.x; mem.py = obs.y;
  }
}

// heading = compass + bias; bias learned from GPS track on straight forward runs
function updateHeading(obs, mem, o) {
  const straight = mem.lastL > 0.15 && mem.lastR > 0.15 &&
    Math.abs(mem.lastL - mem.lastR) < 0.12 && !mem.gpsFrozen && !mem.esc;
  if (straight) {
    if (!mem.ref) mem.ref = { x: o.x, y: o.y };
    else if (dist(mem.ref.x, mem.ref.y, o.x, o.y) >= 8) {
      const g = Math.atan2(o.y - mem.ref.y, o.x - mem.ref.x) * R2D;
      const e = clamp(wrap(g - wrap((obs.heading || 0) + mem.bias)), -20, 20);
      mem.bias = wrap(mem.bias + 0.25 * e);
      mem.ref = { x: o.x, y: o.y };
    }
  } else {
    mem.ref = null;
  }
  mem.hd = wrap((obs.heading || 0) + mem.bias);
}

function readRays(obs, mem) {
  const r = obs.rays || [];
  const moving = Math.abs(mem.lastAvg) > 0.15;
  const d = [];
  for (let i = 0; i < 9; i++) {
    let v = Number(r[i]);
    if (!(v > 0)) v = 15;
    if (v > 15) v = 15;
    if (moving) {
      if (mem.rLast[i] === v) mem.rCnt[i] = (mem.rCnt[i] || 0) + 1;
      else { mem.rCnt[i] = 0; mem.rLast[i] = v; }
    }
    if ((mem.rCnt[i] || 0) > 100) v = 15; // sensor looks stuck
    d.push(v);
  }
  return d;
}

// a in degrees, positive = target to the left
function steer(a, v) {
  const ae = Math.abs(a);
  if (ae > 50) {
    const s = a > 0 ? 1 : -1;
    return mk(-0.3 * s, 0.3 * s, false);
  }
  const vv = Math.max(0.2, v * (1 - ae / 120));
  const st = clamp(0.0025 * a, -0.12, 0.12);
  return mk(vv - st, vv + st, false);
}

function openSide(d) {
  const L = Math.min(d[5], d[6], d[7], d[8]);
  const R = Math.min(d[0], d[1], d[2], d[3]);
  return L >= R ? 1 : -1;
}

function freeAt(d, i) {
  const r = d[i];
  const lo = i > 0 ? d[i - 1] : r;
  const hi = i < 8 ? d[i + 1] : r;
  return r >= 3 && lo >= 2 && hi >= 2;
}

function pickDir(d, tb) {
  let best = -1, bs = 1e9, near = -1, ns = 1e9;
  for (let i = 0; i < 9; i++) {
    const s = Math.abs(ANG[i] - tb);
    if (s < ns) { ns = s; near = i; }
    if (!freeAt(d, i)) continue;
    if (s < bs) { bs = s; best = i; }
  }
  if (best < 0) return null;
  if (near >= 0 && ns <= 10 && freeAt(d, near)) return tb;
  return ANG[best];
}

function avoid(mem, d, tb, v) {
  const f = Math.min(d[3], d[4], d[5]);
  const vv = f < 4 ? v * clamp((f - 1) / 3, 0.3, 1) : v;
  const a = pickDir(d, tb);
  if (a === null) {
    const s = openSide(d);
    return mk(-0.3 * s, 0.3 * s, false);
  }
  return steer(a, vv);
}

function driveTo(o, mem, d, tx, ty, v, stopR) {
  const dd = dist(o.x, o.y, tx, ty);
  if (dd <= stopR) return zero();
  const tb = wrap(Math.atan2(ty - o.y, tx - o.x) * R2D - mem.hd);
  return avoid(mem, d, tb, clamp(0.15 + 0.15 * dd, 0.2, v));
}

function siteWorld(o, mem, s) {
  const a = (mem.hd + s.bearing) * D2R;
  return { x: o.x + s.distance * Math.cos(a), y: o.y + s.distance * Math.sin(a) };
}

function startDrill(o, mem, sw) {
  mem.drill = { x: o.x, y: o.y, sx: sw.x, sy: sw.y, t0: mem.ticks };
  mem.holdI = 0;
  return mk(0, 0, true);
}

function siteStep(o, obs, mem, d, s, sw) {
  const sp = (Math.abs(obs.wheelLeft || 0) + Math.abs(obs.wheelRight || 0)) / 2;
  if (s.distance <= 1.3) {
    if (sp < 0.12) return startDrill(o, mem, sw);
    return zero();
  }
  const v = clamp(0.15 + 0.1 * s.distance, 0.2, 0.3);
  if (s.distance < 3) return steer(s.bearing, v);
  return avoid(mem, d, s.bearing, v);
}

function drillStep(o, obs, mem) {
  const dr = mem.drill;
  const el = typeof obs.drilling === 'number' ? obs.drilling : (mem.ticks - dr.t0) * 0.1;
  const avg = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  if (el >= 6.3) {
    mem.drill = null; mem.holdI = 0; mem.sampled++;
    addSkip(mem, dr.sx, dr.sy);
    markSampled(mem, dr.sx, dr.sy);
    return zero();
  }
  if (dist(o.x, o.y, dr.x, dr.y) > 2.5 || mem.ticks - dr.t0 > 150) {
    mem.drill = null; mem.holdI = 0;
    addSkip(mem, dr.sx, dr.sy);
    return zero();
  }
  mem.holdI = clamp(mem.holdI - 0.1 * avg, -0.3, 0.3);
  const c = clamp(mem.holdI - 2 * avg, -0.3, 0.3);
  return mk(c, c, true);
}

function pushScience(o, obs, mem) {
  if (!(obs.science > 1.5) || obs.site || mem.pushed >= 6) return;
  for (const h of mem.hints) if (!h.done && dist(h.x, h.y, o.x, o.y) < 10) return;
  if (nearSkip(mem, o.x, o.y)) return;
  mem.hints.push(newHint(o.x, o.y, Math.max(0.3, obs.science * 3)));
  mem.pushed++;
}

function pickTarget(o, mem) {
  for (let pass = 0; pass < 2; pass++) {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.done || h.bad >= 2 || inBad(mem, h.x, h.y)) continue;
      const dd = dist(o.x, o.y, h.x, h.y);
      const s = h.est / (dd + 40);
      if (s > bs) { bs = s; best = h; }
    }
    if (best) return best;
    if (!mem.gridAdded) { addGrid(mem); continue; }
    if (mem.cycles >= 2) return null;
    for (const h of mem.hints) if (!h.dead) { h.done = false; h.bad = 0; }
    mem.bad = [];
    mem.cycles++;
  }
  return null;
}

function lawnPts(o, c) {
  const pts = LAWN.map(p => ({ x: clamp(c.x + p[0], 3, 397), y: clamp(c.y + p[1], 3, 397) }));
  let k = 0, best = 1e9;
  for (let i = 0; i < 4; i++) {
    const dd = dist(o.x, o.y, pts[i].x, pts[i].y);
    if (dd < best) { best = dd; k = i; }
  }
  return [pts[k], pts[(k + 1) % 4], pts[(k + 2) % 4], pts[(k + 3) % 4]];
}

function runTarget(o, obs, mem, d) {
  let h = mem.cur;
  if (!h || h.done) {
    h = pickTarget(o, mem);
    mem.cur = h;
    if (!h) return null;
    h.arrived = false; h.wps = []; h.wi = 0; h.t0 = mem.ticks;
  }
  if (mem.ticks - h.t0 > 1500) { h.done = true; mem.cur = null; return null; }
  if (!h.arrived) {
    if (dist(o.x, o.y, h.x, h.y) < 3) {
      h.arrived = true;
      h.wps = lawnPts(o, h);
      h.wi = 0;
      h.lt0 = mem.ticks;
    } else {
      return driveTo(o, mem, d, h.x, h.y, CRUISE, 2.5);
    }
  }
  if (h.wi >= h.wps.length || mem.ticks - h.lt0 > 900) {
    h.done = true;
    markNear(mem, h.x, h.y, 10);
    mem.cur = null;
    return null;
  }
  const w = h.wps[h.wi];
  if (dist(o.x, o.y, w.x, w.y) < 1.5) { h.wi++; return zero(); }
  return driveTo(o, mem, d, w.x, w.y, CRUISE, 1.0);
}

function deliverStep(o, obs, mem, d, dB) {
  const b = obs.beacon;
  const haveB = !!(b && b.distance <= 20);
  const dd = haveB ? b.distance : dB;
  if (dd <= 2.2) {
    mem.dockT++;
    if (mem.dockT > 50) { mem.mode = 'explore'; mem.dockT = 0; }
    return zero();
  }
  mem.dockT = 0;
  if (haveB) return avoid(mem, d, b.bearing, clamp(0.15 + 0.12 * dd, 0.2, CRUISE));
  return driveTo(o, mem, d, mem.base.x, mem.base.y, CRUISE, 2.0);
}

function startEscape(o, mem, d) {
  const t = mem.t;
  mem.escLog = mem.escLog.filter(e => t - e.t < 150);
  let near = 0;
  for (const e of mem.escLog) if (dist(e.x, e.y, o.x, o.y) < 8) near++;
  mem.escLog.push({ x: o.x, y: o.y, t: t });
  mem.escN++;
  let dir = openSide(d);
  if (near >= 2) dir = -dir;
  if (near >= 1) {
    mem.bad.push({ x: o.x, y: o.y, r: 8 });
    if (mem.cur) { mem.cur.bad = 2; mem.cur = null; }
  }
  mem.esc = { ph: 0, n: 0, dir: dir, p: clamp(0.45 + 0.15 * Math.min(near, 3), 0.45, 0.9) };
  mem.hist = [];
}

function escStep(mem) {
  const e = mem.esc;
  e.n++;
  if (e.ph === 0) {
    if (e.n >= 12) { e.ph = 1; e.n = 0; }
    return mk(-e.p, -e.p, false);
  }
  if (e.n >= 10) { mem.esc = null; return zero(); }
  return mk(-e.p * e.dir, e.p * e.dir, false);
}

function stuckNow(o, mem) {
  if (mem.gpsFrozen) return false;
  const n = mem.hist.length;
  if (n >= 40 && Math.abs(mem.lastAvg) > 0.15) {
    const p = mem.hist[n - 40];
    if (dist(o.x, o.y, p.x, p.y) < 0.5) return true;
  }
  if (n >= 80 && mem.lastMag > 0.15) {
    const p = mem.hist[n - 80];
    if (dist(o.x, o.y, p.x, p.y) < 1.0) return true;
  }
  return false;
}

function decide(o, obs, mem, d) {
  const carried = obs.carried || 0;
  const t = mem.t;
  const tl = typeof obs.timeLeft === 'number' ? obs.timeLeft : 1200 - t;
  const dB = dist(o.x, o.y, mem.base.x, mem.base.y);

  if (mem.drill) return drillStep(o, obs, mem);
  if (mem.esc) return escStep(mem);
  if (mem.bumpEdge) { startEscape(o, mem, d); return escStep(mem); }
  if (stuckNow(o, mem)) { startEscape(o, mem, d); return escStep(mem); }

  if (mem.mode === 'explore' && carried > 0) {
    const urgent = carried >= mem.cap || tl < dB / 0.5 + 90 || (obs.battery || 1) < 0.15;
    const near = (carried >= 2 && dB < 35) || (carried >= 1 && dB < 10);
    if (urgent || near) { mem.mode = 'deliver'; mem.dockT = 0; }
  }
  if (mem.mode === 'deliver') {
    if (carried === 0) { mem.mode = 'explore'; mem.dockT = 0; }
    else return deliverStep(o, obs, mem, d, dB);
  }

  const s = obs.site;
  if (s && carried < mem.cap) {
    const sw = siteWorld(o, mem, s);
    if (!nearSkip(mem, sw.x, sw.y)) {
      if (!mem.siteKey || dist(mem.siteKey.x, mem.siteKey.y, sw.x, sw.y) > 8) {
        mem.siteKey = sw; mem.siteT0 = t;
      }
      if (t - mem.siteT0 < 60) return siteStep(o, obs, mem, d, s, sw);
      addSkip(mem, sw.x, sw.y);
    }
  }

  pushScience(o, obs, mem);

  const r = runTarget(o, obs, mem, d);
  if (r) return r;
  if (carried > 0) {
    mem.mode = 'deliver'; mem.dockT = 0;
    return deliverStep(o, obs, mem, d, dB);
  }
  return zero();
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.ticks++;
  mem.t = typeof obs.t === 'number' ? obs.t : mem.ticks * 0.1;
  mem.bumpEdge = !!obs.bumped && !mem.lastBumped;
  mem.lastBumped = !!obs.bumped;

  updatePos(obs, mem);
  const o = { x: mem.px, y: mem.py };
  mem.hist.push({ x: o.x, y: o.y });
  if (mem.hist.length > 80) mem.hist.shift();

  updateHeading(obs, mem, o);
  const d = readRays(obs, mem);
  const cmd = decide(o, obs, mem, d);
  mem.lastL = cmd.left; mem.lastR = cmd.right;
  mem.lastAvg = (cmd.left + cmd.right) / 2;
  mem.lastMag = Math.abs(cmd.left) + Math.abs(cmd.right);
  return mk(cmd.left, cmd.right, cmd.drill);
}

function act(obs, mem) {
  try {
    return step(obs, mem);
  } catch (e) {
    return zero();
  }
}

const D2R = Math.PI / 180;
const R2D = 180 / Math.PI;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const CRUISE = 0.4;
const LAWN = [[-12, -7], [12, -7], [12, 7], [-12, 7]];

function wrap(a) { while (a > 180) a -= 360; while (a < -180) a += 360; return a; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function dist(ax, ay, bx, by) { return Math.hypot(bx - ax, by - ay); }
function mk(l, r, drill) { return { left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!drill }; }
function zero() { return mk(0, 0, false); }

function newHint(x, y, est) {
  return { x: x, y: y, est: est, done: false, dead: false, bad: 0, arrived: false,
    t0: 0, lim: 200, wps: [], wi: 0, lt0: 0 };
}

function init(obs, mem) {
  const m = obs.mission || {};
  mem.init = true;
  mem.base = m.base ? { x: m.base.x, y: m.base.y } : { x: obs.x || 200, y: obs.y || 200 };
  mem.cap = m.capacity || 5;
  mem.hints = (m.hints || []).map(h =>
    newHint(h.x, h.y, typeof h.estimate === 'number' ? Math.max(0.05, h.estimate) : 1));
  mem.gridAdded = false; mem.cycles = 0; mem.pushed = 0;
  mem.skip = []; mem.bad = [];
  mem.bias = 0; mem.ref = null; mem.hd = obs.heading || 0;
  mem.lastGx = NaN; mem.lastGy = NaN; mem.frozen = 0; mem.gpsFrozen = false;
  mem.px = obs.x || mem.base.x; mem.py = obs.y || mem.base.y;
  mem.hist = []; mem.escLog = []; mem.esc = null; mem.escN = 0;
  mem.lastBumped = false; mem.bumpEdge = false;
  mem.mode = 'explore'; mem.dockT = 0;
  mem.cur = null;
  mem.drill = null; mem.holdI = 0;
  mem.site = null;
  mem.rLast = []; mem.rCnt = [];
  mem.lastL = 0; mem.lastR = 0; mem.lastAvg = 0; mem.lastMag = 0;
  mem.ticks = 0; mem.t = 0; mem.sampled = 0;
  mem.anchor = null;
}

function addGrid(mem) {
  mem.gridAdded = true;
  for (const gx of [60, 150, 250, 340]) for (const gy of [60, 150, 250, 340]) {
    mem.hints.push(newHint(gx, gy, 0.25));
  }
}

function skipAt(mem, x, y) {
  for (const s of mem.skip) if (dist(s.x, s.y, x, y) < 5) return s;
  return null;
}
function nearSkip(mem, x, y) { const s = skipAt(mem, x, y); return !!s && s.n >= 2; }
function addSkip(mem, x, y, inc) {
  const s = skipAt(mem, x, y);
  if (s) s.n += inc; else mem.skip.push({ x: x, y: y, n: inc });
}

function inBad(mem, x, y) {
  for (const z of mem.bad) if (dist(z.x, z.y, x, y) < z.r + 2) return true;
  return false;
}
function markNear(mem, x, y, r) {
  for (const h of mem.hints) if (dist(h.x, h.y, x, y) < r) h.done = true;
}
function markSampled(mem, x, y) {
  for (const h of mem.hints) if (dist(h.x, h.y, x, y) < 12) { h.done = true; h.dead = true; }
}

function updatePos(obs, mem) {
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.frozen++;
  else { mem.frozen = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  mem.gpsFrozen = mem.frozen > 25 && Math.abs(mem.lastAvg) > 0.1;
  if (mem.gpsFrozen) {
    const v = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
    mem.px += v * 0.1 * Math.cos(mem.hd * D2R);
    mem.py += v * 0.1 * Math.sin(mem.hd * D2R);
  } else {
    mem.px = obs.x; mem.py = obs.y;
  }
}

function updateHeading(obs, mem, o) {
  const straight = mem.lastL > 0.15 && mem.lastR > 0.15 &&
    Math.abs(mem.lastL - mem.lastR) < 0.12 && !mem.gpsFrozen && !mem.esc;
  if (straight) {
    if (!mem.ref) mem.ref = { x: o.x, y: o.y };
    else if (dist(mem.ref.x, mem.ref.y, o.x, o.y) >= 8) {
      const g = Math.atan2(o.y - mem.ref.y, o.x - mem.ref.x) * R2D;
      const e = clamp(wrap(g - wrap((obs.heading || 0) + mem.bias)), -20, 20);
      mem.bias = wrap(mem.bias + 0.25 * e);
      mem.ref = { x: o.x, y: o.y };
    }
  } else {
    mem.ref = null;
  }
  mem.hd = wrap((obs.heading || 0) + mem.bias);
}

function readRays(obs, mem) {
  const r = obs.rays || [];
  const moving = Math.abs(mem.lastAvg) > 0.15;
  const d = [];
  for (let i = 0; i < 9; i++) {
    let v = Number(r[i]);
    if (!(v > 0)) v = 15;
    if (v > 15) v = 15;
    if (moving) {
      if (mem.rLast[i] === v) mem.rCnt[i] = (mem.rCnt[i] || 0) + 1;
      else { mem.rCnt[i] = 0; mem.rLast[i] = v; }
    }
    if ((mem.rCnt[i] || 0) > 100) v = 15;
    d.push(v);
  }
  return d;
}

// a in degrees, positive = target to the left
function steer(a, v) {
  const ae = Math.abs(a);
  if (ae > 50) {
    const s = a > 0 ? 1 : -1;
    return mk(-0.3 * s, 0.3 * s, false);
  }
  const vv = Math.max(0.2, v * (1 - ae / 120));
  const st = clamp(0.0025 * a, -0.12, 0.12);
  return mk(vv - st, vv + st, false);
}

function openSide(d) {
  const L = Math.min(d[5], d[6], d[7], d[8]);
  const R = Math.min(d[0], d[1], d[2], d[3]);
  return L >= R ? 1 : -1;
}

function freeAt(d, i) {
  const r = d[i];
  const lo = i > 0 ? d[i - 1] : r;
  const hi = i < 8 ? d[i + 1] : r;
  return r >= 3 && lo >= 2 && hi >= 2;
}

function pickDir(d, tb) {
  let best = -1, bs = 1e9, near = -1, ns = 1e9;
  for (let i = 0; i < 9; i++) {
    const s = Math.abs(ANG[i] - tb);
    if (s < ns) { ns = s; near = i; }
    if (!freeAt(d, i)) continue;
    if (s < bs) { bs = s; best = i; }
  }
  if (best < 0) return null;
  if (near >= 0 && ns <= 10 && freeAt(d, near)) return tb;
  return ANG[best];
}

function avoid(mem, d, tb, v) {
  const f = Math.min(d[3], d[4], d[5]);
  const vv = f < 4 ? v * clamp((f - 1) / 3, 0.3, 1) : v;
  const a = pickDir(d, tb);
  if (a === null) {
    const s = openSide(d);
    return mk(-0.3 * s, 0.3 * s, false);
  }
  return steer(a, vv);
}

function driveTo(o, mem, d, tx, ty, v, stopR) {
  const dd = dist(o.x, o.y, tx, ty);
  if (dd <= stopR) return zero();
  const tb = wrap(Math.atan2(ty - o.y, tx - o.x) * R2D - mem.hd);
  return avoid(mem, d, tb, clamp(0.15 + 0.15 * dd, 0.2, v));
}

function siteWorld(o, mem, s) {
  const a = (mem.hd + s.bearing) * D2R;
  return { x: o.x + s.distance * Math.cos(a), y: o.y + s.distance * Math.sin(a) };
}

function startDrill(o, mem, sw) {
  mem.drill = { x: o.x, y: o.y, sx: sw.x, sy: sw.y, t0: mem.ticks };
  mem.holdI = 0;
  return mk(0, 0, true);
}

function siteStep(o, obs, mem, d, s, sw) {
  const sp = (Math.abs(obs.wheelLeft || 0) + Math.abs(obs.wheelRight || 0)) / 2;
  if (s.distance <= 1.4) {
    if (sp < 0.12) return startDrill(o, mem, sw);
    if (sp > 0.35) return mk(-0.2, -0.2, false);
    return zero();
  }
  if (s.distance < 3) return steer(s.bearing, 0.2);
  return avoid(mem, d, s.bearing, 0.25);
}

function drillStep(o, obs, mem) {
  const dr = mem.drill;
  const age = mem.ticks - dr.t0;
  const el = typeof obs.drilling === 'number' ? obs.drilling : age * 0.1;
  const avg = ((obs.wheelLeft || 0) + (obs.wheelRight || 0)) / 2;
  if (el >= 6.3) {
    mem.drill = null; mem.holdI = 0; mem.sampled++;
    addSkip(mem, dr.sx, dr.sy, 99);
    markSampled(mem, dr.sx, dr.sy);
    return zero();
  }
  const moved = dist(o.x, o.y, dr.x, dr.y);
  if (moved > 3 || age > 250 || (age > 40 && el < 0.05)) {
    mem.drill = null; mem.holdI = 0;
    addSkip(mem, dr.sx, dr.sy, 1);
    return zero();
  }
  const c = Math.abs(avg) < 0.03 ? 0 : clamp(-0.3 * avg, -0.2, 0.2);
  return mk(c, c, true);
}

function pushScience(o, obs, mem) {
  if (!(obs.science > 1.5) || obs.site || mem.pushed >= 6) return;
  for (const h of mem.hints) if (!h.done && dist(h.x, h.y, o.x, o.y) < 10) return;
  if (nearSkip(mem, o.x, o.y)) return;
  mem.hints.push(newHint(o.x, o.y, Math.max(0.3, obs.science * 3)));
  mem.pushed++;
}

function pickTarget(o, mem) {
  for (let pass = 0; pass < 2; pass++) {
    let best = null, bs = -1;
    for (const h of mem.hints) {
      if (h.done || h.bad >= 2 || inBad(mem, h.x, h.y)) continue;
      const dd = dist(o.x, o.y, h.x, h.y);
      const s = h.est / (dd + 40);
      if (s > bs) { bs = s; best = h; }
    }
    if (best) return best;
    if (!mem.gridAdded) { addGrid(mem); continue; }
    if (mem.cycles >= 2) return null;
    for (const h of mem.hints) if (!h.dead) { h.done = false; h.bad = 0; }
    mem.bad = [];
    mem.cycles++;
  }
  return null;
}

function lawnPts(o, c) {
  const pts = LAWN.map(p => ({ x: clamp(c.x + p[0], 3, 397), y: clamp(c.y + p[1], 3, 397) }));
  let k = 0, best = 1e9;
  for (let i = 0; i < 4; i++) {
    const dd = dist(o.x, o.y, pts[i].x, pts[i].y);
    if (dd < best) { best = dd; k = i; }
  }
  return [pts[k], pts[(k + 1) % 4], pts[(k + 2) % 4], pts[(k + 3) % 4]];
}

function runTarget(o, obs, mem, d) {
  let h = mem.cur;
  if (!h || h.done) {
    h = pickTarget(o, mem);
    mem.cur = h;
    if (!h) return null;
    h.arrived = false; h.wps = []; h.wi = 0;
    h.t0 = mem.t; h.lt0 = mem.t;
    h.lim = 60 + 1.5 * dist(o.x, o.y, h.x, h.y);
  }
  if (!h.arrived) {
    if (dist(o.x, o.y, h.x, h.y) < 3) {
      h.arrived = true;
      h.wps = lawnPts(o, h);
      h.wi = 0;
      h.lt0 = mem.t;
    } else {
      if (mem.t - h.t0 > h.lim) { h.done = true; mem.cur = null; return null; }
      return driveTo(o, mem, d, h.x, h.y, CRUISE, 2.5);
    }
  }
  if (h.wi >= h.wps.length || mem.t - h.lt0 > 130) {
    h.done = true;
    markNear(mem, h.x, h.y, 10);
    mem.cur = null;
    return null;
  }
  const w = h.wps[h.wi];
  if (dist(o.x, o.y, w.x, w.y) < 1.5) { h.wi++; return zero(); }
  return driveTo(o, mem, d, w.x, w.y, CRUISE, 1.0);
}

function deliverStep(o, obs, mem, d, dB) {
  const b = obs.beacon;
  const haveB = !!(b && b.distance <= 20);
  const dd = haveB ? b.distance : dB;
  if (dd <= 2.2) {
    mem.dockT++;
    if (mem.dockT > 50) { mem.mode = 'explore'; mem.dockT = 0; }
    return zero();
  }
  mem.dockT = 0;
  if (haveB) return avoid(mem, d, b.bearing, clamp(0.15 + 0.12 * dd, 0.2, CRUISE));
  return driveTo(o, mem, d, mem.base.x, mem.base.y, CRUISE, 2.0);
}

function startEscape(o, mem, d) {
  const t = mem.t;
  mem.escLog = mem.escLog.filter(e => t - e.t < 150);
  let near = 0;
  for (const e of mem.escLog) if (dist(e.x, e.y, o.x, o.y) < 8) near++;
  mem.escLog.push({ x: o.x, y: o.y, t: t });
  mem.escN++;
  let dir = openSide(d);
  if (near >= 2) dir = -dir;
  if (near >= 1) {
    mem.bad.push({ x: o.x, y: o.y, r: 8 });
    if (mem.cur) { mem.cur.bad += 2; mem.cur.done = true; mem.cur = null; }
  }
  mem.esc = { ph: 0, n: 0, dir: dir, p: near >= 2 ? 0.5 : 0.35 };
  mem.hist = [];
  mem.anchor = null;
}

function escStep(mem) {
  const e = mem.esc;
  e.n++;
  if (e.ph === 0) {
    if (e.n >= 15) { e.ph = 1; e.n = 0; }
    return mk(-e.p, -e.p, false);
  }
  if (e.n >= 12) { mem.esc = null; return zero(); }
  return mk(-e.p * e.dir, e.p * e.dir, false);
}

function stuckNow(o, mem) {
  if (mem.gpsFrozen) return false;
  const n = mem.hist.length;
  if (n >= 40 && Math.abs(mem.lastAvg) > 0.15) {
    const p = mem.hist[n - 40];
    if (dist(o.x, o.y, p.x, p.y) < 0.5) return true;
  }
  if (n >= 80 && mem.lastMag > 0.15) {
    const p = mem.hist[n - 80];
    if (dist(o.x, o.y, p.x, p.y) < 1.0) return true;
  }
  return false;
}

// true when the rover has moved less than 5 m over the last 45 s
function watchdog(o, mem) {
  if (!mem.anchor) { mem.anchor = { x: o.x, y: o.y, t: mem.t }; return false; }
  if (dist(o.x, o.y, mem.anchor.x, mem.anchor.y) > 5) {
    mem.anchor = { x: o.x, y: o.y, t: mem.t };
    return false;
  }
  if (mem.t - mem.anchor.t > 45) {
    mem.anchor = { x: o.x, y: o.y, t: mem.t };
    return true;
  }
  return false;
}

function decide(o, obs, mem, d) {
  const carried = obs.carried || 0;
  const t = mem.t;
  const tl = typeof obs.timeLeft === 'number' ? obs.timeLeft : 1200 - t;
  const dB = dist(o.x, o.y, mem.base.x, mem.base.y);

  if (mem.drill) return drillStep(o, obs, mem);
  if (mem.esc) return escStep(mem);
  if (mem.bumpEdge) { startEscape(o, mem, d); return escStep(mem); }
  if (stuckNow(o, mem)) { startEscape(o, mem, d); return escStep(mem); }

  if (watchdog(o, mem)) {
    if (mem.mode === 'explore' && mem.cur) {
      mem.cur.done = true; mem.cur.bad += 2; mem.cur = null;
    }
    mem.bad.push({ x: o.x, y: o.y, r: 10 });
    startEscape(o, mem, d);
    return escStep(mem);
  }

  if (mem.mode === 'explore' && carried > 0) {
    const urgent = carried >= mem.cap || tl < dB / 0.5 + 90 || (obs.battery || 1) < 0.15;
    const near = (carried >= 2 && dB < 35) || (carried >= 1 && dB < 10);
    if (urgent || near) { mem.mode = 'deliver'; mem.dockT = 0; }
  }
  if (mem.mode === 'deliver') {
    if (carried === 0) { mem.mode = 'explore'; mem.dockT = 0; }
    else return deliverStep(o, obs, mem, d, dB);
  }

  const s = obs.site;
  if (s && carried < mem.cap) {
    const sw = siteWorld(o, mem, s);
    if (!nearSkip(mem, sw.x, sw.y)) {
      let st = mem.site;
      if (!st || dist(st.x, st.y, sw.x, sw.y) > 6) {
        st = { x: sw.x, y: sw.y, t0: t, best: s.distance, bestT: t };
        mem.site = st;
      }
      if (s.distance < st.best - 0.3) { st.best = s.distance; st.bestT = t; }
      if (t - st.bestT < 20 && t - st.t0 < 80) return siteStep(o, obs, mem, d, s, sw);
      addSkip(mem, st.x, st.y, 2);
      mem.site = null;
    }
  }

  pushScience(o, obs, mem);

  const r = runTarget(o, obs, mem, d);
  if (r) return r;
  if (carried > 0) {
    mem.mode = 'deliver'; mem.dockT = 0;
    return deliverStep(o, obs, mem, d, dB);
  }
  return zero();
}

function step(obs, mem) {
  if (!mem.init) init(obs, mem);
  mem.ticks++;
  mem.t = typeof obs.t === 'number' ? obs.t : mem.ticks * 0.1;
  mem.bumpEdge = !!obs.bumped && !mem.lastBumped;
  mem.lastBumped = !!obs.bumped;

  updatePos(obs, mem);
  const o = { x: mem.px, y: mem.py };
  mem.hist.push({ x: o.x, y: o.y });
  if (mem.hist.length > 80) mem.hist.shift();

  updateHeading(obs, mem, o);
  const d = readRays(obs, mem);
  if (mem.drill || obs.site || mem.esc) mem.anchor = null;
  const cmd = decide(o, obs, mem, d);
  mem.lastL = cmd.left; mem.lastR = cmd.right;
  mem.lastAvg = (cmd.left + cmd.right) / 2;
  mem.lastMag = Math.abs(cmd.left) + Math.abs(cmd.right);
  return mk(cmd.left, cmd.right, cmd.drill);
}

function act(obs, mem) {
  try {
    return step(obs, mem);
  } catch (e) {
    return zero();
  }
}
